export async function POST(req: NextRequest) {
  // KINEO-353A — TODO o corpo roda dentro de um contexto proprio. Duas
  // requisicoes simultaneas na mesma instancia nao se enxergam mais.
  return despacho.run(novoContextoDeDespacho(), async () => {
    const ctx = ctxDespacho()
    const res = await manipularPost(req)
    // A Response REAL — inclusive 402/409/503 vindos do publish/settlement.
    await finalizarDespacho(ctx, res)
    return res
  })
}

async function manipularPost(req: NextRequest) {
  let activeBirthClaim: {
    db: SupabaseClient
    secret: string
    userId: string
    generationId: string
    billingReference: string
    debitConfirmed: boolean
  } | null = null
  let providerSubmissionMayExist = false
  // Unlike providerSubmissionMayExist (also true for a known accepted ID),
  // this records an unbound/unknown paid scene. A null slot alone is NOT
  // evidence of rejection. Publish the distinction inside the signed response.
  let cinematicSubmissionUncertain = false
  // ═══ sprint-assinaturas #14 (04/09) — O CLIQUE QUE MORRE COM A ABA ═══════
  // Medido em produção (14d, externos): 407 cliques em gerar, 25 deles (21
  // pessoas, 19 SEM UM FILME NA VIDA) não deixaram UM ÚNICO registro no
  // servidor — nem claim, nem despacho, nem erro, nem recusa. Não é falha do
  // motor: é a requisição morrendo junto com a aba. Quando tudo vai bem o
  // claim nasce 20s depois do clique (p90 60s), e a MEDIANA de tempo até essas
  // pessoas saírem da tela é de 7 SEGUNDOS — 13 das 25 sumiram em menos de 60s.
  // A casa ficava cega: nenhuma rede de segurança pode resgatar o que nunca
  // existiu. Este par de marcadores é a caixa-preta. O de abertura é gravado
  // ANTES de qualquer trabalho caro (o client admin nasce ~1s depois de a
  // requisição chegar; tudo antes dele é parse e leitura barata) e o de fecho
  // no finally, que roda em TODO caminho de saída — sucesso, 4xx, 5xx e
  // exceção. Aberto e nunca fechado = a função foi morta no meio, e a Fase 5
  // do cron de resgate avisa a pessoa. NÃO muda uma linha de geração.
  let attemptTrace: { db: SupabaseClient; userId: string; generationId: string } | null = null
  let releaseActiveBirthClaim: ((reason: string) => Promise<boolean>) | null = null
  try {
    if (!process.env.FAL_KEY) {
      return NextResponse.json(
        { error: 'Cinematic mode is not configured. Please contact support.' },
        { status: 500 }
      )
    }

    const supabase = createClient()
    const { data: { user } } = await supabase.auth.getUser()
    if (!user) {
      return NextResponse.json({ error: 'You must be signed in.' }, { status: 401 })
    }

    // KINEO-HOLLYWOOD-2026-07-09 — `language` accepted (already sent by the
    // client) so the Hollywood planner knows the input language.
    // KINEO-CHARACTER-LOCK-2026-07-10 — characterId: a saved character (My
    // Characters) whose portrait replaces the generated Hollywood PORTRAIT
    // anchor → the SAME person appears across every video the user makes.
    // KINEO-HOLLYWOOD-HOST-2026-07-13 — two new OPTIONAL fields (absent →
    // byte-identical behavior): `vertical` (the analyze-idea niche, forwarded
    // by the client) pins the SAME narrator persona here and in /api/compose;
    // `brollScenes[].userFootageUrl` (My Footage, same contract as
    // generate-video-fast) is the prepared hook for demo scenes using the
    // user's own clips.
    // KINEO-VERBATIM-SEM-MARCADOR-2026-08-24: `script_mode` ('verbatim'|'ai')
    // e `dry_run` (validador de $0, só contas do fundador) entram no contrato.
    let body: { generationId?: string; prompt?: string; duration?: number; allow_shorter_duration?: boolean; engine?: string; language?: string; vertical?: string; characterId?: string; script_mode?: string; dry_run?: boolean; brollScenes?: Array<{ sceneNumber?: number; brollPrompt?: string; shotType?: string; negativePrompt?: string; userFootageUrl?: string }>; globalStyle?: { mood?: string; lighting?: string; cameraStyle?: string } }
    try {
      body = await req.json()
    } catch {
      return NextResponse.json({ error: 'Invalid request body.' }, { status: 400 })
    }

    // KINEO-FACELESS-2026-08-25 — tag [faceless] no script = filme SEM avatar:
    // desliga a conversão HOOK/PAYOFF-on-camera no planner. A tag é REMOVIDA
    // aqui, antes de tudo (verbatim, fingerprint, narração) — nunca é falada.
    const promptRaw = (body.prompt ?? '').trim()
    const tagFacelessPresente = TAG_FACELESS.test(promptRaw)
    // KINEO-IDEIA-COLADA-2026-09-12 — ideia de 1 clique colada na frente do texto da pessoa não é o tema.
    const intake = stripIdeaPrefix(promptRaw.replace(/\[faceless\]/gi, '').trim())
    if (intake.strippedIdea) await writeServerEvent({ name: 'idea_prefix_stripped', userId: user.id, path: '/api/generate-video-cinematic', metadata: { idea: intake.strippedIdea.slice(0, 80), rest_chars: intake.text.length } })
    let prompt = intake.text // KINEO-EPISODIO-COM-ASSUNTO: `let` — o pedido de continuação ganha o episódio anterior abaixo
    // ═══ KINEO-EPISODIO-COM-ASSUNTO-2026-09-22 — "próximo episódio" recebe o ASSUNTO, não só o gancho (ver generate-video-fast) ═══
    if (isSeriesContinuationPrompt(prompt)) {
      const anterior = await findPreviousEpisode(supabase, user.id, prompt)
      const enriched = enrichSeriesContinuationPrompt(prompt, anterior)
      void writeServerEvent({ name: 'series_continuation_enriched', userId: user.id, path: '/api/generate-video-cinematic', metadata: { found: !!anterior, matched_by: anterior?.matchedBy ?? null, previous_video_id: anterior?.id ?? null, added_chars: enriched.length - prompt.length } })
      prompt = enriched
    }
    // ═══ DIRETOR DE FORMATO — 2026-08-27 ═════════════════════════════════
    // ANTES: `facelessRequested` so era true com a tag `[faceless]` escrita a
    // mao. Nenhum cliente conhece essa tag, entao o padrao de fabrica era
    // APRESENTADOR PARA TODO MUNDO — e o prompt de sistema do planner ainda
    // reforcava (`hostFits=true for documentary/mysteries/history/facts`),
    // com default true no parse. Resultado medido no render 37c8d832: um
    // roteiro de misterio/noticia sobre naufragios da Segunda Guerra ganhou
    // host falando na lente e rostos humanos em cenas de apoio, sem que o
    // roteiro pedisse nada disso.
    // AGORA: o formato e inferido do CONTEUDO. Documentario, misterio,
    // ciencia e noticia nascem faceless; apresentador so por pedido
    // explicito. A tag antiga continua valendo para quem ja a usa.
    // [TRAVA 8.2 — vai do fundador 29/09 'vai pra todas as 4'] KINEO-ESTRELA-DO-FILME-2026-09-29 — com a estrela o filme MOSTRA a pessoa:
    // documentary_faceless vira character_story (pessoa muda em cena). Pedido de estrela recusado mais abaixo volta antes de [KINEO-ESTRELA-DO-FILME-2026-09-29]
    // qualquer trabalho; sem `estrela` no corpo, formatoComEstrela devolve a decisão de sempre (o mesmo objeto). [KINEO-ESTRELA-DO-FILME-2026-09-29]
    const formatoVisual = formatoComEstrela(decidirFormato(prompt, tagFacelessPresente), estrelaPedida((body as { estrela?: unknown }).estrela)) // KINEO-ESTRELA-DO-FILME-2026-09-29
    // KINEO-ROMANCE-ADULTO-2026-10-13 — pedido romântico (lib/cinematic/romanceGuard; só o texto do CLIENTE): mostra as duas pessoas
    // KINEO-ROMANCE-ADULTO-2026-10-13 — (character_story, nunca o faceless que apagava "man/woman"); a tag [faceless] e o apresentador pedido vencem.
    const romanceAdulto = decidirRomanceAdulto(prompt) // KINEO-ROMANCE-ADULTO-2026-10-13
    if (romanceAdulto.ativo && !tagFacelessPresente && formatoVisual.modo === 'documentary_faceless') Object.assign(formatoVisual, { modo: 'character_story', motivo: `${romanceAdulto.motivo}: as duas pessoas aparecem, mudas, adultas` }) // KINEO-ROMANCE-ADULTO-2026-10-13
    // KINEO-META95-PERSONAGEM-2010 — a folha de personagem pedida (conta interna + formatFlags "personagem"; PERSONAGEM_PUBLIC=false) e um roteiro COM personagem: o filme mostra o personagem
    // KINEO-META95-PERSONAGEM-2010 — (character_story, como a Estrela e o romance fazem) — o faceless apagava o protagonista (C5 do diagnóstico). Cliente que manda o campo: nada muda.
    const personagemPedido = PERSONAGEM_PUBLIC || (isInternalEmail(user.email) && pedidoDePersonagem((body as { formatFlags?: unknown; format_flags?: unknown }).formatFlags ?? (body as { format_flags?: unknown }).format_flags)) // KINEO-META95-PERSONAGEM-2010
    if (personagemPedido && !tagFacelessPresente && formatoVisual.modo === 'documentary_faceless' && elencoDeterministico(prompt).length > 0) Object.assign(formatoVisual, { modo: 'character_story', motivo: `folha de personagem: o roteiro tem personagem nomeado ou protagonista (antes: ${formatoVisual.motivo})` }) // KINEO-META95-PERSONAGEM-2010
    const facelessRequested = !permiteApresentador(formatoVisual.modo)
    console.log(`[formato] visual_mode=${formatoVisual.modo} — ${formatoVisual.motivo}`)
    if (!prompt) {
      return NextResponse.json({ error: 'Prompt is required.' }, { status: 400 })
    }
    if (prompt.length > 12000) {
      return NextResponse.json({ error: 'Prompt is too long.' }, { status: 400 })
    }
    // ═══ KINEO-MONUMENTO-2026-10-13 — LUGAR REAL QUE O PÚBLICO RECONHECE (lib/cinematic/monumentoReal.ts) ═══ [KINEO-MONUMENTO-2026-10-13]
    // Parceiro Logan, 11/10 21:01–21:07 UTC: 3 pedidos de "drone tour" do Palácio de Versalhes com linhas "Style:" e "Camera:" [KINEO-MONUMENTO-2026-10-13]
    // (617–669 palavras, modo "as is") recusados aqui embaixo como plano de clipe (shot_spec_detected keyed_shot_spec). [KINEO-MONUMENTO-2026-10-13]
    // Plano sobre lugar real é pedido de FILME: as linhas de plano viram uma linha de direção visual, o pedido ganha [KINEO-MONUMENTO-2026-10-13]
    // "The story of <lugar>, told as a narrated cinematic tour", e o modo vira IA (a narradora nunca lê o plano). [KINEO-MONUMENTO-2026-10-13]
    // Plano SEM lugar real segue recusado como antes. `lugarDoPedido` também ancora o lugar nos prompts das cenas, abaixo. [KINEO-MONUMENTO-2026-10-13]
    const lugarDoPedido = lugarPrincipal(prompt) // KINEO-MONUMENTO-2026-10-13
    if (lugarDoPedido && detectShotSpec(prompt).isShotSpec) { // KINEO-MONUMENTO-2026-10-13
      const planoOriginal = detectShotSpec(prompt) // KINEO-MONUMENTO-2026-10-13
      prompt = pedidoDeTourNarrado(prompt, lugarDoPedido) // KINEO-MONUMENTO-2026-10-13
      body.script_mode = 'ai' // KINEO-MONUMENTO-2026-10-13
      void writeServerEvent({ name: 'shot_spec_place_admitted', userId: user.id, path: '/api/generate-video-cinematic', metadata: { place: lugarDoPedido.id, place_name: lugarDoPedido.nome, curated: lugarDoPedido.curado, reason: planoOriginal.reason, keys: planoOriginal.keys.slice(0, 6), prompt_length: prompt.length, version: 'monumento_v1' } }) // KINEO-MONUMENTO-2026-10-13
    } // KINEO-MONUMENTO-2026-10-13
    // ═══ KINEO-TRES-MODOS-2026-09-11 — PLANO COLADO NÃO VIRA NARRAÇÃO ══════
    // Render 802f024e (11/09): a pessoa colou um plano JSON (clip/duration/
    // action/camera/vfx) e a narradora LEU O JSON em voz alta. Um prompt de
    // plano só entra pelo modo clipe (/api/generate-clip). Aqui: 422 antes de
    // qualquer débito, com a saída certa na mensagem.
    {
      const shot = detectShotSpec(prompt)
      if (shot.isShotSpec) {
        await writeServerEvent({ name: 'shot_spec_detected', userId: user.id, path: '/api/generate-video-cinematic', metadata: { reason: shot.reason, keys: shot.keys, seconds: shot.seconds, prompt_length: prompt.length } })
        return NextResponse.json({
          error: `This looks like a shot plan (${shot.keys.slice(0, 4).join(', ')}), not a story to narrate. Kineo would read it out loud over the footage. Use "Just this clip (no narration)" in Studio to render exactly this shot (${shot.seconds} s), or write the story you want narrated.`,
          reason: 'shot_spec_detected', clip_seconds: shot.seconds, clip_prompt: shot.prompt.slice(0, 600), retryable: false,
        }, { status: 422 })
      }
    }
    const generationId = typeof body.generationId === 'string' ? body.generationId.trim() : ''
    if (!validCinematicGenerationId(generationId)) {
      return NextResponse.json(
        { error: 'This AI generation is missing its safety id. Please start it again.' },
        { status: 400 },
      )
    }

    // KINEO-DISPATCH-ENTRY-2026-09-05 — irmão do evento do /generate-video-fast.
    // Prova de SERVIDOR de que este POST chegou, emitida ANTES de qualquer
    // trabalho caro e antes do claim. É o par que faltava do
    // `cinematic_dispatch_result`: sem ele, um despacho que morre antes do
    // planner é indistinguível de um POST que nunca saiu do navegador — os dois
    // deixam o mesmo silêncio. Carrega o `generation_id` justamente para casar
    // com o `cinematic_dispatch_result` do mesmo despacho.
    void writeServerEvent({
      name: 'generation_dispatch_received',
      userId: user.id,
      path: '/api/generate-video-cinematic',
      metadata: {
        engine: 'cinematic',
        generation_id: generationId,
        prompt_length: prompt.length,
        requested_duration: Number((body as { duration?: unknown }).duration) || null,
        // KINEO-VIGIA-FORMATO-2026-09-11 — o quadro pedido nunca era gravado em
        // evento nenhum; sem isto 'formato respeitado' nao se mede no banco.
        requested_aspect: normalizeAspect((body as { aspect?: unknown }).aspect),
      },
    })

    // sprint-v1v4 #20 — `let` porque o guard de narracao abaixo pode trocar um
    // alvo FANTASMA (duracao que nenhum botao da tela oferece, tipicamente 45)
    // pela maior duracao real que a narracao enche, em vez de recusar a pessoa.
    // KINEO-MULTIFORMATO-2026-09-02 — enquadramento pedido. Ausente = '9:16'
    // (todo o comportamento anterior). Viaja para: payload da fal
    // (`aspect_ratio`), prompt do planner e geometria do compose.
    const aspectRequested = normalizeAspect((body as { aspect?: unknown }).aspect)
    let duration = Number(body.duration) || 45
    // Runtime-validate optional director data before any OpenAI/Fal work. A TS
    // annotation is not a JSON boundary: null/malformed scene entries used to
    // crash only after paid Hollywood anchors had already been generated.
    const rawPlanScenes: unknown = body.brollScenes
    if (
      rawPlanScenes !== undefined &&
      (!Array.isArray(rawPlanScenes) || rawPlanScenes.length > 12 || rawPlanScenes.some((scene) =>
        !scene || typeof scene !== 'object' || Array.isArray(scene)
      ))
    ) {
      return NextResponse.json({ error: 'Invalid cinematic scene plan.' }, { status: 400 })
    }
    const planScenes = (Array.isArray(rawPlanScenes) ? rawPlanScenes : []).map((raw) => {
      const scene = raw as Record<string, unknown>
      const optionalString = (value: unknown, max: number) =>
        typeof value === 'string' && value.trim().length > 0
          ? value.trim().slice(0, max)
          : undefined
      return {
        sceneNumber: typeof scene.sceneNumber === 'number' && Number.isInteger(scene.sceneNumber)
          ? Math.max(1, Math.min(99, scene.sceneNumber))
          : undefined,
        brollPrompt: optionalString(scene.brollPrompt, 1200),
        shotType: optionalString(scene.shotType, 120),
        negativePrompt: optionalString(scene.negativePrompt, 500),
        userFootageUrl: optionalString(scene.userFootageUrl, 4096),
      }
    })
    const rawStyle: unknown = body.globalStyle
    if (rawStyle !== undefined && (!rawStyle || typeof rawStyle !== 'object' || Array.isArray(rawStyle))) {
      return NextResponse.json({ error: 'Invalid cinematic style.' }, { status: 400 })
    }
    const styleRecord = (rawStyle ?? {}) as Record<string, unknown>
    const styleString = (value: unknown) => typeof value === 'string' ? value.trim().slice(0, 200) : undefined
    const gStyle = rawStyle === undefined ? undefined : {
