    if (classicPersona && narrationRate.wordsPerSecond !== 3.1) console.log(`[cinematic] KINEO-RITMO-POR-VOZ: persona ${classicPersona.id} (${classicPersona.voice} ${classicPersona.defaultSpeed}) → régua ${narrationRate.wordsPerSecond} pal/s (${Math.round(duration * narrationRate.wordsPerSecond)} palavras para ${duration}s)`)
    // ═══ KINEO-VERBATIM-SEM-MARCADOR-2026-08-24 ═════════════════════════════
    // O Contrato C1 dizia "com script verbatim, o texto falado é o roteiro do
    // usuário" — mas a porta de entrada do contrato era `hasMarkers`: só
    // roteiro no formato da casa (HOOK/MICRO REWARD) contava como verbatim.
    // Quem clicava "Use my script as is" com PROSA LIMPA (o caso mais comum de
    // roteiro próprio) caía no caminho antigo: o GPT planejava as cenas E
    // escolhia o que falar — no render do fundador desta noite, usou 4 de 9
    // cenas e descartou justamente o clímax (Proteus/Nereus, a frase final, o
    // gancho do próximo episódio). 24s de filme mudo, 150cr, $7 de fal.
    // Agora o pedido explícito do usuário TAMBÉM liga o contrato: verbatim =
    // formato da casa OU botão apertado. `script_mode` chega do client (que
    // sempre soube — só não contava).
    const userSaysVerbatim = ((body.script_mode ?? '') as string).toLowerCase() === 'verbatim'
    // KINEO-BRIEF-NAO-E-FALA-2026-09-12 — um BRIEFING (ficha de personagem +
    // instruções, sem rótulo de fala) nunca é narrado palavra por palavra, mesmo
    // que o cliente diga verbatim (9bac0a81: a voz leu "Voz infantil feminina,
    // doce…" como fala, 25cr). Vira modo IA: o escritor recebe o brief inteiro.
    const briefDetected = userSaysVerbatim && !parsedScript.hasMarkers && looksLikeBrief(prompt)
    if (briefDetected) await writeServerEvent({ name: 'brief_detected_ai_mode', userId: user.id, path: '/api/generate-video-cinematic', metadata: { prompt_length: prompt.length, engine: body.engine ?? 'seedance' } })
    const verbatim = (parsedScript.hasMarkers && parsedScript.segments.length > 0) || (userSaysVerbatim && !briefDetected)
    // [TRAVA 8.2 — "vai conserta" do fundador, 29/09] KINEO-RITMO-POR-IDIOMA-15S-2026-09-29 — a guarda de roteiro longo no RITMO
    // DA LÍNGUA (lib/durationByEngine ritmoDoFilmeCurto, a mesma régua do escritor, do plano 3x6 e do portão): 46 palavras turcas
    // são ~22,7 s de fala (46 ÷ 2,03), acima dos 22,5 s que 3 × 8 s cobrem — a guarda de 2,5 pal/s logo abaixo as deixava passar
    // e mandava "encurtar para 56 palavras". Só nas línguas de palavra longa (fator < 1: tr, de, ru, uk, id, pl, nl); em en/pt/es
    // nada roda aqui e a guarda de baixo é a de sempre. Linhas só acrescentadas: a guarda de baixo fica byte a byte e, por ser
    // mais frouxa, nunca recusa o que esta aceitou.
    if (fatorDoRitmoDoIdioma(narrationLanguage.language) < 1) {
      const falaCurtaNaLingua = checarFalaDoFilmeCurto({ engine: typeof body.engine === 'string' ? body.engine : null, seconds: duration, verbatim, narration: parsedScript.narration, language: narrationLanguage.language })
      if (!falaCurtaNaLingua.ok) {
        await writeServerEvent({ name: 'short_film_script_too_long_refused', userId: user.id, path: '/api/generate-video-cinematic', metadata: { engine: typeof body.engine === 'string' ? body.engine : 'seedance', requested_seconds: duration, est_speech_seconds: Math.round(falaCurtaNaLingua.estSeconds), limit_seconds: falaCurtaNaLingua.limitSeconds, suggested_seconds: falaCurtaNaLingua.sugestao, charged: false, version: 'seedance_15s_20260929', language: narrationLanguage.language, words_per_second: ritmoDoFilmeCurto(narrationLanguage.language), ruler: 'ritmo_por_idioma_15s_20260929' } })
        return NextResponse.json({ error: scriptTooLongForShortFilmMessage(duration, falaCurtaNaLingua.estSeconds, creditCostForDuration('cinematic_ai', true, falaCurtaNaLingua.sugestao), narrationLanguage.language), reason: falaCurtaNaLingua.recusa, requested_seconds: duration, est_speech_seconds: Math.round(falaCurtaNaLingua.estSeconds), suggested_seconds: falaCurtaNaLingua.sugestao, retryable: false, charged: false, refunded: false }, { status: 422 })
      }
    }
    // ═══ KINEO-SEEDANCE-15S-2026-09-29 [TRAVA 8.2 — "vai" do 15 s] — roteiro longo pedido como filme curto ═══
    // Em verbatim o filme segue a FALA (#442 abaixo: clipes = fala ÷ 10 s, até 9; o compose deixa o áudio ir a 90 s), mas o
    // preço fica selado na duração pedida. Seedance a 15 s com fala estimada > 22,5 s (mesma régua do #442: palavras ÷ 2,5)
    // é recusado AQUI, antes do custo, do claim e do débito, sugerindo 35 s — sem isto, 150 palavras viravam um filme de
    // ~60 s por 7 cr (de graça no trial).
    {
      const falaCurta = checarFalaDoFilmeCurto({ engine: typeof body.engine === 'string' ? body.engine : null, seconds: duration, verbatim, narration: parsedScript.narration })
      if (!falaCurta.ok) {
        await writeServerEvent({ name: 'short_film_script_too_long_refused', userId: user.id, path: '/api/generate-video-cinematic', metadata: { engine: typeof body.engine === 'string' ? body.engine : 'seedance', requested_seconds: duration, est_speech_seconds: Math.round(falaCurta.estSeconds), limit_seconds: falaCurta.limitSeconds, suggested_seconds: falaCurta.sugestao, charged: false, version: 'seedance_15s_20260929' } })
        return NextResponse.json({ error: scriptTooLongForShortFilmMessage(duration, falaCurta.estSeconds, creditCostForDuration('cinematic_ai', true, falaCurta.sugestao)), reason: falaCurta.recusa, requested_seconds: duration, est_speech_seconds: Math.round(falaCurta.estSeconds), suggested_seconds: falaCurta.sugestao, retryable: false, charged: false, refunded: false }, { status: 422 })
      }
    }

    // ═══ KINEO-DEGRAU-2026-09-03 — O GATE VIRA DEGRAU, E DESCE ANTES DO CUSTO ═══
    // Medido em 03/09: a trava de narração (mais abaixo) recusou 34 renders de
    // ~30 pessoas em 30d; 24 deles tinham ≥60% de cobertura — "faltam 2
    // palavras". Em vez de recusar, o servidor desce o alvo para o múltiplo de
    // 5 que a fala enche (FLOOR: a fala fica ACIMA do novo alvo, nunca
    // abaixo — "passar do alvo é bom, ficar abaixo é defeito", fundador 02/09)
    // e renderiza. É o espelho do `script_duration_autofit` do cliente.
    //
    // ⚠️ AQUI, E NÃO NA TRAVA: `creditCostForDuration` (abaixo) é linear nos
    // segundos e o claim sela esse valor. Descer a duração depois do claim
    // faria a pessoa pagar 35s e receber 30s — cobrança-surpresa, a classe de
    // erro que KINEO-DURACAO-2026-08-20 existe para matar. Com a descida
    // aqui, custo, claim, débito, planner, compose e resposta usam TODOS a
    // mesma duração efetiva. Zero drift financeiro.
    //
    // Só no caminho verbatim (texto do USUÁRIO, Contrato C1 — não podemos
    // reescrevê-lo; no automático o gerador produz o tamanho certo). Quando
    // não desce (cobertura <60%, alvo <piso, régua reprova), NADA muda: a
    // trava de hoje recusa com o 422 educativo, exatamente como antes.
    // Regra e constantes em lib/narrationFit.ts (`autofitDown`).
    const requestedDuration = duration
    // 11/09 founder decision supersedes the automatic descent described above.
    // A normal request keeps its selected duration. Existing guided expansion /
    // explicit shorter-duration buttons remain available before any debit.
    const degrau = body.allow_shorter_duration === true && verbatim && parsedScript.narration
      ? autofitDownAt(parsedScript.narration, requestedDuration, narrationRate, {
          // O planner hollywood trava o alvo em `Math.max(30, …)` — descer
