    // trialClockExpired trata data ilegivel como vencida, de proposito) e a
    // copy contextual diria "o motor de AI era do seu trial" a alguem que nunca
    // teve trial funcional. So fala de PERDA quem comprovadamente RECEBEU.
    const trialEnded =
      (trialUi.phase === 'downgraded' || trialUi.phase === 'ending') && trialUi.creditsGranted > 0
    // ═══ KINEO-S25-ABRE-2026-10-06 — SEEDANCE 2.5 SÓ PARA QUEM PAGA (aposta A do fundador, 06/10) ═══════════════
    // O 2.5 é motor PAGO EXTRA: página e seletor são públicos (S25_PUBLIC, a isca), mas usar exige plano pago — [KINEO-S25-ABRE-2026-10-06]
    // isPayingPlan via lib/s25Access.ts. O trial de cadastro (o TRIAL_UNLOCKS_PREMIUM abaixo NÃO vale para ele), o [KINEO-S25-ABRE-2026-10-06]
    // *_trial de cortesia e o pacote avulso ficam de fora. Fica ANTES do gate dos motores premium, do custo, do claim e de [KINEO-S25-ABRE-2026-10-06]
    // qualquer débito: recusar aqui custa zero. Mesmo formato das recusas de portão (402 + upsell 'studio', que o [KINEO-S25-ABRE-2026-10-06]
    // /studio/create já abre como caixa de planos) e evento de SERVIDOR com o motivo. Os outros motores não passam por aqui. [KINEO-S25-ABRE-2026-10-06]
    // Com S25_PUBLIC=false vale o portão antigo do canário (mais abaixo, 's25_internal_only'). [KINEO-S25-ABRE-2026-10-06]
    if (wantsS25 && S25_PUBLIC) { // KINEO-S25-ABRE-2026-10-06
      // KINEO-PARCEIRO-ABRE-TUDO-2026-10-09 — parceiro ativo (cortesia ativa + afiliado ativo, lib/partnerAccess.ts) usa o 2.5 com o
      // crédito da cortesia; o débito e o preço abaixo são os de sempre. Só lê para plano de cortesia; falha = não é parceiro [KINEO-PARCEIRO-ABRE-TUDO-2026-10-09]
      // (a recusa de baixo continua idêntica para quem não é). [KINEO-PARCEIRO-ABRE-TUDO-2026-10-09]
      const parceiroS25 = await isActivePartner(user.id, planVal) // KINEO-PARCEIRO-ABRE-TUDO-2026-10-09
      const acessoS25 = s25AccessFor({ email: user.email, plan: planVal, partner: parceiroS25 }) // KINEO-S25-ABRE-2026-10-06 · KINEO-PARCEIRO-ABRE-TUDO-2026-10-09
      if (!acessoS25.allowed) { // KINEO-S25-ABRE-2026-10-06
        await writeServerEvent({ name: S25_PAID_ONLY_EVENT, userId: user.id, path: '/api/generate-video-cinematic', metadata: { engine: 's25', reason: acessoS25.reason, plan: planVal, has_paid: profile?.has_paid === true, trial_active: trialActive, balance, dry_run: body.dry_run === true, charged: false, version: 's25_abre_20261006' } }) // KINEO-S25-ABRE-2026-10-06
        return NextResponse.json({ error: S25_PAID_ONLY_MESSAGE, upsell: 'studio', reason: S25_PAID_ONLY_REASON, engine: 's25', upgradeHref: s25UpgradeHref('server'), balance, retryable: false, charged: false, refunded: false }, { status: 402 }) // KINEO-S25-ABRE-2026-10-06
      } // KINEO-S25-ABRE-2026-10-06
    } // KINEO-S25-ABRE-2026-10-06

    // ═══ KINEO-TETO-2026-08-20 — O TRIAL PASSA A MOSTRAR O TETO ═══════════
    // Inversão do modelo, decidida com o fundador depois do estudo dos cinco
    // concorrentes. O padrão vencedor da categoria (OpusClip) NÃO raciona o
    // produto: entrega o vídeo pronto e cobra pela POSSE dele — o clipe grátis
    // deixa de ser exportável em 3 dias. Quem paga, paga para não perder uma
    // coisa que já é sua; é aversão à perda, não expectativa de ganho.
    //
    // O QUE ESTÁVAMOS FAZENDO ERA O CONTRÁRIO, e contra nós mesmos: o trial só
    // abria o Kineo 1 e o Seedance, ou seja, a pessoa julgava a Kineo pelo
    // PISO do catálogo e concluía que somos medianos. Só que o nosso
    // diferencial mora no TETO — Kling 3 com voz nativa e lip sync é
    // exatamente o que nenhum desses concorrentes tem (eles cortam vídeo
    // alheio; nós fazemos filme do zero).
    //
    // Agora o trial abre TUDO. O que segura a conversão não é mais o bloqueio
    // do motor, é a MARCA D'ÁGUA + o download limpo (ver app/api/compose:
    // `watermark`). A pessoa faz o filme cinematográfico dela, assiste, se
    // encanta — e o botão de baixar pede o plano.
    //
    // O custo disso é real e foi aceito de olhos abertos: um Kling 3 custa
    // ~$11,85 de fornecedor e o trial de 80 créditos NÃO alcança os 150 dele
    // (por isso o gate de crédito abaixo continua sendo o freio de verdade).
    // Quem alcança é o H3 (45cr) e o Veo (90cr) — os dois já são teto o
