      // gastou o trial inteiro e é o sinal de intenção mais forte do funil.
      //
      // ⚠️ ONDE CADA UM REALMENTE ACONTECE (2ª passada — a 1ª versão deste
      // comentário vendia o `spent` como o caso principal desta rota, e é o
      // contrário): `isTrialActive()` já devolve false quando `trialCapReached`
      // (usado >= 40), então quem queimou o trial inteiro NÃO chega aqui com
      // `trialActive` true — ele cai no gate de plano logo acima, como
      // `trial_ended`, e na prática nem isso, porque o cliente barra o clique
      // antes (corrigido no MESMO commit, em openOutOfCreditsModal).
      // Nesta rota o caso VIVO é o `stalled`: saldo parcial, trial ainda de pé.
      // O `spent` fica como caminho de defesa para o resíduo real de saldo 0
      // com `usado < 40` (estorno de render falho devolve crédito e abate o
      // consumo — a coorte de 13/08 tem linhas assim).
      // ═══ KINEO-TRIAL-STALL-FALSO-2026-08-15 ═══════════════════════════════
      // ANTES de chamar qualquer coisa de "fim de trial", perguntar se o
      // buraco é explicado por um render que ainda não se resolveu. Só entra
      // quando o crédito preso REALMENTE fecha a conta (`balance + held >=
      // cost`): se mesmo com ele de volta não daria, a pessoa está sem saldo
      // de verdade e merece a frase antiga, não uma desculpa.
      //
      // Vale para TODO MUNDO, não só trial (`insufficient_credits` também
      // mentia — "This needs 20 credits. You have 19." é um extrato, não uma
      // explicação), mas a mentira cara era a do trial, que vinha com pedido
      // de dinheiro em cima.
      // `hold` já foi lido acima (e o estorno ao vivo já tentou). Reavaliar com
      // o saldo ATUAL: se o estorno devolveu parte e ainda não fecha, a frase
      // continua sendo a do crédito preso, com o número novo.
      const heldByUnsettled = hold.held
      const veredito = classifyHold({ hold, balance, cost })
      const heldExplainsGap = veredito.explainsGap
      // KINEO-CREDITO-PRESO-2026-09-03 — os dois casos que hoje leem a MESMA
      // frase e precisam de frases opostas. Mediana medida da idade do débito
      // que segura: 2 minutos (11 das 16 recusas abaixo de 5 min). Nessa faixa
      // o render não morreu — ele está no forno, e a pessoa está clicando de
      // novo porque a tela não disse isso. Dizer "seu crédito volta em uma
      // hora" para quem tem um filme cozinhando é a definição de produto
      // quebrado: ela abandona a aba, e aí o filme morre de verdade.
      const holdIsInFlight = veredito.inFlight
      const holdMinutes = veredito.minutes

      // ═══ sprint-v1v4 #27 — O SEGUNDO CAMINHO DA RECUSA DE SALDO ══════════
      //
      // MEDIDO EM PRODUCAO (60d, so externos, `compose_refused` com
      // reason='trial_credits_stalled'): 26 recusas em 15 pessoas. O saldo
      // delas ia de 9 a 62 creditos — NENHUMA estava zerada. E em 19 das 26
      // existia uma combinacao motor x duracao DESTE MESMO cardapio que o
      // saldo pagava naquele segundo (11 das 15 pessoas). A unica coisa que a
      // resposta dizia era "Add a plan".
      //
      // Ou seja: a pessoa voltou para fazer o 2o video, tinha credito no
      // bolso, e o produto mandou ela para a pagina de preco. E o 4o video e
      // o limiar onde a conversao medida salta de 0,9% para 11,8% — cobrar
      // antes de deixar ela chegar la e cobrar cedo demais.
      //
      // ⚠️ O QUE ESTE BLOCO **NAO** FAZ, e a razao de cada limite:
      //   · NAO toca no `error` de plano: a frase do Codex continua PRIMEIRA e
      //     byte a byte. A sugestao e ACRESCENTADA depois, nunca substitui.
      //   · NAO mexe em `upsell`, `reason`, `needed`, `balance` nem no modal.
      //     O caminho de compra sai daqui exatamente como entrou.
      //   · NAO fala de preco, plano, cupom, cota, trial nem "free". Diz dois
      //     numeros tecnicos (segundos e creditos), que e o lado meu da
      //     fronteira de lib/credits/engineCost.ts.
      //   · NAO inventa motor travado: `motoresDisponiveis` repete o MESMO
      //     gate de plano que roda ~80 linhas acima (TRIAL_UNLOCKS_PREMIUM).
      //     Nunca ofereco como saida algo que o cadeado do Codex tranca.
      //   · Se nada cabe (`nada_cabe`), a resposta sai IDENTICA a hoje. Sem
      //     saida real, inventar uma seria a mentira que a copy honesta
      //     proibe.
      //   · Nao entra no `credits_held_by_render`: ali o saldo VOLTA sozinho
      //     dentro da hora, e mandar a pessoa encolher o filme dela seria
      //     resolver com concessao um problema que se resolve com espera.
      //
      // A duracao usada e a MESMA lista de tres botoes do seletor
      // (DURATION_OPTIONS no GenerateClient: 35/60/90). Escrever aqui um
      // numero que o seletor nao oferece e exatamente o defeito que a #11
      // caçou — por isso a lista fica em constante nomeada, com o par citado.
      const DURACOES_DO_SELETOR = [35, 60, 90] as const
      const premiumLiberado = isPaidUser || (TRIAL_UNLOCKS_PREMIUM && trialActive)
      const MOTOR_PARA_QUALIDADE: Record<string, Quality> = {
        seedance: 'cinematic_ai',
        h3: 'cinematic_h3',
        h3max: 'cinematic_h3max', // KINEO-H3MAX-2026-10-13
        kling: 'cinematic_kling',
        veo: 'cinematic_veo',
        hollywood: 'cinematic_hollywood',
        omni: 'cinematic_omni',
        s25: 'cinematic_s25',
      }
      const NOME_PUBLICO_DO_MOTOR: Record<string, string> = {
        seedance: 'AI Generated',
        h3: 'MiniMax H3',
        h3max: 'MiniMax H3 Max', // KINEO-H3MAX-2026-10-13
        kling: 'Kling 2.5',
        veo: 'Veo 3.1',
        hollywood: 'Kling 3',
        omni: 'Omni',
        s25: 'Seedance 2.5',
      }
      const motorPedido = wantsS25 ? 's25'
        : wantsH3 ? 'h3'
        : wantsH3Max ? 'h3max' // KINEO-H3MAX-2026-10-13
        : wantsOmni ? 'omni'
        : wantsHollywood ? 'hollywood'
        : wantsKling ? 'kling'
        : wantsVeo ? 'veo'
        : 'seedance'
      // A MESMA funcao que COBRA, nunca uma tabela local (a licao do
      // "Generate · 20 credits" que debitava 30).
      const custoDe = (m: string, d: number): number =>
        creditCostForDuration(MOTOR_PARA_QUALIDADE[m] ?? 'cinematic_ai', true, d) + (estrelaAtiva ? estrelaSobretaxa(m, d) : 0) // KINEO-ESTRELA-DO-FILME-2026-09-29: o resgate por saldo precifica com a estrela
      // KINEO-SEEDANCE-15S-2026-09-29 (B10) — no Seedance, a recusa por saldo também oferece o 15 s (7 cr), mas só para
      // quem o interruptor SEEDANCE_15S_PUBLIC já mostra o botão (a casa, até o canário). Nos outros motores o 15 s não existe.
      const duracoesDoResgate: readonly number[] = motorPedido === 'seedance' && seedance15sVisible(user.email)
        ? supportedDurationsFor('seedance')
        : DURACOES_DO_SELETOR
      // [TRAVA 8.2 — vai do fundador 29/09 'vai pra todas as 4'] KINEO-DURACOES-CURTAS-2026-09-29 — nos outros motores a recusa por saldo também
      // [KINEO-DURACOES-CURTAS-2026-09-29] oferece as durações curtas do motor (Kling 2.5/Veo 15 s; hollywood 15/30 s), para quem o interruptor DURACOES_CURTAS_PUBLIC mostra os botões.
      const duracoesDoResgateCurtas: readonly number[] | null = motorPedido !== 'seedance' && duracoesCurtasVisible(user.email) ? supportedDurationsFor(motorPedido) : null // KINEO-DURACOES-CURTAS-2026-09-29
      const resgateDoSaldo = heldExplainsGap
        ? ({ tipo: 'cabe' } as const)
        : planoDeResgate({
            motorAtual: motorPedido,
            duracaoAtual: duration,
            saldo: balance,
            duracoes: duracoesDoResgateCurtas ?? duracoesDoResgate, // KINEO-DURACOES-CURTAS-2026-09-29
            custoDe,
            motoresDisponiveis: premiumLiberado
              ? ['seedance', 'h3', ...(h3maxVisible(user.email) ? ['h3max'] : []), 'kling', 'veo', 'hollywood', 'omni'] // KINEO-H3MAX-2026-10-13
              : ['seedance'],
          })
      const fraseDoResgate =
        resgateDoSaldo.tipo === 'mesma_camera'
          // O desvio PREFERIDO: a camera que ela escolheu, filme mais curto.
          ? `A ${resgateDoSaldo.alvo.duracao}s version of the same film costs ${resgateDoSaldo.alvo.custo} credits — your balance covers that one right now.`
          : resgateDoSaldo.tipo === 'outra_camera'
            ? `${NOME_PUBLICO_DO_MOTOR[resgateDoSaldo.alvo.motor] ?? 'Another engine'} at ${resgateDoSaldo.alvo.duracao}s costs ${resgateDoSaldo.alvo.custo} credits — your balance covers that one right now.`
            : ''

      // ⚠️ KINEO-CREDITO-PRESO-2026-09-03 — O `reason` DE FIO NÃO MUDA, DE
      // PROPÓSITO. `app/(dashboard)/generate/GenerateClient.tsx` tem, desde o
      // sprint-v1v4 #33, uma SALA DE ESPERA dedicada a
      // `reason === 'credits_held_by_render'` — sem caixa de planos, com
      // rechecagem de saldo, exibindo o texto do servidor. Inventar um
      // `reason` novo aqui jogaria justamente o caso mais comum (filme no
      // forno) no painel vermelho genérico, que ainda diz "your credits have
      // been returned - you can retry safely". Seria uma regressão vestida de
      // melhoria. A distinção viaja em `holdState` (aditivo) e na telemetria.
      const stallReason = heldExplainsGap
        ? 'credits_held_by_render'
        : trialBuyer
          ? (balance > 0 ? 'trial_credits_stalled' : 'trial_credits_spent')
          : 'insufficient_credits'
      await logCinematicRefusal(stallReason, user.id, {
        needed: cost,
        balance,
        held_by_unsettled_render: heldByUnsettled,
        // KINEO-CREDITO-PRESO-2026-09-03 — sem estes três campos não dá para
        // saber, em SQL, se a recusa foi "filme no forno" ou "render morto",
        // que é a pergunta inteira desta jogada.
        hold_age_ms: hold.newestAgeMs,
        hold_in_flight: holdIsInFlight,
        live_release_credits: liveRelease.creditsReturned,
        engine: wantsS25 ? 's25' : wantsOmni ? 'omni' : wantsH3 ? 'h3' : wantsH3Max ? 'h3max' : wantsHollywood ? 'hollywood' : wantsKling ? 'kling' : wantsVeo ? 'veo' : 'seedance', // KINEO-H3MAX-2026-10-13
        trial_phase: trialUi.phase,
        trial_credits_granted: trialUi.creditsGranted,
        is_paid: isPaidUser,
        // sprint-v1v4 #27 — A METRICA DESTA RODADA. `nada_cabe` = o saldo
        // realmente nao paga nada do cardapio (a recusa saiu IDENTICA a de
        // hoje); qualquer outro valor = existia saida e a pessoa passou a ser
        // avisada. Campos NOVOS: `reason`, `used` e `balance` seguem
        // significando o mesmo de sempre, porque instrumento novo nao pode
        // inflar metrica antiga.
        rescue: resgateDoSaldo.tipo,
        rescue_engine: 'alvo' in resgateDoSaldo ? resgateDoSaldo.alvo.motor : null,
        rescue_seconds: 'alvo' in resgateDoSaldo ? resgateDoSaldo.alvo.duracao : null,
        rescue_cost: 'alvo' in resgateDoSaldo ? resgateDoSaldo.alvo.custo : null,
      })
      return NextResponse.json(
        {
          error:
            // KINEO-CREDITO-PRESO-2026-09-03 — a frase do filme que JÁ está
            // sendo feito. Nenhum preço, nenhum pedido de plano, nenhuma
            // promessa de prazo exato: só o fato, a idade real do render e a
            // única instrução que evita o segundo clique. "your film" e não
            // "your credits" de propósito — a pessoa veio fazer um filme, não
            // administrar saldo.
            holdIsInFlight
              ? inFlightMessage(holdMinutes, heldByUnsettled)
            : stallReason === 'credits_held_by_render'
              // NENHUMA PROMESSA DE PRAZO EXATO e NENHUM PREÇO. "within the
              // hour" é o que a varredura horária garante; dizer "5 minutos"
              // seria inventar. E a última frase é a que importa: a pessoa
              // precisa saber que o trial NÃO acabou.
              ? `A video you already started is still holding ${heldByUnsettled} credit${heldByUnsettled === 1 ? '' : 's'}. If it doesn't finish, they come back automatically within the hour — your trial is still running.`
              : stallReason === 'trial_credits_stalled'
                ? `Your trial has ${balance} credit${balance === 1 ? '' : 's'} left and an AI video needs ${cost}. Add a plan to keep the AI engine.${fraseDoResgate ? ` ${fraseDoResgate}` : ''}`
                : stallReason === 'trial_credits_spent'
                  ? `You've used all ${trialUi.creditsGranted} credits from your trial. Add a plan to keep making AI videos.`
                  : `This needs ${cost} credits. You have ${balance}.${fraseDoResgate ? ` ${fraseDoResgate}` : ''}`,
          needed: cost,
          balance,
          held: heldExplainsGap ? heldByUnsettled : undefined,
          // KINEO-CREDITO-PRESO-2026-09-03 — a UI pode mostrar progresso em vez
          // de erro quando isto vem preenchido. Campo aditivo: cliente antigo
          // ignora e continua exibindo `error`, que já está certo sozinho.
          // Campos ADITIVOS: cliente antigo ignora e continua certo, porque o
          // `error` já carrega a frase inteira. Servem para a sala de espera
          // poder, quando quiser, mostrar progresso em vez de contagem.
          holdState: heldExplainsGap ? (holdIsInFlight ? 'in_flight' : 'dead') : undefined,
          inFlight: holdIsInFlight ? { minutesAgo: holdMinutes, credits: heldByUnsettled } : undefined,
          retryAfterSeconds: holdIsInFlight ? 90 : undefined,
          reason: stallReason,
          // `upsell` só viaja para quem realmente precisa comprar um PLANO. Um
          // assinante sem saldo precisa de créditos, não de outro plano, e
          // mandar `upsell` abriria a headline errada para ele.
          // `heldExplainsGap` DERRUBA o upsell mesmo para quem é trialBuyer:
          // este 402 não é um momento de venda, é um aviso de estado. Sem
          // `upsell` o cliente não abre a caixa de planos (ver GenerateClient,
          // mesmo marcador) — que é o ponto inteiro desta correção.
          upsell: trialBuyer && !heldExplainsGap ? 'creator' : undefined,
          trialCreditsGranted: trialBuyer && !heldExplainsGap ? trialUi.creditsGranted : undefined,
          trialCreditsUsed: trialBuyer && !heldExplainsGap ? trialUi.creditsUsedForDisplay : undefined,
        },
        { status: 402 }
      )
    }
    if (reconexaoDoMesmoFilme) balance = saldoDaReconexao // KINEO-RECONEXAO-MESMO-FILME-2026-10-13

    // KINEO-353A.1 — MOTOR REAL. O #353A gravava `engine: 'hollywood'` no
    // FAILFAST premium, o que apagava H3 e Omni: os tres viravam a mesma linha
    // no painel, e a pergunta "qual motor esta falhando?" ficava sem resposta.
    const claimQuality = wantsS25
      ? 'cinematic_s25'
      : wantsH3
      ? 'cinematic_h3'
      : wantsH3Max // KINEO-H3MAX-2026-10-13
      ? 'cinematic_h3max' // KINEO-H3MAX-2026-10-13
      : wantsOmni
      ? 'cinematic_omni'
      : wantsHollywood
      ? 'cinematic_hollywood'
      : wantsKling
        ? 'cinematic_kling'
        : wantsVeo
          ? 'cinematic_veo'
          : 'cinematic_ai'
    // KINEO-128C-2026-09-01 — faltava o ramo do Omni: o claim do render
    // 37c8d832 gravou engine='seedance' num filme Omni e a pergunta 'qual
    // motor esta falhando?' ficou sem resposta. Agora cada familia assina.
    const claimEngine = wantsS25
      ? 's25'
      : wantsOmni
      ? 'omni'
      : wantsH3
      ? 'h3'
      : wantsH3Max // KINEO-H3MAX-2026-10-13
      ? 'h3max' // KINEO-H3MAX-2026-10-13
      : wantsHollywood
      ? 'hollywood'
      : wantsKling
        ? 'kling'
        : wantsVeo
          ? 'veo'
          : 'seedance'
    const claimFingerprint = cinematicRequestFingerprint({
      prompt,
      duration,
      engine: claimEngine,
      language: narrationLanguageCode(body.language) ?? 'en', // KINEO-IDIOMAS-15
      vertical: typeof body.vertical === 'string' ? body.vertical.trim().toLowerCase() : '',
      characterId: (typeof body.characterId === 'string' ? body.characterId.trim() : '') + estrelaFingerprintSuffix(estrelaDecisao), // KINEO-ESTRELA-DO-FILME-2026-09-29: com e sem estrela não são o mesmo pedido ('' sem estrela = impressão de sempre)
      brollScenes: planScenes,
      globalStyle: gStyle ?? null,
    })
    const supabaseUrl = process.env.NEXT_PUBLIC_SUPABASE_URL
    const serviceRoleKey = process.env.SUPABASE_SERVICE_ROLE_KEY
    if (!supabaseUrl || !serviceRoleKey) {
      return NextResponse.json(
        { error: 'AI generation safety is temporarily unavailable. Nothing was submitted.' },
        { status: 503 },
      )
    }
    const cinematicAdmin: SupabaseClient = createAdminClient(supabaseUrl, serviceRoleKey, {
      auth: { persistSession: false, autoRefreshToken: false },
    })
    // sprint-assinaturas #14 — a caixa-preta abre aqui. O campo session_id
    // recebe o generationId (mesma convenção dos claims), para o cron cruzar
    // os dois lotes por chave e nunca por dedução. Fire-and-forget: telemetria
    // jamais derruba a geração.
    try {
      await cinematicAdmin.from('events').insert({
        user_id: user.id,
        name: 'generation_attempt_opened',
        session_id: generationId,
        path: '/api/generate-video-cinematic',
        metadata: {
          generation_id: generationId,
          engine: claimEngine,
          duration,
          dry_run: body.dry_run === true,
          // O tema, para o aviso da Fase 5 nomear o filme que a pessoa quis.
          // topic_complete diz se estes 90 caracteres SÃO o texto inteiro: só
          // nesse caso o botão do e-mail pode voltar preenchido. Roteiro longo
          // vira nome, nunca reenvio truncado em nome da pessoa.
          topic_hint: prompt.slice(0, 90),
          topic_complete: prompt.length <= 90,
        },
      })
      attemptTrace = { db: cinematicAdmin, userId: user.id, generationId }
    } catch { /* telemetria nunca derruba a resposta */ }
    // KINEO-DEGRAU-2026-09-03 — a descida ganha evento com nome próprio no
    // PRIMEIRO ponto em que o client admin existe (a decisão foi tomada lá em
    // cima, antes do custo; `events` só aceita service_role). Sem isto o
    // degrau seria invisível no /admin e não haveria como provar que ele
    // converteu parede em vídeo. `credits_requested` × `credits_effective`
    // provam no painel que a pessoa pagou o que recebeu. Fire-and-forget.
    if (degrau?.applied) {
      try {
        await cinematicAdmin.from('events').insert({
          user_id: user.id,
          name: 'script_duration_autofit_down',
          path: '/api/generate-video-cinematic',
          metadata: {
            generation_id: generationId,
            requested_seconds: requestedDuration,
            effective_seconds: duration,
            speech_seconds: Math.round(degrau.speechSeconds),
            coverage: Number(degrau.coverage.toFixed(2)),
            engine: claimEngine,
            quality: costQuality,
            credits_requested: creditCostForDuration(costQuality, true, requestedDuration),
            credits_effective: cost,
            lost_60s_floor: degrau.lost60sFloor,
            dry_run: body.dry_run === true,
          },
        })
      } catch { /* telemetria nunca derruba a resposta */ }
    }
    const cacheKey = `${user.id}:${generationId}`
    const now = Date.now()
    for (const [key, entry] of cinematicSubmissionCache) {
      if (entry.expiresAt <= now) cinematicSubmissionCache.delete(key)
    }

    // A fully failed provider attempt is refunded, but repeated deliberately
    // failing prompts must not turn paid Fal work (especially Hollywood
    // anchors) into an unlimited free endpoint. Two signed/refunded failures
    // inside 15 minutes trigger a short cooling-off window. Query failure is
    // fail-open so an analytics outage never blocks legitimate generation.
    const cooldownCutoff = new Date(now - 15 * 60 * 1000).toISOString()
    const { data: recentClaims, error: cooldownError } = await cinematicAdmin
      .from('events')
      .select('metadata,created_at')
      .eq('name', 'cinematic_submission_claim')
      .eq('user_id', user.id)
      .gte('created_at', cooldownCutoff)
      .order('created_at', { ascending: false })
      .limit(10)
    if (cooldownError) {
      console.warn('[cinematic] refunded-attempt cooldown lookup failed:', cooldownError.message)
    } else {
      const recentRefundedFailures = (recentClaims ?? []).filter((row) => {
        const metadata = row.metadata && typeof row.metadata === 'object' && !Array.isArray(row.metadata)
          ? row.metadata as Record<string, unknown>
          : {}
        // sprint-retencao #20 — o filtro casa `provider_*_refunded` DE
        // PROPOSITO. Falha de plano vazio sai como `empty_plan_rejected_
        // refunded` e NAO conta aqui: sem POST nenhum na fal, nao ha trabalho
        // pago para transformar em endpoint gratuito, que e a unica coisa que
        // este resfriamento existe para impedir. Antes ela contava, e o
        // guarda anti-abuso trancava por 15 minutos justamente quem nao
        // tinha consumido nada.
        return metadata.status === 'released' &&
          typeof metadata.authority === 'string' && /^[a-f0-9]{64}$/i.test(metadata.authority) &&
          typeof metadata.resolution_reason === 'string' &&
          /^provider_.*_refunded$/.test(metadata.resolution_reason)
      }).length
      if (recentRefundedFailures >= 2) {
        return NextResponse.json(
          {
            error: 'Two AI attempts were just refunded. Please wait a few minutes before starting another one.',
            retry_after_ms: 15 * 60 * 1000,
          },
          { status: 429 },
        )
      }
    }

    const billingReference = `cinematic-${cinematicClaimId(user.id, generationId)}`
    // KINEO-353A.1 — identidade no contexto assim que existe. O finalizador
    // unico le daqui, entao TODO caminho de saida (inclusive o catch externo)
    // sai identificado, e nao so os tres que eu tinha escolhido a dedo.
    {
      const c = ctxDespacho()
      c.userId = user.id
      c.generationId = generationId
      c.claimId = cinematicClaimId(user.id, generationId)
      c.billingReference = billingReference
    }
    // KINEO-TRIAL-DOUBLECOUNT-2026-08-07 — de onde veio o replay do débito.
    // O débito adiantado (`upfrontDebit`) e a "confirmação idempotente" dentro
    // de settleDebitAndRespond() são o MESMO `billingReference`. Quando os dois
    // acontecem na MESMA request (caminho feliz: debita → submete → publica →
    // settle), o RPC roda duas vezes: a segunda colide na PK de credit_debits,
    // devolve o saldo e não tira nada. Isso é correto para o dinheiro, mas era
    // contado duas vezes no teto do trial (20 + 20 = 40 em 0,5s — foi assim que
    // o 1º trial real morreu com metade dos créditos). A trava definitiva é o
    // ledger por render em lib/reverseTrial.ts; aqui só se elimina a chamada
    // redundante: se ESTA request já confirmou o débito, reusa o resultado.
    // As outras duas entradas de settleDebitAndRespond (claim já existente /
    // resposta em cache) continuam confirmando de verdade — lá o débito NÃO
    // rodou nesta request e a confirmação é a única prova que temos.
    let debitConfirmedThisRequest: { ok: true; balance: number; insufficient: false; error: '' } | null = null
    const ensureCinematicDebit = async (creditCost: number): Promise<{
      ok: boolean
      balance: number
      insufficient: boolean
      error: string
    }> => {
      const { data, error } = await debitVideoCredits(supabase, {
        userId: user.id,
        renderId: billingReference,
        cost: creditCost,
      })
      if (error || typeof data !== 'number') {
        const message = error?.message ?? 'no balance returned'
        return {
          ok: false,
          balance: typeof data === 'number' ? data : 0,
          insufficient: /balance|credit|insufficient/i.test(message),
          error: message,
        }
      }
      return { ok: true, balance: data, insufficient: false, error: '' }
    }

    const confirmCinematicRefund = async (): Promise<boolean> => {
      const refunded = await refundRenderCredits(billingReference)
      if (refunded > 0) return true
      const { data, error } = await cinematicAdmin
        .from('credit_debits')
        .select('refunded_at')
        .eq('render_id', billingReference)
        .maybeSingle()
      if (error) {
        console.error('[cinematic] refund confirmation failed:', error.message)
        return false
      }
      return typeof data?.refunded_at === 'string' && data.refunded_at.length > 0
    }

    const audioNoClique = (resp: Record<string, unknown>) => (body.dry_run === true ? Promise.resolve(false) : agendarAudioNoClique({ generationId, userId: user.id, quality: claimQuality, response: resp, bodyVertical: body.vertical, bodyLanguage: body.language })) // KINEO-FILME-RAPIDO-1710 — despacho aceito: trilha, voz clássica e vozes por cena começam depois da resposta, enquanto a fal gera as cenas (1 reserva por geração; sem waitUntil = nada muda)
    const settleDebitAndRespond = async (
      claim: CinematicClaim,
      response: Record<string, unknown>,
    ): Promise<NextResponse> => {
      if (claim.status === 'released') {
        return NextResponse.json(
          { error: 'This AI generation was safely closed. Please start a new one.' },
          { status: 409 },
        )
      }
      if (claim.status === 'settled') await audioNoClique(response) // KINEO-FILME-RAPIDO-1710 — replay de um despacho já liquidado: a reserva por geração não repete
      if (claim.status === 'settled') return NextResponse.json(response)
      if (claim.status !== 'done') {
        return NextResponse.json(
          { error: 'This AI generation is still being submitted.', pending: true, retry_after_ms: 2500 },
          { status: 409 },
        )
      }

      // The job was atomically debited before provider submission. Re-running
      // the same deterministic ledger key here is an idempotent recovery check
      // before exposing request IDs or allowing authenticated polling.
      // KINEO-TRIAL-DOUBLECOUNT-2026-08-07 — pulada quando esta mesma request já
      // efetuou o débito adiantado (ver o bloco em `ensureCinematicDebit`).
      const debit = debitConfirmedThisRequest ?? await ensureCinematicDebit(claim.creditCost)
      if (!debit.ok) {
        console.error('[cinematic] deterministic debit confirmation failed:', debit.error)
        return NextResponse.json(
          {
            error: debit.insufficient
              ? `Your AI scenes were reserved, but ${claim.creditCost} credits could not be confirmed. Add credits and retry this same generation.`
              : 'Your AI scenes are safe while we confirm the credit charge. Reconnecting automatically.',
            ...(debit.insufficient
              ? { balance: debit.balance, resume_same_generation: true, generationId }
              : { pending: true, retry_after_ms: 3000 }),
          },
          { status: debit.insufficient ? 402 : 503 },
        )
      }
      const settled = await settleCinematicClaim({
        db: cinematicAdmin,
        secret: serviceRoleKey,
        userId: user.id,
        generationId,
        reason: 'provider_submitted_and_debited',
        renderId: billingReference,
      })
      if (!settled.ok) {
        console.error('[cinematic] debit settled but claim publication failed:', settled.error)
        return NextResponse.json(
          { error: 'Your AI scenes are safe while we finalize the submission.', pending: true, retry_after_ms: 2500 },
          { status: 503 },
        )
      }
      activeBirthClaim = null
      cinematicSubmissionCache.delete(cacheKey)
      await audioNoClique(response) // KINEO-FILME-RAPIDO-1710 — débito confirmado e claim liquidado: voz e música no clique
      return NextResponse.json({ ...response, credits_charged: claim.creditCost, balance: debit.balance })
    }

    const acquired = await acquireCinematicClaim({
      db: cinematicAdmin,
      secret: serviceRoleKey,
      userId: user.id,
      generationId,
      fingerprint: claimFingerprint,
      creditCost: cost,
      quality: claimQuality,
      engine: claimEngine,
    })
    if (acquired.kind === 'conflict') {
      return NextResponse.json({ error: acquired.error }, { status: 409 })
    }
    if (acquired.kind === 'error') {
      console.error('[cinematic] birth claim unavailable:', acquired.error)
      return NextResponse.json(
        { error: 'AI generation safety is temporarily unavailable. Nothing was submitted.' },
        { status: 503 },
      )
    }
    if (acquired.kind === 'released') {
      return NextResponse.json(
        { error: 'This AI generation was safely closed. Please start a new one.' },
        { status: 409 },
      )
    }
    if (acquired.kind === 'replay') {
      return settleDebitAndRespond(acquired.claim, acquired.response)
    }
    if (acquired.kind === 'pending') {
      const cached = cinematicSubmissionCache.get(cacheKey)
      if (
        cached && cached.expiresAt > Date.now() &&
        cached.fingerprint === claimFingerprint && cached.creditCost === cost &&
        cached.quality === claimQuality && cached.engine === claimEngine
      ) {
        const completed = await completeCinematicClaim({
          db: cinematicAdmin,
          secret: serviceRoleKey,
          userId: user.id,
          generationId,
          fingerprint: claimFingerprint,
          creditCost: cost,
          quality: claimQuality,
          engine: claimEngine,
          response: cached.response,
          falRequestIds: cached.requestIds,
          falModels: cached.models,
        })
        if (completed.ok) return settleDebitAndRespond(completed.claim, cached.response)
      }
      const pendingStartedAt = Date.parse(acquired.claim.startedAt)
      if (
        Number.isFinite(pendingStartedAt) &&
        Date.now() - pendingStartedAt > ACTIVE_COMPOSE_CREDIT_HOLD_TTL_MS
      ) {
        const { data: staleDebit, error: staleDebitError } = await cinematicAdmin
          .from('credit_debits')
          .select('user_id,amount,refunded_at')
          .eq('render_id', billingReference)
          .maybeSingle()
        if (staleDebitError) {
          console.error('[cinematic] stale pending debit lookup failed:', staleDebitError.message)
          return NextResponse.json(
            { error: 'Your previous AI submission is being reconciled. Please retry shortly.', pending: true, retry_after_ms: 5000 },
            { status: 503 },
          )
        }
        const staleAmount = typeof staleDebit?.amount === 'number'
          ? staleDebit.amount
          : Number(staleDebit?.amount)
        if (
          staleDebit &&
          (staleDebit.user_id !== user.id || !Number.isFinite(staleAmount) || staleAmount !== cost)
        ) {
          console.error('[cinematic] stale pending debit does not match signed claim')
          return NextResponse.json(
            { error: 'Your previous AI submission needs billing review. No new job was submitted.' },
            { status: 503 },
          )
        }
        const alreadyRefunded = typeof staleDebit?.refunded_at === 'string' && Boolean(staleDebit.refunded_at)
        if (staleDebit && !alreadyRefunded && !(await confirmCinematicRefund())) {
          return NextResponse.json(
            { error: 'Your previous AI submission refund is still being confirmed. Please retry shortly.', pending: true, retry_after_ms: 5000 },
            { status: 503 },
          )
        }
        const released = await releaseCinematicClaim({
          db: cinematicAdmin,
          secret: serviceRoleKey,
          userId: user.id,
          generationId,
          reason: staleDebit ? 'stale_pending_refunded' : 'stale_pending_no_debit',
          ...(staleDebit ? { reference: billingReference } : {}),
        })
        if (!released.ok) {
          console.error('[cinematic] stale pending claim release failed:', released.error)
          return NextResponse.json(
            { error: 'Your previous AI submission is being closed safely. Please retry shortly.', pending: true, retry_after_ms: 5000 },
            { status: 503 },
          )
        }
        return NextResponse.json(
          {
            error: staleDebit
              ? `Your previous AI submission expired and ${cost} credits were refunded automatically. Please start a new generation.`
              : 'Your previous AI submission expired before charging. Please start a new generation.',
            creditsRefunded: staleDebit ? cost : 0,
            start_new_generation: true,
          },
          { status: 409 },
        )
      }
      return NextResponse.json(
        { error: 'This AI generation is already being submitted.', pending: true, retry_after_ms: 2500 },
        { status: 409 },
      )
    }

    activeBirthClaim = {
      db: cinematicAdmin,
      secret: serviceRoleKey,
      userId: user.id,
      generationId,
      billingReference,
      debitConfirmed: false,
    }
    const releaseBirthClaim = async (reason: string): Promise<boolean> => {
      if (!activeBirthClaim) return true
      const current = activeBirthClaim
      let releaseReason = reason
      let reference: string | undefined
      if (current.debitConfirmed) {
        const refundConfirmed = await confirmCinematicRefund()
        if (!refundConfirmed) {
          console.error('[cinematic] refusing to release claim before refund is confirmed:', reason)
          return false
        }
        releaseReason = `${reason}_refunded`
        reference = current.billingReference
      }
      const released = await releaseCinematicClaim({
        db: current.db,
        secret: current.secret,
        userId: current.userId,
        generationId: current.generationId,
        reason: releaseReason,
        reference,
      })
      if (!released.ok) {
        console.error('[cinematic] birth claim release failed:', released.error)
        return false
      }
      activeBirthClaim = null
      return true
    }
    releaseActiveBirthClaim = releaseBirthClaim

    // Every concurrent generation inserts first and then audits all signed
    // holds. The last request necessarily sees the earlier reservations.
    const holds = await inspectActiveComposeCreditHolds({
      db: cinematicAdmin,
      secret: serviceRoleKey,
      userId: user.id,
      currentClaimId: acquired.claim.id,
    })
    if (!holds.ok || !holds.currentSeen) {
      console.error('[cinematic] credit hold audit failed:', holds.ok ? 'current claim missing' : holds.error)
      await releaseBirthClaim('hold_audit_failed')
      return NextResponse.json(
        { error: 'Your credit reservation could not be verified. Nothing was submitted.' },
        { status: 503 },
      )
    }
    const { data: currentProfile, error: currentProfileError } = await cinematicAdmin
      .from('profiles')
      // KINEO-TRIAL-BLOCKERS-2026-08-07 — colunas de trial: a RELEITURA de
      // admissão (logo abaixo) tem o seu PRÓPRIO predicado de "conta paga", e
      // ele não conhecia o trial. O gate trial-aware de cima (:685) deixava a
      // conta passar e esta releitura a matava com 402 poucas linhas antes do
      // débito — dois veredictos opostos sobre a mesma conta, na mesma request.
      .select(`video_credits, plan, has_paid, ${TRIAL_ENTITLEMENT_COLUMNS}`)
      .eq('id', user.id)
      .single()
    if (currentProfileError || typeof currentProfile?.video_credits !== 'number') {
      await releaseBirthClaim('balance_lookup_failed')
      return NextResponse.json(
        { error: 'Your credit balance could not be verified. Nothing was submitted.' },
        { status: 503 },
      )
    }
    const currentPlan = String(currentProfile.plan ?? 'free').toLowerCase()
    // KINEO-TRIAL-BLOCKERS-2026-08-07 — mesmo termo do gate de entrada
    // (`trialActive`, :685), agora relido do estado FRESCO: se o trial expirou
    // entre a admissão e aqui (relógio venceu ou o teto de 40 foi atingido por
    // um débito concorrente), isTrialActive() volta false e este 402 é o
    // correto. Os motores Studio continuam FORA — quem chega aqui já passou
    // pelo gate Kling/Veo/Hollywood, que exige `isPaidUser` de verdade.
    // Flag OFF ⇒ termo false ⇒ predicado idêntico ao anterior.
    const currentPaid =
      currentProfile.has_paid === true ||
      PAID_PLANS.has(currentPlan) ||
      freeWeeklyAdmitted || // KINEO-E4-SAIDA-B-2026-09-29: admitido acima pela cota semanal (15 s, Seedance, país da lista); o saldo abaixo segue cobrando
      regionFreeFilmAdmitted || // KINEO-SAIDA-REGIAO-2026-10-07: admitido acima pelo filme grátis de região (15 s, Seedance, 1 por conta); o saldo abaixo segue cobrando
      kidsPedidoAdmitido || // KINEO-KIDS-VENDA-2010: admitido acima pelo pedido infantil (run pendente deste generationId); o saldo abaixo segue cobrando o crédito que o cron financiou
      isTrialActive(currentProfile)
    const currentBalance = Math.max(0, currentProfile.video_credits)
    const heldByOtherJobs = Math.max(0, holds.totalHeld - cost)
    if (!currentPaid || holds.totalHeld > currentBalance) {
      await releaseBirthClaim('insufficient_available_credits')
      return NextResponse.json(
        {
          error: !currentPaid
            ? 'AI Generated videos require a paid plan.'
            : `This generation needs ${cost} credits. ${heldByOtherJobs > 0 ? 'Other active renders already reserve part of your balance. ' : ''}You have ${Math.max(0, currentBalance - heldByOtherJobs)} available.`,
          needed: cost,
          balance: Math.max(0, currentBalance - heldByOtherJobs),
        },
        { status: 402 },
      )
    }

    // ═══ KINEO-SAIDA-REGIAO-2026-10-07 (a) [TRAVA 8.2 — "vai pra tudo" do fundador 07/10] — o filme grátis de região é UM por conta: a trava DEPOIS do próprio claim ═══
    // [KINEO-SAIDA-REGIAO-2026-10-07] A admissão lá em cima conta `videos`, que só nasce quando o render termina: dois pedidos juntos contavam 0.
    // [KINEO-SAIDA-REGIAO-2026-10-07] Aqui, com o claim gravado e os holds auditados: outro crédito reservado, OU qualquer débito `cinematic-*` não
    // [KINEO-SAIDA-REGIAO-2026-10-07] estornado na VIDA da conta, OU leitura que falhou → recusa sem cobrar e solta o claim. Falha estorna; o filme volta.
    if (regionFreeFilmAdmitted) { // KINEO-SAIDA-REGIAO-2026-10-07
      const { count: debitosVida, error: debitosVidaErr } = await cinematicAdmin // KINEO-SAIDA-REGIAO-2026-10-07
        .from('credit_debits') // KINEO-SAIDA-REGIAO-2026-10-07
        .select('render_id', { count: 'exact', head: true }) // KINEO-SAIDA-REGIAO-2026-10-07
        .eq('user_id', user.id) // KINEO-SAIDA-REGIAO-2026-10-07
        .like('render_id', 'cinematic-%') // KINEO-SAIDA-REGIAO-2026-10-07
        .is('refunded_at', null) // KINEO-SAIDA-REGIAO-2026-10-07
      const debitosNaVida = debitosVidaErr || typeof debitosVida !== 'number' ? null : debitosVida // KINEO-SAIDA-REGIAO-2026-10-07
      const outroPedidoRegiao = holds.totalHeld > cost // KINEO-SAIDA-REGIAO-2026-10-07
      if (!regionFreeFilmExclusive({ otherActiveHold: outroPedidoRegiao, lifetimeCinematicDebits: debitosNaVida })) { // KINEO-SAIDA-REGIAO-2026-10-07
        await releaseBirthClaim('region_free_film_in_use') // KINEO-SAIDA-REGIAO-2026-10-07
        await writeServerEvent({ name: REGION_FREE_FILM_REFUSED_EVENT, userId: user.id, path: '/api/generate-video-cinematic', metadata: { reason: debitosNaVida === null ? 'read_failed' : outroPedidoRegiao ? 'other_hold' : 'already_used', held: holds.totalHeld, cost, lifetime_debits: debitosNaVida } }) // KINEO-SAIDA-REGIAO-2026-10-07
        return NextResponse.json({ error: REGION_FREE_FILM_IN_USE_MESSAGE, reason: 'region_free_film_in_use', charged: false, upgrade: '/pricing' }, { status: 402 }) // KINEO-SAIDA-REGIAO-2026-10-07
      } // KINEO-SAIDA-REGIAO-2026-10-07
    } // KINEO-SAIDA-REGIAO-2026-10-07
    // ═══ KINEO-E4-CONSERTO-2026-09-29 [TRAVA 8.2 — "vai E4" do fundador] (revisão de dinheiro, achado 5) ═══
    // A cota semanal é EXCLUSIVA: a admissão acima conta `videos`, que só nasce quando o render termina — dois
    // Seedance de 15 s disparados juntos contavam 0 e passavam os dois. Aqui, DEPOIS de gravar o próprio claim (o
    // "inserir e depois auditar" dos holds, logo acima), outro render dessa conta aparece como hold (antes do débito)
    // ou como débito `cinematic-*` não estornado na semana (depois). Qualquer um dos dois, ou leitura falhou → recusa
    // sem cobrar. Render que falha é estornado (refunded_at) e a semana volta.
    if (freeWeeklyAdmitted) {
      const { count: debitosSemana, error: debitosErr } = await cinematicAdmin
        .from('credit_debits')
        .select('render_id', { count: 'exact', head: true })
        .eq('user_id', user.id)
        .like('render_id', 'cinematic-%')
        .is('refunded_at', null)
        .gte('created_at', new Date(Date.now() - FREE_WEEKLY_FILM_WINDOW_MS).toISOString())
      const exclusivo = freeWeeklyFilmExclusive({ otherActiveHold: holds.totalHeld > cost, weekCinematicDebits: debitosErr || typeof debitosSemana !== 'number' ? null : debitosSemana })
      if (!exclusivo) {
        await releaseBirthClaim('free_weekly_film_in_use')
        await writeServerEvent({ name: FREE_WEEKLY_FILM_EXCLUSIVE_REFUSED_EVENT, userId: user.id, path: '/api/generate-video-cinematic', metadata: { held: holds.totalHeld, cost, week_debits: typeof debitosSemana === 'number' ? debitosSemana : null, read_failed: Boolean(debitosErr) } })
        return NextResponse.json(
          { error: FREE_WEEKLY_FILM_IN_USE_MESSAGE, reason: 'free_weekly_film_in_use', charged: false, upgrade: '/pricing' },
          { status: 402 },
        )
      }
    }

    // KINEO-CAPACITY-2026-08-08 — DISJUNTOR GLOBAL, o último portão antes do
    // dinheiro sair. Fica DEPOIS da checagem de saldo e ANTES do débito de
    // propósito: quem bate no teto não é cobrado, não perde crédito e não
    // precisa de estorno — o caminho mais barato de todos. `releaseBirthClaim`
    // devolve o claim para a próxima tentativa não colidir consigo mesma.
    // Fail-open por dentro: só nega quando a contagem foi lida COM SUCESSO e
    // estourou. Ver a conta que justifica o número em lib/aiRenderCircuitBreaker.
    const aiCap = await checkAiRenderDailyCap(cinematicAdmin)
    if (!aiCap.allowed) {
      await releaseBirthClaim('global_daily_ai_cap')
      return NextResponse.json(
        { error: AI_RENDER_CAP_MESSAGE, code: 'global_daily_ai_cap' },
        { status: 503 },
      )
    }

    // ⚠️ KINEO-DEBITO-DEPOIS-DA-TRAVA-2026-09-02 — O DÉBITO SAIU DAQUI.
    // Ele agora acontece DEPOIS da trava de narração (procure
    // `KINEO-DEBITO-DEPOIS-DA-TRAVA` mais abaixo, logo após o guard).
    //
    // POR QUÊ: o comentário da trava sempre disse "e ela vem ANTES do débito",
    // mas o débito tinha migrado para cá e a promessa virou mentira. O preço
    // disso, medido em 02/09 na conta do albertopopacristian (chegou pelo
    // TAAFT, conta com 62 SEGUNDOS de vida): pediu 60s com 40s de fala, o
    // guard recusou — e no caminho até a recusa os 25 créditos foram
    // DEBITADOS, o teto do reverse trial foi somado, a conta foi carimbada
    // `trial_expired` por `credit_cap`, e só então tudo foi estornado e o
    // trial revivido. Três eventos de dinheiro e um "seu trial acabou" para
    // alguém que nunca chegou a renderizar nada. Ele foi olhar o preço e sumiu.
    //
    // Com o débito aqui embaixo, a recusa didática não toca em crédito nenhum:
    // não há débito, não há estorno, não há `trial_expired`, não há
    // `narration_guard_blocked` com `refunded:true`. O claim continua sendo
    // liberado pelo mesmo caminho de sempre.

    let personagemRelatoFinal: RelatoPersonagem | null = null // KINEO-META95-PERSONAGEM-2010 — o relato da folha (contagens, vereditos, custo), preenchido no bloco da folha; null = nada entra na resposta
    const publishCinematicResponse = async (
      response: Record<string, unknown>,
      requestIds: CinematicRequestId[],
      models: string[],
    ): Promise<NextResponse> => {
      response = { ...response, submission_uncertain: cinematicSubmissionUncertain }
      if (personagemRelatoFinal) response = { ...response, personagem: personagemRelatoFinal } // KINEO-META95-PERSONAGEM-2010 — só com a folha ligada (sem ela, resposta e hash de sempre)
      // [TRAVA 8.2 — Tarefa 0 do pedido de 01/10] KINEO-ESTRELA-SOBRETAXA-ASSINADA-2026-10-01 — a sobretaxa que o `cost` somou vai ASSINADA na resposta do claim (hash + assinatura):
      // o /api/compose confere filme + ESTE número, sem recalcular. Sem estrela, nada entra (resposta e hash de sempre). [KINEO-ESTRELA-SOBRETAXA-ASSINADA-2026-10-01]
      if (estrelaAtiva) response = { ...response, estrela_sobretaxa_cr: estrelaSobretaxaDe(duracaoCobrada) } // KINEO-ESTRELA-SOBRETAXA-ASSINADA-2026-10-01
      cinematicSubmissionCache.set(cacheKey, {
        fingerprint: claimFingerprint,
        creditCost: cost,
        quality: claimQuality,
        engine: claimEngine,
        response,
        requestIds,
        models,
        expiresAt: Date.now() + 10 * 60 * 1000,
      })
      const completed = await completeCinematicClaim({
        db: cinematicAdmin,
        secret: serviceRoleKey,
        userId: user.id,
        generationId,
        fingerprint: claimFingerprint,
        creditCost: cost,
        quality: claimQuality,
        engine: claimEngine,
        response,
        falRequestIds: requestIds,
        falModels: models,
      })
