      }
      return settleDebitAndRespond(completed.claim, response)
    }

    // KINEO-DEGRAU-2026-09-03 — `parsedScript`, `userSaysVerbatim` e `verbatim`
    // são decididos lá em cima, logo depois de `hollywoodPath` (o degrau
    // precisa deles ANTES do custo). A trava abaixo lê os mesmos valores.
    // Quando o degrau desceu a duração, `fit.ok` abaixo é verdadeiro por
    // construção (a função verifica a régua no alvo descido) e a trava passa
    // sem tocar em nada; ela continua sendo a rede para tudo que NÃO desceu.

    // ═══ KINEO-NARRACAO-ENCHE-2026-08-22 — A TRAVA, E ELA VEM ANTES DO DÉBITO ══
    //
    // O caso que mandou construir isto: o fundador reprovou um Kling 3 de 70s
    // cujo roteiro tinha 402 caracteres (73 palavras ≈ 32s de fala). Medido
    // quadro a quadro: luminância NUNCA abaixo de 44 (não havia apagão de
    // imagem, nunca houve) e ~28s de déficit de narração. O nome "apagão"
    // atrasou o diagnóstico por duas rodadas.
    //
    // A poda de cenas mudas (KINEO-CENA-MUDA, mais abaixo) conserta o SINTOMA:
    // o filme sai íntegro, só que curto. Esta trava ataca a CAUSA — e ela tem
    // de vir aqui, ANTES de `generate-video-cinematic` debitar. Um filme
    // Hollywood custa 150 créditos; entregar 28 segundos mudos por esse preço,
    // e só descobrir 6 minutos depois, é o pior desfecho possível para os dois
    // lados. Recusar em 200ms com um número acionável é o melhor.
    //
    // ⚠️ SÓ VALE PARA O CAMINHO VERBATIM, e isso é deliberado: ali o texto é do
    // USUÁRIO e nós não podemos reescrevê-lo (Contrato C1), então a única saída
    // honesta é ele decidir — escrever mais, ou aceitar um vídeo mais curto. No
    // caminho automático quem escreve é o nosso gerador, e a correção certa lá
    // é ele produzir o tamanho certo, não recusar o pedido da pessoa.
    if (verbatim && parsedScript.narration) {
      let fit = narrationFitAt(parsedScript.narration, duration, narrationRate)
      // [TRAVA 8.2 — vai do fundador 29/09 'vai pra todas as 4'] KINEO-DURACOES-CURTAS-2026-09-29 — a duração curta que o MOTOR oferece (15 s; 30 s na
      // [KINEO-DURACOES-CURTAS-2026-09-29] hollywood — lib/durationByEngine supportedDurationsFor) não é "alvo fantasma": sem isto o resgate/aterrissagem abaixo trocava o
      // [KINEO-DURACOES-CURTAS-2026-09-29] 15 pedido por 35 só para escrever a recusa ("you asked for a 35-second video" a quem pediu 15). Fora dos curtos, a lista de sempre.
      const oferecidasDoPortao: readonly number[] = !SUPPORTED_DURATIONS.includes(duration as (typeof SUPPORTED_DURATIONS)[number]) && supportedDurationsFor(typeof body.engine === 'string' ? body.engine : null).includes(duration) ? [...SUPPORTED_DURATIONS, duration] : SUPPORTED_DURATIONS // KINEO-DURACOES-CURTAS-2026-09-29
      // ═══ sprint-v1v4 #20 — NAO RECUSE POR UM NUMERO QUE ELA NAO ESCOLHEU ═══
      // 11 das 15 recusas de narracao em 14 dias mediram o roteiro contra 45s,
      // e 45 nao existe no seletor (35/60/90) desde 20/08. Antes de recusar, o
      // servidor pergunta se o alvo e um alvo que o produto OFERECE. Se nao e,
      // troca pelo maior alvo REAL que a fala enche e segue. Nada de preco,
      // credito ou plano muda (engineCost nao olha duracao). Detalhes e a
      // prova de zero-regressao no cabecalho de lib/durationGhost.ts.
      const resgate = deveResgatar({
        fitOk: fit.ok,
        alvoPedido: duration,
        falaSegundos: fit.speech,
        oferecidas: oferecidasDoPortao, // KINEO-DURACOES-CURTAS-2026-09-29
        maiorQueCabe: largestFittingDuration(fit.speech),
      })
      if (resgate) {
        duration = resgate.alvo
        fit = narrationFitAt(parsedScript.narration, duration, narrationRate)
        console.warn(
          `[narracao] ALVO FANTASMA RESGATADO: pedido ${resgate.fantasma}s nao existe no seletor ` +
          `(${SUPPORTED_DURATIONS.join('/')}); ${resgate.fala}s de fala -> alvo ${resgate.alvo}s.`,
        )
        // Evento com nome proprio: sem isto o resgate seria invisivel e nao
        // haveria como provar (ou desmentir) que ele converteu parede em video.
        try {
          await cinematicAdmin.from('events').insert({
            user_id: user.id,
            name: 'duration_ghost_rescued',
            path: '/api/generate-video-cinematic',
            metadata: {
              ghost_seconds: resgate.fantasma,
              rescued_to_seconds: resgate.alvo,
              speech_seconds: resgate.fala,
              still_short: !fit.ok,
            },
          })
        } catch { /* telemetria nunca derruba a resposta */ }
      }
      // ═══ sprint-v1v4 #39 — SE NADA CABE, ATERRISSA NO PISO ANTES DE RECUSAR ═
      // O resgate acima so age quando ALGUMA duracao do seletor cabe. Quando
      // nenhuma cabe ele devolve null, e ate hoje a recusa saia medida contra o
      // fantasma: houh70985 (01/09 18:00 UTC) ouviu que faltavam 23 palavras
      // para 45s quando, contra os 35s que o produto realmente vende, faltava
      // UMA. A aterrissagem nao aprova nada — `fit` continua reprovado, por
      // construcao — mas o numero da mensagem, o `missing_words` que viaja para
      // o expansor e a duracao do render passam a ser os reais.
      if (!fit.ok) {
        const pouso = deveAterrissar({
          fitOk: fit.ok,
          alvoPedido: duration,
          falaSegundos: fit.speech,
          oferecidas: oferecidasDoPortao, // KINEO-DURACOES-CURTAS-2026-09-29
          maiorQueCabe: largestFittingDuration(fit.speech),
        })
        if (pouso) {
          const faltavamAntes = fit.missingWords
          duration = pouso.alvo
          fit = narrationFitAt(parsedScript.narration, duration, narrationRate)
          console.warn(
            `[narracao] ATERRISSOU NO PISO: alvo ${pouso.fantasma}s nao existe no seletor e ` +
            `nenhuma duracao cabe em ${pouso.fala}s de fala; medindo contra o piso ${pouso.alvo}s ` +
            `(faltavam ${faltavamAntes} palavras, faltam ${fit.missingWords}).`,
          )
          try {
            await cinematicAdmin.from('events').insert({
              user_id: user.id,
              name: 'duration_ghost_floored',
              path: '/api/generate-video-cinematic',
              metadata: {
                ghost_seconds: pouso.fantasma,
                floored_to_seconds: pouso.alvo,
                speech_seconds: pouso.fala,
                missing_words_before: faltavamAntes,
                missing_words_after: fit.missingWords,
                // Tripwire do contrato: aterrissar NUNCA pode aprovar. Se isto
                // vier true uma vez, a prova do cabecalho esta errada.
                unblocked: fit.ok,
              },
            })
          } catch { /* telemetria nunca derruba a resposta */ }
        }
      }
      // KINEO-DURACAO-SEGUE-O-ROTEIRO-2026-09-19 — roteiro da própria pessoa (este bloco só roda em verbatim) e
      // uma duração do seletor cabe na fala → desce e renderiza, em vez de recusar e pedir palavras. Caso Axel:
      // 34 s de fala, seletor em 60 s, duas recusas sem filme. Ver lib/durationFollowsScript.ts.
      if (!fit.ok) {
        const seguir = decideDurationFollowsScript({
          fitOk: fit.ok,
          ownScript: true,
          requestedSeconds: duration,
          speechSeconds: fit.speech,
          largestFitting: largestFittingDuration(fit.speech),
          floorSeconds: hollywoodPath ? AUTOFIT_DOWN_FLOOR_SECONDS_HOLLYWOOD : 15,
        })
        if (seguir) {
          const faltavam = fit.missingWords
          duration = seguir.to
          fit = narrationFitAt(parsedScript.narration, duration, narrationRate)
          console.warn(`[narracao] DURACAO SEGUE O ROTEIRO: ${seguir.speechSeconds}s de fala, seletor em ${seguir.from}s → filme de ${seguir.to}s (faltavam ${faltavam} palavras; agora ${fit.ok ? 'cabe' : 'ainda falta'}).`)
          try {
            await cinematicAdmin.from('events').insert({
              user_id: user.id,
              name: DURATION_FOLLOWED_SCRIPT_EVENT,
              path: '/api/generate-video-cinematic',
              metadata: { version: seguir.version, from_seconds: seguir.from, to_seconds: seguir.to, speech_seconds: seguir.speechSeconds, missing_words_before: faltavam, fits_now: fit.ok, engine: body.engine ?? null },
            })
          } catch { /* telemetria nunca derruba a resposta */ }
        }
      }
      if (!fit.ok) {
        // ═══ KINEO-GUARD-DEVOLVE-2026-08-25 — O GUARD COBRAVA E NÃO DEVOLVIA ═══
        // O comentário acima dizia "antes do débito", mas o claim+débito
        // migraram para ANTES deste ponto (linha ~1448) e a promessa
        // envelheceu virando prisão: pedrohscordeiro (trial de 25cr, 25/08
        // 14:03) escreveu roteiro de 25s, pediu 35s, levou o 422 educativo —
        // e ficou com 12cr PRESOS num claim pending eterno, que o painel
        // ainda mostrava como "RENDERING". Primeiro contato com o produto:
        // metade do trial confiscada por uma recusa didática. O release é o
        // mesmo caminho do dry-run/FAILFAST: estorna e libera na hora.
        await releaseBirthClaim('narration_too_short_no_charge')
        // KINEO-GUARD-VISIVEL-2026-08-25 (fundador: "isso precisa refletir pra
        // mim no adm") — o bloqueio educativo ganha um evento com NOME próprio,
        // porque o /admin/live só enxerga nomes: sem isto, o guard aparecia
        // como um FAILED genérico + RENDERING eterno, ilegível. Fire-and-forget.
        try {
          await cinematicAdmin.from('events').insert({
            user_id: user.id,
            name: 'narration_guard_blocked',
            path: '/api/generate-video-cinematic',
            // KINEO-DEBITO-DEPOIS-DA-TRAVA-2026-09-02 — `refunded` era `true`
            // chumbado. Agora a trava roda ANTES do débito, então o normal é
            // NÃO ter havido cobrança nenhuma: o campo passa a dizer a verdade
            // (`charged` é o que o claim registrou de fato) e `refunded` só é
            // true se, por algum caminho, o débito tiver acontecido antes.
            metadata: {
              speech_seconds: Math.round(fit.speech),
              target_seconds: duration,
              missing_words: fit.missingWords,
              charged: activeBirthClaim?.debitConfirmed === true,
              refunded: activeBirthClaim?.debitConfirmed === true,
            },
          })
        } catch { /* telemetria nunca derruba a resposta */ }
        console.warn(
          `[narracao] RECUSADO (claim liberado, crédito devolvido): ${Math.round(fit.speech)}s de fala para ` +
          `alvo de ${duration}s (cobertura ${(fit.coverage * 100).toFixed(0)}%, ` +
          `mínimo ${(MIN_COVERAGE * 100).toFixed(0)}%).`,
        )
        // ═══ sprint-v1v4 #22 — ESTA RECUSA SABE SE JA HOUVE OUTRA ═══════════
        // Medido: 154 das 283 falhas de 30d aconteceram a menos de CINCO
        // minutos da falha anterior da mesma pessoa, e quem falha 3+ vezes faz
        // 0,66 videos contra 1,29 de quem falha uma. A segunda mensagem
        // repetia a licao da primeira — que ja tinha se provado inutil.
        // Best-effort integral: qualquer tropeco devolve a mensagem de hoje,
        // byte a byte. Posicao 1 (a maioria) tambem devolve a de hoje.
        const msgGuard = narrationTooShortMessage(fit, SUPPORTED_DURATIONS)
        let espiralGuard: ReturnType<typeof avaliarEspiral> = null
        try {
          const agoraEsp = Date.now()
          espiralGuard = avaliarEspiral({
            historico: await historicoDeParedes(cinematicAdmin, user.id, agoraEsp),
            paredeAtual: 'narracao_curta',
            agora: agoraEsp,
          })
          if (espiralGuard) {
            await cinematicAdmin.from('events').insert({
              user_id: user.id,
              name: 'refusal_spiral',
              path: '/api/generate-video-cinematic',
              metadata: {
                posicao: espiralGuard.posicao,
                parede: espiralGuard.parede,
                parede_anterior: espiralGuard.paredeAnterior,
                mesma_parede: espiralGuard.mesmaParede,
                minutos_desde_ultima: espiralGuard.minutosDesdeUltima,
                paredes: espiralGuard.paredes,
                sufixo_entregue: espiralGuard.sufixo !== null,
              },
            })
          }
        } catch { /* espiral nunca derruba nem atrasa a recusa */ }
        return NextResponse.json(
          {
            error: mensagemComEspiral(msgGuard, espiralGuard),
            narrationTooShort: true,
            // A UI usa estes para oferecer o botão "usar Xs" sem a pessoa ter
            // de fazer conta nenhuma.
            speechSeconds: Math.round(fit.speech),
            // sprint-v1v4 #11 — era um arredondamento cru para multiplo de 5,
            // que podia (a) nao existir no seletor e (b) nem passar na regua:
            // com 11s de fala isto devolvia 15s, e 11/15 = 73% seria recusado
            // outra vez. Agora e a maior duracao DO SELETOR que a fala enche,
            // ou 0 (a UI ja trata 0 como 'nao ha botao honesto').
            suggestedDuration: largestFittingDuration(fit.speech) ?? 0,
            missingWords: fit.missingWords,
          },
          { status: 422 },
        )
      }
    }

    // ═══ KINEO-DEBITO-DEPOIS-DA-TRAVA-2026-09-02 ════════════════════════════
    // Este bloco vivia ~60 linhas acima, ANTES da trava de narração (ver a nota
    // no lugar de onde ele saiu). O valor cobrado é o MESMO `cost` calculado na
    // linha ~1386 a partir da duração PEDIDA — o resgate de alvo fantasma acima
    // pode ter mudado `duration`, e mudar o preço aqui quebraria o contrato de
    // custo que o claim assinou e que o /api/compose confere (regressão de
    // 02/09 de manhã: "clips do not match"). Preço não muda; só a ORDEM mudou.
    //
    // Close the gap between an in-memory/events hold and every other debit
    // route. The database RPC atomically spends this generation's credits
    // before OpenAI/Fal work begins; concurrent spenders cannot double-use the
    // same balance. The deterministic key makes retries safe.
    const upfrontDebit = await ensureCinematicDebit(cost)
    if (!upfrontDebit.ok) {
      console.error('[cinematic] upfront debit failed:', upfrontDebit.error)
      await releaseBirthClaim('upfront_debit_rejected')
      return NextResponse.json(
        {
          error: upfrontDebit.insufficient
            ? `This generation needs ${cost} credits. Your available balance changed before it could start.`
            : 'Your credit charge could not be confirmed. Nothing was submitted.',
          needed: cost,
          balance: upfrontDebit.balance,
        },
        { status: upfrontDebit.insufficient ? 402 : 503 },
      )
    }
    if (activeBirthClaim) activeBirthClaim.debitConfirmed = true
    // KINEO-TRIAL-DOUBLECOUNT-2026-08-07 — o débito desta request está feito e
    // confirmado; settleDebitAndRespond() não precisa repetir o mesmo RPC.
    debitConfirmedThisRequest = { ok: true, balance: upfrontDebit.balance, insufficient: false, error: '' }
    // KINEO-SAIDA-REGIAO-2026-10-07 (a) — o filme grátis de região foi GASTO neste render (débito confirmado). Falha depois = estorno, e o filme volta.
    if (regionFreeFilmAdmitted) await writeServerEvent({ name: REGION_FREE_FILM_USED_EVENT, userId: user.id, path: '/api/generate-video-cinematic', metadata: { generation_id: generationId, quality: costQuality, seconds: duration, cost, balance_after: upfrontDebit.balance, country: paisDoRequest(req.headers) } }) // KINEO-SAIDA-REGIAO-2026-10-07

    // ═══ V2-PRECO-DA-DURACAO-ENTREGUE-2026-09-23 — autorização nominal do fundador ("vai v2 e v3", 23/09, trava 8.2) ═══
    // O `cost` é assinado no claim com a duração PEDIDA e não pode mudar aqui (KINEO-DEBITO-DEPOIS-DA-TRAVA: mudar o preço
    // quebra o contrato que o /api/compose confere — "clips do not match", 02/09). Mas "a duração segue o roteiro" e o
    // resgate de alvo fantasma podem ENCURTAR o filme depois do preço: caso axel.dickburt (19/09), Veo pedido a 60 s, filme de
    // 35 s, cobrado 100 em vez de 59 (reembolsado à mão em 23/09). Agora a diferença volta NA HORA, pelo mesmo RPC atômico
    // de crédito, uma vez por geração (evento com a referência de cobrança), sem tocar claim nem débito.
    // Limite conhecido e aceito: se este render ainda falhar depois e for estornado INTEIRO, a pessoa fica com a diferença
    // a mais (a favor dela, só no caso raro de filme encurtado + falha).
    if (duration < duracaoCobrada) {
      const precoEntregue = creditCostForDuration(costQuality, true, duration) + estrelaSobretaxaDe(duration) // KINEO-ESTRELA-DO-FILME-2026-09-29: a estrela da duração entregue (a diferença dela volta junto)
      const diferenca = cost - precoEntregue
      if (diferenca > 0) {
        try {
          const { data: jaAjustado } = await cinematicAdmin
            .from('events').select('id').eq('user_id', user.id).eq('name', 'cinematic_duration_price_adjusted')
            .eq('metadata->>billing_reference', billingReference).limit(1)
          if (!jaAjustado || jaAjustado.length === 0) {
            const { error: ajusteErr } = await cinematicAdmin.rpc('add_video_credits', { p_user: user.id, p_amount: diferenca })
            if (ajusteErr) throw new Error(ajusteErr.message)
            void writeServerEvent({ name: 'cinematic_duration_price_adjusted', userId: user.id, path: '/api/generate-video-cinematic', metadata: { billing_reference: billingReference, engine: claimEngine, quality: costQuality, requested_seconds: duracaoCobrada, delivered_seconds: duration, charged: cost, delivered_price: precoEntregue, refunded: diferenca, version: 'v2_preco_da_duracao_entregue_20260923' } })
            console.log(`[cinematic] V2: filme ${duracaoCobrada}s → ${duration}s; devolvidos ${diferenca} cr (cobrado ${cost}, preço entregue ${precoEntregue})`)
          }
        } catch (e) {
          // Nunca derruba o render por causa do ajuste: fica registrado para conserto à mão.
          console.error('[cinematic] V2 ajuste de preço falhou:', e instanceof Error ? e.message : String(e))
          void writeServerEvent({ name: 'cinematic_duration_price_adjust_failed', userId: user.id, path: '/api/generate-video-cinematic', metadata: { billing_reference: billingReference, requested_seconds: duracaoCobrada, delivered_seconds: duration, owed: diferenca } })
        }
      }
    }

    // #442 — in verbatim mode the final video follows the SCRIPT length, not the
    // selected duration button (the script is narrated in full). The clip count
    // was still derived from the button, so a long script + a short button
    // (e.g. 45) under-provisioned clips and compose REPEATED one to fill the gap
    // (the ~2s repeated shot). Re-size the clip count to the actual narration:
    // each Seedance clip is 10s, so we need ceil(narration_seconds / 10) clips
    // for footage to cover the whole video. Estimate is biased to slightly MORE
    // clips (lower words/sec) since extra footage is just trimmed — never repeated.
    // Stays within the tested 2..6 range; never drops below the button's count.
    if (verbatim) {
      const SECONDS_PER_CLIP = (wantsVeo || wantsSora) ? 8 : 10 // Veo/Sora 8s, Seedance/Kling 10s
      const WORDS_PER_SECOND = 2.5 // ~ElevenLabs at speed 1.05 (conservative)
      const words = parsedScript.narration.split(/\s+/).filter(Boolean).length
      const estSeconds = words / WORDS_PER_SECOND
      const needed = Math.ceil(estSeconds / SECONDS_PER_CLIP)
      const sized = Math.max(clipCount, Math.min(9, needed))
      if (sized !== clipCount) {
        console.log(`[cinematic] #442 verbatim clip count ${clipCount} -> ${sized} (script ~${Math.round(estSeconds)}s, ${words} words)`)
        clipCount = sized
      }
    }

    // ═══ KINEO-KLING25-PLANOS-5S-2026-09-28 — Kling 2.5 em planos de 5 s (fundador 28/09: "mais variedade de cenas") ═══
    // Até aqui: ⌈d/9⌉ planos de 10 s (35 s → 4; 60 s → 7; 90 s → 9) e, no verbatim, ⌈fala/10⌉ (#442). Agora a imagem ÚTIL
    // necessária (o compose tira 0,16 s de cada plano) vira planos de 5 s (a fal cobra por segundo, US$ 0,07/s). Modo IA:
    // o filme do botão + 3 s de folga. Verbatim: o roteiro no passo de planejamento (≤ 2,3 pal/s, a voz mais lenta medida
    // nos filmes reais) — este número é provisório: o roteiro em prosa é dividido mais abaixo (kling25VerbatimPlan), com
    // cortes e segundos decididos juntos para CADA plano caber a sua fala. Seedance/Veo/Sora: nada roda aqui.
    // [TRAVA 8.2] KLING25-60S-TETO (28/09): teto de 12 planos só no modo IA (o escritor de cenas corta em 12); no roteiro
    // pronto o teto acompanha a imagem que o filme pede (kling25MaxShots: 60 s → 14, 90 s → 18) — o ensaio de $0 de 203
    // palavras batia no 12 e enchia com planos de 10 s; o fundador quer ~13-14 planos de 5 s num 60 s com 65-70 s de fala.
    let kling25Footage = 0
    if (wantsKling) {
      const palavrasDoRoteiro = verbatim ? parsedScript.narration.split(/\s+/).filter(Boolean).length : 0
      kling25Footage = kling25FootageNeeded({ durationSeconds: duration, verbatimWords: palavrasDoRoteiro, wordsPerSecond: narrationRate.wordsPerSecond })
      const planos = kling25ShotCount(kling25Footage, { verbatim })
      console.log(`[cinematic] KLING25-PLANOS-5S: ${clipCount} planos de 10 s → ${planos} planos de 5 s (imagem necessária ${kling25Footage}s${verbatim ? `, roteiro de ${palavrasDoRoteiro} palavras` : ''})`)
      clipCount = planos
    }

    // ═══ [TRAVA 8.2] VEO-MODO-IA-2026-09-29 — o escritor do Veo 3.1 em modo IA é dimensionado para planos de ~6 s ═══
    // A linha do Veo acima (⌈s/8⌉ + 1, intocada: 35 s → 6; 60 s → 9; 90 s → 12) valia para os dois modos, e o modo IA saía
    // em '8s' fixos por cena. Agora, SÓ no Veo em modo IA ("Let AI structure my text"), o número de cenas pedido ao escritor
    // mira a média real dos planos que a imagem vai ter (lib/cinematic/veoShots veoShotCountAI: imagem útil do filme + 3 s
    // em planos de 6 s, teto 12 — 35 s → 7; 45 s → 9; 60 s → 12; 90 s → 12), o padrão de kling25ShotCount no Kling 2.5. O
    // roteiro pronto (verbatim) segue o divisor de VEO-PLANOS; Seedance/Kling/Sora: `wantsVeo` falso, nada roda aqui.
    let veoFootage = 0
    if (wantsVeo && !verbatim) {
      veoFootage = veoFootageNeededAI(duration)
      const planos = veoShotCountAI(veoFootage)
      console.log(`[cinematic] VEO-MODO-IA: ${clipCount} cenas de 8 s → ${planos} cenas de ~${veoAverageShotSecondsAI(planos, veoFootage)} s (imagem necessária ${veoFootage}s)`)
      clipCount = planos
    }

    // ═══ [TRAVA 8.2 — "vai" do 3x6] KINEO-SEEDANCE-15S-3X6-2026-09-29 — o filme de 15 s no Seedance 1.5 são 3 clipes ═══
    // Fundador, 29/09: "3x6 gostei dessa opção bora fazer". Até aqui o 15 s pedia ⌈15/9⌉ = 2 clipes de 10 s (e o #442 acima
    // subia para 3 com roteiro longo); o canário de 29/09 04:34 UTC (45 palavras, 2 × 10 s) saiu com o clipe 0 repetido
    // nos últimos 2,9 s. Agora: EXATAMENTE 3 cenas, em verbatim e no modo IA; os segundos de cada clipe (6|7|8, pela fala)
    // saem mais abaixo, quando as cenas existem (seedanceClipSeconds), e vão explícitos à fal no i2v e no t2v de reserva.
    // Só duration 15 no Seedance 1.5 pelo MESMO predicado que autoriza o 15 s (isSeedance15, que checarDuracao usa acima —
    // todo outro motor a 15 s já foi recusado com 422), e nunca Kling/Veo/Sora: 35/60/90 e os outros motores não passam aqui.
    const seedanceShortFilm = duration === SEEDANCE_SHORT_SECONDS && isSeedance15(typeof body.engine === 'string' ? body.engine : null) && !wantsKling && !wantsVeo && !wantsSora
    if (seedanceShortFilm) clipCount = SEEDANCE_SHORT_CLIPS

    // ═══ KINEO-ESCRITOR-CLASSICO-SABE-A-DURACAO-2026-09-12 — o pente fino de $0
    // (12/09) mostrou o Seedance em modo IA nascendo com 74 palavras para 60 s
    // (24 s de fala): o mesmo "10-22 palavras por cena" que o vigia consertou no
    // Kineo 1 às 19:30 de 11/09. O compose reescrevia o corpo sob clipes PAGOS
    // da fal escolhidos para outro texto. Mesma régua (targetWordCount, 3,1
    // pal/s) e a língua do texto; só no caminho clássico (o hollywood tem o seu).
    const classicWriterOptions = { wordsPerScene: wordsPerSceneFor(duration, clipCount, narrationRate.wordsPerSecond), language: narrationLanguage.language } // KINEO-RITMO-POR-VOZ-2026-09-15: a mesma régua do portão e do dry-run
