    // [KINEO-DURACOES-CURTAS-2026-09-29] [Pexels: …] de todos os blocos que a sua fala toca (lib/durationByEngine pistasDosTrechos). Motivo — dinheiro e bloco: bloco a
    // [KINEO-DURACOES-CURTAS-2026-09-29] bloco, um HOOK de 13 palavras pedia 10 s de Kling (11 cabem em 5 s) e 4 blocos viravam 25-30 s de imagem para ~16 s de fala
    // [KINEO-DURACOES-CURTAS-2026-09-29] (15 cr ≈ US$ 2,75 contra ≈ US$ 2,80 de fal+still+voz: margem NEGATIVA, executado no guardião); pelo divisor são 20 s. E
    // [KINEO-DURACOES-CURTAS-2026-09-29] nenhum bloco some (resolveVerbatimSegments sorteava blocos quando havia mais blocos que planos). Nenhuma palavra muda: as
    // [KINEO-DURACOES-CURTAS-2026-09-29] falas dos planos somam a narração. 35/60/90, Seedance e hollywood: nada roda aqui.
    if ((wantsKling || wantsVeo) && duration === SEEDANCE_SHORT_SECONDS && verbatim && parsedScript.segments.length > 0 && parsedScript.narration) { // KINEO-DURACOES-CURTAS-2026-09-29
      const planoCurto = wantsKling ? kling25VerbatimPlan(parsedScript.narration, { durationSeconds: duration, wordsPerSecond: narrationRate.wordsPerSecond }) : veoVerbatimPlan(parsedScript.narration, { durationSeconds: duration, wordsPerSecond: narrationRate.wordsPerSecond }) // KINEO-DURACOES-CURTAS-2026-09-29
      if (planoCurto.chunks.length > 0) { // KINEO-DURACOES-CURTAS-2026-09-29
        const pistasCurtas = pistasDosTrechos(parsedScript.segments, planoCurto.chunks) // KINEO-DURACOES-CURTAS-2026-09-29
        scenes = planoCurto.chunks.map((fala, i) => ({ description: pistasCurtas[i] || fala, voiceover: fala, caption: shortCaptionFromVoiceover(fala), stockSearchQuery: pistasCurtas[i] || fala, clipSeconds: planoCurto.seconds[i] })) // KINEO-DURACOES-CURTAS-2026-09-29
        console.log(`[cinematic] KINEO-DURACOES-CURTAS: 15 s ${wantsKling ? 'Kling 2.5' : 'Veo 3.1'} marcado (${parsedScript.segments.length} blocos) em ${scenes.length} planos [${planoCurto.seconds.join(',')}] pelo divisor da fala, pistas herdadas`) // KINEO-DURACOES-CURTAS-2026-09-29
        clipCount = scenes.length // KINEO-DURACOES-CURTAS-2026-09-29
        if (wantsVeo) veoMarcadoRelato = null // KINEO-DURACOES-CURTAS-2026-09-29: o relato do VEO-MARCADO descrevia os planos substituídos
      } // KINEO-DURACOES-CURTAS-2026-09-29
    } // KINEO-DURACOES-CURTAS-2026-09-29

    // ═══ KINEO-KLING25-PLANOS-5S-2026-09-28 — no Kling 2.5 o roteiro verbatim em prosa vira planos que CABEM a própria fala
    // (lib/cinematic/klingShots kling25VerbatimPlan). Revisão adversarial (28/09, 06fe798a): o divisor por frase fazia cenas
    // de 6 a 23 palavras e dava 5 s a cenas de 15-20 (6-8 s de fala) — a imagem corria na frente da voz. Agora cortes e
    // segundos saem juntos: cada bloco cabe na parte útil do seu plano no passo de planejamento (≤ 2,3 pal/s; 5 s → até 11
    // palavras, 10 s → até 22), fim de frase quando o preço é o mesmo, vírgula dentro de frase que não cabe num plano,
    // palavra só sem outro jeito. O divisor de palavras iguais logo acima continua sendo o de Seedance/Veo, byte a byte;
    // roteiro com marcadores mantém os blocos do autor. Nenhuma palavra muda: a soma das cenas é o roteiro.
    if (wantsKling && verbatim && parsedScript.segments.length === 0 && scenes.length > 0) {
      const plano = kling25VerbatimPlan(parsedScript.narration, { durationSeconds: duration, wordsPerSecond: narrationRate.wordsPerSecond })
      if (plano.chunks.length > 0) {
        scenes = plano.chunks.map((fala, i) => {
          const pista = kling25VisualHint(fala)
          return { description: pista, voiceover: fala, caption: shortCaptionFromVoiceover(fala || pista), stockSearchQuery: pista, clipSeconds: plano.seconds[i] }
        })
        console.log(`[cinematic] KLING25-PLANOS-5S: verbatim em ${scenes.length} planos [${plano.seconds.join(',')}] (passo ${plano.pace} pal/s: 5 s ≤ ${plano.fitShort} palavras, 10 s ≤ ${plano.fitLong}; filme ≈ ${plano.needSeconds}s)`)
        clipCount = scenes.length
      }
    }

    // ═══ KINEO-ZERO-SCENES-FALLBACK-2026-09-04 — construtor vazio nao vira filme perdido ═══
    //
    // archiveunknownmedia@gmail.com (04/09) chegou ao despacho com scenes=[] TRES
    // vezes seguidas: crédito debitado, zero POSTs, estorno, e a tela culpava o
    // fornecedor (corrigido no #21). Pelo código, nenhum construtor deveria
    // devolver vazio para texto não-vazio: generateScenes preenche até o
    // clipCount e resolveVerbatimSegments só esvazia sem narração. Mas o evento
    // cinematic_dispatch_result (planned:0, http 503) prova que aconteceu, e o
    // texto original de 922 chars não fica guardado — a telemetria
    // cinematic_zero_scenes_planned do #21 é quem vai dizer o formato exato.
    //
    // Aqui: quando o construtor escolhido devolve ZERO cenas, o OUTRO tenta.
    //   verbatim → planner de IA sobre o texto cru (o cliente pediu "as is",
    //              mas não há fala a preservar; melhor um filme que erro);
    //   ai → divisor determinístico do texto, SÓ se o texto não parece uma
    //        instrução ("Create a 60-second short about...") — narrar uma
    //        instrução em voz alta seria pior que a mensagem verdadeira do #21,
    //        que manda "deixar a IA estruturar" (foi o que salvou a 4ª tentativa).
    // Para todo pedido que HOJE gera filme (scenes.length > 0) este bloco não
    // executa uma linha — trava de qualidade do fundador (03/09) preservada.
    if (scenes.length === 0 && prompt.trim().length > 0) {
      const origem = verbatim ? 'verbatim' : 'ai'
      const pareceInstrucao = looksLikeInstruction(prompt)
      let recuperadas: typeof scenes = []
      let via: 'unbracket' | 'ai_planner' | 'verbatim_split' | 'none' = 'none'
      try {
        if (verbatim) {
          // KINEO-UNBRACKET-2026-09-04 — CAUSA RAIZ REPRODUZIDA: cleanNarration
          // (lib/scriptParser.ts) apaga tudo entre colchetes, porque [Pexels: ...]
          // e direcao de cena. O ChatGPT devolve roteiros com TODA fala entre
          // colchetes ("[Narrator: ...]", "[HOOK – 0:00-0:02: ...]"): a narracao
          // vira vazia, resolveVerbatimSegments devolve [] e o filme morre com
          // credito debitado. Probes de 04/09: 3 formatos assim -> 0 chars; sem
          // os colchetes -> 107-154 chars, 7 segmentos. Primeira tentativa,
          // portanto: tirar colchetes (e faixas de tempo "0:00-0:02:", que a TTS
          // leria em voz alta) e re-parsear — sao as PALAVRAS DO CLIENTE, que e
          // o que "use my script as is" promete. So se isso tambem der vazio a
          // IA reescreve (segundo recurso abaixo).
          // Linha que e so direcao de cena ('Visual: ...', 'Camera: ...', 'Music: ...')
          // sai antes do re-parse: recuperar as palavras do cliente nao pode virar
          // uma voz lendo 'Visual: stormy sky'. Se so sobrar direcao, cai na IA.
          const DIRECAO_LINHA = /^\s*(visual|visuals|camera|shot|shots|music|sfx|sound|style|tone|lighting|title|format|duration|aspect|caption|captions|text on screen|on-screen text|b-roll|broll|scene\s*\d+)\s*[:\-\u2013]/i
          const desembrulhado = prompt
            .replace(/\b\d{1,2}:\d{2}\s*[-\u2013]\s*\d{1,2}:\d{2}\s*:?/g, ' ')
            .split(/\r?\n/)
            .map((l) => l.replace(/[\[\]]/g, ' '))
            .filter((l) => !DIRECAO_LINHA.test(l))
            .join('\n')
          const reparse = parseUserScript(desembrulhado)
          const beats = reparse.narration.trim() ? resolveVerbatimSegments(reparse, clipCount) : []
          if (beats.length > 0) {
            recuperadas = beats.map((seg) => ({
              description: seg.pexelsQuery,
              voiceover: seg.voiceover,
              caption: shortCaptionFromVoiceover(seg.voiceover || seg.pexelsQuery),
              stockSearchQuery: seg.pexelsQuery,
            }))
            via = 'unbracket'
            // [TRAVA 8.2 — "vai" do 3x6] KINEO-SEEDANCE-15S-3X6-2026-09-29 — revisão de dinheiro (29/09): este resgate roda DEPOIS
            // da divisão em 3 blocos acima; um roteiro todo entre colchetes com só HOOK + PAYOFF saía com 2 cenas, cada uma com os
            // segundos pensados para 3 clipes (2 × 6 = 12 s de imagem para ~17 s de fala → reuso). A prosa desembrulhada inteira
            // vai ao mesmo divisor de palavras equilibradas, em 3 blocos; nenhuma palavra muda.
            if (seedanceShortFilm && recuperadas.length < SEEDANCE_SHORT_CLIPS) {
              const blocos3 = resolveVerbatimSegments({ segments: [], narration: reparse.narration }, SEEDANCE_SHORT_CLIPS)
              if (blocos3.length > recuperadas.length) recuperadas = blocos3.map((seg) => ({ description: seg.pexelsQuery, voiceover: seg.voiceover, caption: shortCaptionFromVoiceover(seg.voiceover || seg.pexelsQuery), stockSearchQuery: seg.pexelsQuery }))
            }
          } else {
            const generated = await generateScenes(prompt.slice(0, SCENE_WRITER_INPUT_MAX_CHARS), clipCount, hollywoodPath ? undefined : classicVisualPolicy, hollywoodPath ? undefined : classicWriterOptions)
          recuperadas = generated.map((s) => ({
            description: s.description,
            voiceover: s.voiceover ?? '',
            caption: s.caption ?? shortCaptionFromVoiceover(s.description),
            stockSearchQuery: s.stockSearchQuery,
            aiPrompt: s.description,
          }))
            via = 'ai_planner'
          }
        } else if (!pareceInstrucao) {
          const picked = resolveVerbatimSegments(parseUserScript(prompt), clipCount)
          recuperadas = picked.map((seg) => ({
            description: seg.pexelsQuery,
            voiceover: seg.voiceover,
            caption: shortCaptionFromVoiceover(seg.voiceover || seg.pexelsQuery),
            stockSearchQuery: seg.pexelsQuery,
          }))
          via = 'verbatim_split'
        }
      } catch (e) {
        console.warn('[cinematic] zero-scenes fallback falhou:', e instanceof Error ? e.message : String(e))
      }
      if (recuperadas.length > 0) scenes = recuperadas
      try {
        await cinematicAdmin.from('events').insert({
          user_id: user.id,
          name: 'cinematic_zero_scenes_recovered',
          path: '/api/generate-video-cinematic',
          metadata: {
            generation_id: generationId,
            from: origem,
            via,
            recovered: recuperadas.length,
            clip_count: clipCount,
            looks_like_instruction: pareceInstrucao,
            has_markers: parsedScript.hasMarkers === true,
            segments: parsedScript.segments.length,
            narration_chars: parsedScript.narration.length,
            prompt_chars: prompt.length,
          },
        })
      } catch { /* telemetria nunca derruba a resposta */ }
    }
    if (!verbatim) { const metaDasCenas = cenasSemMetaTexto(scenes, shortCaptionFromVoiceover); if (metaDasCenas.removidas.length) void writeServerEvent({ name: CENA_META_TEXTO_EVENTO, userId: user.id, path: '/api/generate-video-cinematic', metadata: { generation_id: generationId, scenes: metaDasCenas.cenas, removed: metaDasCenas.removidas.map((f) => f.slice(0, 160)), engine: typeof body.engine === 'string' ? body.engine : 'seedance', version: 'meta95_ideia_1910' } }) } // KINEO-META95-IDEIA-1910 — caminho antigo (generateScenes, verbatim=false): fala que descreve a cena/instrução/"voiceover" (5cb320bb) sai como FRASE INTEIRA, nunca é narrada; o roteiro do cliente (verbatim) nunca é tocado
    // L2B - prefer the smart BrollPlan per-scene cinematic prompt when provided
    const decisaoPlanoDeBroll = decidirPlanoDeBroll({ blocosDoPlano: planScenes.length, falasDasCenas: scenes.map((s) => s.voiceover), falasDosBlocos: parsedScript.segments.map((s) => s.voiceover), verbatim }) // KINEO-TRILHA-15S — o plano só vale se as cenas do filme SÃO os blocos dele, um por um (lib/cinematic/planoDeBroll.ts)
    const planoDeBrollAplicado = hollywoodPath ? planScenes.length > 0 : decisaoPlanoDeBroll.aplicar // KINEO-TRILHA-15S — hollywood: como sempre (o planejador dele reescreve as cenas)
    if (!hollywoodPath && planScenes.length > 0 && !planoDeBrollAplicado) { console.log(`[cinematic] KINEO-TRILHA-15S: plano de b-roll ignorado (${decisaoPlanoDeBroll.motivo}: ${planScenes.length} blocos no plano, ${scenes.length} cenas no filme) — cada imagem nasce da fala do próprio clipe`); void writeServerEvent({ name: 'broll_plan_descartado', userId: user.id, path: '/api/generate-video-cinematic', metadata: { generation_id: generationId, ...decisaoPlanoDeBroll, engine: typeof body.engine === 'string' ? body.engine : 'seedance', duration, verbatim, dry_run: body.dry_run === true } }) } // KINEO-TRILHA-15S
    if (planoDeBrollAplicado) { // KINEO-TRILHA-15S — era: if (planScenes.length > 0) {
      scenes = scenes.map((s, i) => { const bp = planScenes[i]?.brollPrompt; return bp && bp.trim().length > 20 ? { ...s, aiPrompt: bp.trim() } : s })
    }

    // #441 — verbatim path has no cinematic description (description === stock
    // query). Generate a shot description in the approved format from the
    // narration so Seedance gets a shot to direct, not keyword soup. Best-effort:
    // on failure each scene falls back to its stock query in submitAllScenes.
    // KINEO-HOLLYWOOD-2026-07-09 — skipped for hollywood: planHollywoodScenes
    // writes its own per-scene prompts (people allowed), so the faceless
    // description pass would be wasted work.
    // [TRAVA 8.2] KLING25-DESCRICOES-2026-09-28 — cobertura TOTAL e fallback que nunca é a fala. Render real 28/09 02:35 UTC
    // (Kling 2.5, 18 planos, 17 descrições): a cena 18 caía em `stockSearchQuery`, que no verbatim são as PALAVRAS FALADAS
    // (kling25VisualHint / verbatimBeats.pexelsQuery) — "a monster like this… Follow for the next one" virou dinossauro.
    // Agora: acima de 12 cenas o descritor vai em 2 lotes paralelos, as faltantes são re-pedidas uma vez, e a cena que
    // AINDA ficar sem descrição nasce do SUJEITO da vizinha válida com outro enquadramento (completeSceneDescriptions);
    // fala que é só CTA repete o assunto do filme. Caminho clássico (Seedance/Kling/Veo/Sora); hollywood intocado.
    const cenasSemDescricaoDoModelo = new Set<number>() // índices 0-based cujo plano veio do fallback: o supervisor fala×imagem não pode devolvê-los à criatura/CTA literal
    if (verbatim && !planoDeBrollAplicado && !hollywoodPath) { // KINEO-TRILHA-15S — era: planScenes.length === 0 (com plano fora de posição, o descritor era pulado)
      let cobertura: DescriptionCoverage = { descriptions: scenes.map(() => null), lotes: 0, repedidas: [], recuperadas: [], erros: [] }
      try {
        cobertura = await describeScenesCovered(scenes.length, async (numeros) => await generateCinematicDescriptions(numeros.map((n) => scenes[n]), prompt, classicVisualPolicy, numeros.length === scenes.length ? undefined : { numeros: numeros.map((n) => n + 1), total: scenes.length })) // ≤ 12 cenas: sem `lote` — mensagens byte-idênticas às de hoje
      } catch (e) {
        console.warn('[cinematic] #441 description generation skipped:', e instanceof Error ? e.message : String(e))
      }
      const completas = completeSceneDescriptions({
        descriptions: cobertura.descriptions.map((d, i) => d ?? scenes[i].aiPrompt ?? null), // prosa já existente (planner do zero-scenes) vale como descrição
        scenes: scenes.map((s) => ({ voiceover: s.voiceover, hint: s.stockSearchQuery || s.description })),
        topic: prompt,
      })
      scenes = scenes.map((s, i) => ({ ...s, aiPrompt: completas.descriptions[i] }))
      for (const f of completas.fallbacks) cenasSemDescricaoDoModelo.add(f.index)
      const got = cobertura.descriptions.filter(Boolean).length
      console.log(`[cinematic] #441 cinematic descriptions: ${got}/${scenes.length} scenes (${cobertura.lotes} lote(s)${cobertura.repedidas.length ? `; re-pedidas ${cobertura.repedidas.map((i) => i + 1).join(',')} → ${cobertura.recuperadas.length} recuperada(s)` : ''}${cobertura.erros.length ? `; erros: ${cobertura.erros.join(' | ')}` : ''})`)
      if (completas.fallbacks.length) console.warn(`[cinematic] KLING25-DESCRICOES: ${completas.fallbacks.length} cena(s) sem descrição do modelo — prompt visual nasceu do sujeito, nunca da fala: ${completas.fallbacks.map((f) => `cena ${f.index + 1} (${f.source})`).join(', ')}`)
    }

    // #370 — Submit strategy is per-engine (see submitAllScenes below):
    // Seedance/Veo submit with BOUNDED CONCURRENCY (pool of 3) since they have
    // no shared-alias throttle; Kling stays SERIAL with a 450ms stagger because
    // its alias throttles per user (firing 5-6 kling submits at once tripped a
    // burst/rate limit that 4xx'd exactly one clip — the old "submitted 4/5"
    // repeated-clip bug). KINEO-RETRY-2026-07-24 — EVERY scene now gets ONE real
    // retry (submitScene): an EXPLICIT non-ambiguous reject is re-POSTed once
    // after an ~800ms backoff before the scene is dropped to null. Ambiguous
    // rejects are NEVER retried (the job may already exist) — the scene stays
    // null and its claim stays pending, preserving the no-double-charge contract.
    // Push #402 — engine is the user's explicit choice (Kling already gated to
    // Studio above). If Kling fails entirely, fall back to Seedance AND drop the
    // charge to the Seedance price so the user is never billed 50 cr for a
    // Seedance video. Single model per generation keeps the status poll simple.
    const usedModel = wantsKling ? KLING_MODEL : wantsVeo ? VEO_MODEL : wantsSora ? SORA_MODEL : SEEDANCE_MODEL

    // KINEO-SEEDANCE-720-ALL-2026-07-06 — Seedance runs 720p on EVERY plan
    // (~$0.26/clip). 1080p (~$0.62/clip) blew the Studio margin (10 videos =
    // $43.40 cost > $37.90) so it's retired for Seedance — 1080p now lives only
    // in Kling, the premium engine. hd stays false; Kling sets its own params.
    const hd = false

    // KINEO-SEED-2026-07-24 — ONE deterministic seed for this whole generation,
    // shared by every classic scene (Seedance/Kling/Veo) so the clips are drawn
    // from the same latent neighborhood and look connected instead of like
    // unrelated shots. Derived from billingReference (stable per user+generation)
    // so retrying the SAME generationId reuses the SAME seed — no re-dicing.
    const generationSeed = deterministicSeed(billingReference)

    // KINEO-ERA-LOCK-2026-07-09 — era detected ONCE from the full narration +
    // topic, then appended to EVERY scene prompt below (code-enforced; survives
    // any GPT slip in the per-scene visual prompts).
    // KINEO-VIGIA-ERA-2026-09-11 — a era vem SÓ das palavras da história
    // (tema + fala), nunca da camada visual escrita pelo GPT. Render c636e7a0
    // (Seedance, 11/09 19:33 UTC, conto de terror em PT-BR com telefone que
    // recebe MENSAGEM): o descritor inventou "1910 New England farmhouse" numa
    // cena, o `1910` casou com ERA_YEAR_RE e as 7 cenas subiram com "period
    // piece set strictly in the year 1910, no modern objects" — para uma
    // história de hoje. O deslize do GPT que a trava devia sobreviver era
    // justamente o que a estava disparando.
    const eraSuffix = eraLockSuffix(
      `${prompt} ${scenes.map((s) => s.voiceover ?? '').join(' ')}`,
    )
    if (eraSuffix) console.log('[cinematic] era-lock active for this render')
    if (styleAnchor.look !== 'photoreal') console.log(`[cinematic] style-lock: ${styleAnchor.look}`)
    if (storyMode) console.log(`[cinematic] story-mode: look=${styleAnchor.look} character=${storyCharacter ?? '-'}`)

    // ── KINEO-HOLLYWOOD-2026-07-09 — HOLLYWOOD MODE 2.0 ─────────────────────
    // Dedicated path: GPT plans dialogue/cinematic/support scenes with ONE
    // fictional character + ONE environment + ONE styleSheet (KINEO-HOLLYWOOD-22),
    // each scene is submitted to ITS engine (Kling3 dialogue+support / Veo3.1
    // cinematic — Seedance out since 22) with NATIVE AUDIO ON, and the
    // response carries the per-scene metadata compose needs (engines,
    // narrations, seconds). buildFacelessCinematicPrompt / PERSON_NOUN_RE are
    // intentionally NOT applied — fictional people are the point here. The
    // era-lock suffix IS kept (period accuracy still matters).
    if (hollywoodPath) {
      // KINEO-VERBATIM-SEM-MARCADOR-2026-08-24 — no verbatim sem marcadores,
      // parsedScript.narration vem vazio (não há segmentos para extrair); o
      // roteiro é o PROMPT INTEIRO. Sem este fallback, o verbatim recém-ligado
      // cairia no join dos voiceovers do GPT — o exato texto que o contrato
      // proíbe de virar trilho.
      const hollywoodVoiceover = verbatim
        ? (parsedScript.narration && parsedScript.narration.trim().length > 0
            ? parsedScript.narration
            : prompt.trim())
        : scenes.map((s) => s.voiceover).filter(Boolean).join(' ')

      // KINEO-HOLLYWOOD-HOST-2026-07-13 — language/vertical hoisted (the host
      // voice resolution below needs both; the same `vertical` reaches
      // /api/compose from the client, so both routes pin the same persona).
      const hollywoodLanguage: HollywoodLanguage = isHollywoodLanguage(narrationLanguage.language) ? narrationLanguage.language : 'en' // KINEO-IDIOMA-DO-TEXTO · KINEO-IDIOMAS-15: o portão lá em cima já recusou o resto
      const hollywoodVertical =
        typeof body.vertical === 'string' && body.vertical.trim() ? body.vertical.trim().toLowerCase() : undefined

      // ── KINEO-SALVAGE-2026-08-17 — RETOMADA DE RENDER ────────────────────
      // Madrugada de 17/08: um render morreu com 4/6 cenas PRONTAS e pagas no
      // fal (~$8) e o Retry recomeçava do zero — replanejava, re-pagava e
      // re-esperava as 4 cenas que JÁ EXISTIAM. Agora todo submit Hollywood
      // grava plano+ids em hollywood_resume (chave: user+fingerprint do
      // pedido); um novo pedido IGUAL dentro de 2h reaproveita as cenas
      // completas/na fila e re-submete só as falhadas — planner e âncoras
      // nem rodam. Fail-open total: qualquer erro aqui cai no caminho normal.
      const salvageDb = (() => {
        try {
          const url = process.env.NEXT_PUBLIC_SUPABASE_URL
          const key = process.env.SUPABASE_SERVICE_ROLE_KEY
          if (!url || !key) return null
          return createAdminClient(url, key, { auth: { persistSession: false } })
        } catch { return null }
      })()
      const salvageFp = createHash('md5')
        .update(`${user.id}|hollywood|${Math.round(duration || 60)}|${prompt.trim().toLowerCase()}`)
        .digest('hex')
      // ═══ KINEO-SALVAGE-DRYRUN-2026-08-25 — DRY-RUN NUNCA ENTRA NO SALVAGE ═══
      // O caso de 12:56Z: dois dry-runs do MESMO roteiro casaram o fingerprint
      // do render 422 de 12:41, o salvage devolveu as cenas MORTAS antes do
      // gate de dry-run rodar, e cada chamada settlou + debitou 150 (300 no
      // total, estornados à mão via grant-credits). Dry-run é bancada de
      // estudo: SEMPRE plano fresco, NUNCA toca submissão guardada, NUNCA
      // despacha — por isso ele pula o salvage inteiro.
