          faceless: facelessRequested,
          idea: prompt,
          aspect: aspectRequested, // KINEO-MULTIFORMATO-2026-09-02
          characterHint: fichaDoPedidoTexto, // KINEO-FICHA-DO-PEDIDO-2026-09-15
          voiceoverScript: hollywoodVoiceover || undefined,
