      // MOTORMAX — entao esticar funciona; dialogo nunca estica: a fala tem o
      // tamanho que tem).
      {
        const target = hollywoodTarget // KINEO-TIKTOK-61 — overshoot pro plano
        const planTotal = (pl: typeof plan) => pl.scenes.reduce((acc, sc) => acc + (sc.seconds || 0), 0)
        let total = planTotal(plan)
        if (total < Math.round(target * 0.85)) {
          console.warn(`[cinematic] hollywood plan too short: ${total}s of ${target}s target — replanning once`)
          try {
            const replanned = await planHollywoodScenes({
          faceless: facelessRequested,
              idea: prompt,
              characterHint: fichaDoPedidoTexto, // KINEO-FICHA-DO-PEDIDO-2026-09-15 (também nos replans)
              aspect: aspectRequested, // KINEO-MULTIFORMATO-2026-09-02
              voiceoverScript: hollywoodVoiceover || undefined,
              scenes: scenes.map((sc) => ({ voiceover: sc.voiceover, description: sc.aiPrompt || sc.description })),
              durationSeconds: hollywoodTarget,
              language: hollywoodLanguage,
              shortRetryFeedback: `it totaled only ${total} seconds against a ${target}-second target. Return a plan whose scene seconds SUM to ${target - 5}-${target + 2}. Add scenes or lengthen the non-dialogue ones.`,
            })
            if (planTotal(replanned) > total) plan = replanned
            total = planTotal(plan)
          } catch (e) {
            console.warn('[cinematic] hollywood replan failed (keeping first plan):', e instanceof Error ? e.message : String(e))
          }
        }
        // Estica b-roll ate o alvo — MAS SO ATE ONDE A FALA ALCANCA.
        // KINEO-DURATIONFIX-B-2026-08-17 — era 90%; plano de 54 virava video
        // de 46 (cenas de fala usam o audio REAL, sempre menor).
        // KINEO-QUEUE-LATENCY-2026-08-17 — teto de apoio 15→12s (clipes de
        // 14-15s entupiram a fila do Kling na madrugada).
        // KINEO-NARRATION-FIT-2026-08-17 — feedback do fundador no render da
        // manha: "faltou narracao no meio, sem brilho". Raiz: o esticador
        // alongava o CLIPE mas nao a FALA — voiceover de 8s dentro de cena de
        // 12s = 2-4s de silencio morto POR CENA. Agora o teto de cada cena e
        // o MENOR entre 12s e o que a narracao dela sustenta (~2.3 pal/s +1s
        // de respiro). Duracao que faltar vem de MAIS CENAS (replan abaixo),
        // nunca de cena oca.
        const wordsOf = (sc: { voiceover?: string | null }) =>
          (sc.voiceover ?? '').trim().split(/\s+/).filter(Boolean).length
        const capFor = (sc: { type: string; voiceover?: string | null }) =>
          sc.type === 'cinematic'
            ? 8
            : Math.min(SCENE_CAP, Math.max(5, Math.round(wordsOf(sc) / 2.3) + 1)) // KINEO-OMNI-TETO10
        let guard = 60
        while (total < target && guard-- > 0) {
          const stretchable = plan.scenes.filter((sc) => sc.type !== 'dialogue' && (sc.seconds || 0) < capFor(sc))
          if (stretchable.length === 0) break
          for (const sc of stretchable) {
            if (total >= target) break
            sc.seconds = (sc.seconds || 0) + 1
            total += 1
          }
        }
        // Esticador esgotou (toda fala no limite) e ainda falta >5s? UMA
        // replaneja extra pedindo MAIS CENAS com fala dimensionada — e o
        // conteudo da script que estava sendo DROPADO ("a historia ficou
        // curta") volta pro filme.
        if (total < target - 5) {
          console.warn(`[cinematic] hollywood plan ${total}s apos esticar ate o limite da fala — replan por MAIS CENAS`)
          try {
            const replanned = await planHollywoodScenes({
          faceless: facelessRequested,
              idea: prompt,
              characterHint: fichaDoPedidoTexto, // KINEO-FICHA-DO-PEDIDO-2026-09-15 (também nos replans)
              aspect: aspectRequested, // KINEO-MULTIFORMATO-2026-09-02
              voiceoverScript: hollywoodVoiceover || undefined,
              scenes: scenes.map((sc) => ({ voiceover: sc.voiceover, description: sc.aiPrompt || sc.description })),
              durationSeconds: hollywoodTarget,
              language: hollywoodLanguage,
              shortRetryFeedback: `it covered only ${total} seconds of spoken content against a ${target}-second target. Return ${Math.min(8, plan.scenes.length + 1)}-8 scenes summing ${target - 5}-${target + 2} seconds, and size EVERY voiceover to its scene at ~2.3 words per second (a 10s scene needs 20-24 words, a 12s scene 26-30) — use MORE of the source script's facts; do not drop story beats.`,
            })
            const replannedTotal = replanned.scenes.reduce((acc, sc) => acc + (sc.seconds || 0), 0)
            if (replannedTotal > total) {
              plan = replanned
              total = replannedTotal
            }
          } catch (e) {
            console.warn('[cinematic] replan por mais cenas falhou (mantendo plano):', e instanceof Error ? e.message : String(e))
          }
        }
        console.log(`[cinematic] hollywood plan duration: ${total}s of ${target}s target (${plan.scenes.length} scenes)`)
      }

      // ═══ KINEO-CONTRATO-2026-08-18 — Cláusulas 1+2 (docs/CONTRATO-HOLLYWOOD.md)
      // Render ef2d09bf provou: o planner condensou 160 palavras em 52 e
      // submeteu 51s de 68s. C1: com script verbatim, o TEXTO FALADO do filme
      // é o roteiro do usuário, redistribuído cena a cena EM CÓDIGO — o GPT
      // dirige a câmera, nunca mais escreve/condensa/inventa fala. O relógio
      // vira o roteiro (~2.3 palavras/s), então duração fecha por aritmética.
      let verbatimOverflowWords = 0 // KINEO-FALA-MAIOR-QUE-A-CENA — sobra que não coube em cena nenhuma
      if (verbatim && hollywoodVoiceover && hollywoodVoiceover.trim().length > 0) {
        const wordsIn = (t: string) => t.trim().split(/\s+/).filter(Boolean).length
        const totalWords = wordsIn(hollywoodVoiceover)
        const sentencesRaw =
          hollywoodVoiceover
            .replace(/\s+/g, ' ')
            .match(/[^.!?…]+[.!?…]+["”']?|[^.!?…]+$/g)
            ?.map((s) => s.trim())
            .filter(Boolean) ?? []
        // ═══ KINEO-FRASE-MAIOR-QUE-A-CENA-2026-09-14 (auditoria, item 1) ═══════
        // Uma frase de 32 palavras entrava INTEIRA numa cena de 12 s (13,9 s de
        // fala) sem contar como sobra: o dry-run avisava, o caminho pago ia à fal
        // e o compose recusava depois do gasto. Frase acima do teto da cena é
        // quebrada na vírgula/ponto-e-vírgula mais perto do meio — as palavras
        // do autor e a ordem ficam intactas; só a respiração muda de lugar.
        // ═══ MIRROR: splitLongSentence ═══
        const capSentenceWords = plan.scenes.some((sc) => sc.type === 'cinematic') ? 20 : Math.floor((SCENE_CAP + 1) * 2.3) - 1
        const splitLongSentence = (s: string): string[] => {
          if (wordsIn(s) <= capSentenceWords) return [s]
          const toks = s.split(' ')
          const mid = toks.length / 2
          let best = -1
          for (let i = 3; i < toks.length - 3; i++) {
            if (/[,;:—–]$/.test(toks[i]) && (best < 0 || Math.abs(i - mid) < Math.abs(best - mid))) best = i
          }
          const cut = best >= 0 ? best + 1 : Math.floor(mid)
          return [...splitLongSentence(toks.slice(0, cut).join(' ')), ...splitLongSentence(toks.slice(cut).join(' '))]
        }
        // ═══ END MIRROR ═══
        const sentences = sentencesRaw.flatMap(splitLongSentence)
        // [TRAVA 8.2 — vai do fundador 29/09 'vai pra todas as 4'] KINEO-DURACOES-CURTAS-2026-09-29 (entrega 3) — o C1 só redistribuía roteiro de
        // [KINEO-DURACOES-CURTAS-2026-09-29] 40+ palavras em 3+ frases: um roteiro pronto de 15 s (33-42 palavras) caía FORA do contrato e o GPT escreveria a fala.
        // [KINEO-DURACOES-CURTAS-2026-09-29] Nos alvos curtos da estrada (15/30 s) o C1 vale a partir de 12 palavras e 1 frase (o teto-rede divide a frase longa).
        const c1Curto = duration < 35 && totalWords >= 12 && sentences.length >= 1 // KINEO-DURACOES-CURTAS-2026-09-29
        if ((totalWords >= 40 && sentences.length >= 3) || c1Curto) { // KINEO-DURACOES-CURTAS-2026-09-29: + c1Curto
          type PlanScene = (typeof plan.scenes)[number]
          // KINEO-CENA-MUDA-2026-08-22 — índices das cenas que ficaram SEM
          // texto porque o roteiro acabou antes. Elas são PODADAS logo abaixo,
          // depois do laço: remover no meio da iteração embaralharia os
          // índices e o `plan.scenes[i]` passaria a apontar para outra cena.
          const cenasSemFala = new Set<number>()
          const capWords = (sc: PlanScene) =>
            sc.type === 'dialogue' ? (DIALOGUE_CAP >= 15 ? 32 : 22) : sc.type === 'cinematic' ? 16 : (SCENE_CAP >= 12 ? 26 : 20) // KINEO-CONTRATO-FIT-2026-08-18 + KINEO-OMNI-TETO10: fala cabe SEMPRE no teto do clipe da FAMILIA (26w=11.3s<12s; omni: 22w=9.6s<10s, 20w=8.7s<10s)
          let si = 0
          for (let i = 0; i < plan.scenes.length; i++) {
            const sc = plan.scenes[i]
            // KINEO-ORDEM-DA-HISTORIA-2026-09-14 (auditoria, item 2): a cota é
            // proporcional sobre o que RESTA (palavras e segundos), não sobre o
            // total — assim a última cena recebe o fim da história e a sobra
            // deixa de existir por arredondamento.
            const restantesW = sentences.slice(si).reduce((a, s) => a + wordsIn(s), 0)
            const restantesS = plan.scenes.slice(i).reduce((a, s) => a + (s.seconds || 5), 0) || 1
            const share = Math.max(6, Math.round(restantesW * ((sc.seconds || 5) / restantesS)))
            const chunk: string[] = []
            let w = 0
            while (si < sentences.length) {
              const nw = wordsIn(sentences[si])
              // KINEO-SILENCIO-NA-CENA-2026-09-11 — frase curta ("I didn't.") nunca
              // abre cena própria: cabe no bloco atual mesmo passando da cota.
              // Era a origem dos 4 s para 2 palavras no canário do faroleiro.
              if (chunk.length > 0 && (w + nw > capWords(sc) || (w >= share && nw >= 5))) break
              chunk.push(sentences[si])
              w += nw
              si++
            }
            const text = chunk.join(' ').trim()
            // ═══ KINEO-CENA-MUDA-2026-08-22 ═══════════════════════════════
            // ESTA LINHA ERA `if (!text) continue` E É A ORIGEM DO "APAGÃO".
            //
            // Quando o roteiro acaba antes das cenas (`si` chegou ao fim das
            // frases), o `continue` PULAVA a cena — e a cena continuava no
            // plano, com a duração que o GPT pediu e com o voiceover que o
            // GPT tinha inventado, ou com nenhum. Nos dois casos o resultado
            // é o mesmo na tela: imagem rodando sem voz.
            //
            // Medido hoje no render que o fundador reprovou (Solopreneur v2,
            // Kling 3, 70s, 402 caracteres de roteiro = 73 palavras):
            //   silêncio real >1s: 0,2→2,8s · 9,9→12,3s · 60,1→63,6s ·
            //   67,2→70,0s ≈ 11s de buracos, e ~28s de déficit total de fala.
            //   Luminância nunca abaixo de 44 — NÃO havia apagão de imagem,
            //   nunca houve. O nome "apagão" atrasou o diagnóstico em duas
            //   rodadas, inclusive a minha de 20/08, que consertou o rabo mudo
            //   do FINAL (KINEO-TAIL) e não tocou no buraco do MEIO.
            //
            // E o defeito é PIOR do que só silêncio: uma cena pulada aqui
            // mantém o `voiceover` que o GPT escreveu, o que fura o Contrato
            // C1 (o GPT nunca escreve fala) sem que ninguém perceba — a
            // narração deixa de ser a do usuário exatamente nas cenas em que
            // o roteiro dele acabou.
            //
            // O CONSERTO: cena sem texto é MARCADA para poda, não pulada.
            // Filme mais curto e íntegro vale mais que filme no tamanho
            // pedido com um terço de imagem muda — e a poda acontece abaixo,
            // ANTES do C2 medir a duração, para que o C2 trabalhe sobre o
            // plano real em vez de contar segundos que não têm fala.
            if (!text) {
              cenasSemFala.add(i)
              continue
            }
            if (sc.type === 'dialogue') {
              const spoken = text.replace(/"/g, "'")
              sc.dialogueLine = spoken
              sc.prompt = /"[^"]{6,}"/.test(sc.prompt)
                ? sc.prompt.replace(/"[^"]{6,}"/, `"${spoken}"`)
                : `${sc.prompt} The person looks straight into the lens and says: "${spoken}"`
              sc.voiceover = undefined
              sc.needsNarration = false
              sc.seconds = Math.max(3, Math.min(DIALOGUE_CAP, Math.round(w / 2.3) + 1)) // KINEO-OMNI-TETO10
            } else {
              sc.voiceover = text
              sc.needsNarration = true
              const cap = sc.type === 'cinematic' ? 8 : SCENE_CAP // Veo entrega no max 8s; KINEO-OMNI-TETO10
              sc.seconds = Math.max(4, Math.min(cap, Math.round(w / 2.3) + 1))
            }
          }
          // ═══ KINEO-CENA-MUDA-2026-08-22 — A PODA ═══════════════════════
          // Cenas que não receberam uma única palavra do roteiro saem do
          // plano. Só rodam se AINDA houver frases sobrando (`si`), porque
          // nesse caso o buraco foi de distribuição, não de falta de texto, e
          // o bloco de sobra logo abaixo vai preenchê-las.
          //
          // POR QUE PODAR EM VEZ DE INVENTAR FALA: inventar quebra o Contrato
          // C1 (a narração é do usuário, sempre). Deixar mudo é o defeito que
          // o fundador acabou de reprovar. Entre um filme mais CURTO e um
          // filme do tamanho pedido com um terço de imagem sem voz, o curto
          // ganha — e é o único dos três caminhos que não mente para ninguém.
          //
          // ⚠️ ISTO PODE DERRUBAR O FILME ABAIXO DO PISO DE 60s do TikTok
          // Creator Rewards, e isso é ACEITO de propósito: um vídeo de 40s
          // inteiro vale mais que um de 65s com 25s mudos, e o C2 logo abaixo
          // ainda tenta recompor a duração com cenas que TENHAM fala. A defesa
          // de verdade contra o filme curto não é aqui — é impedir que um
          // roteiro curto demais entre no pipeline (ver lib/narrationFit.ts).
          if (cenasSemFala.size > 0 && si >= sentences.length) {
            const antes = plan.scenes.length
            const segundosPodados = [...cenasSemFala]
              .reduce((a, i) => a + (plan.scenes[i]?.seconds || 0), 0)
            plan.scenes = plan.scenes.filter((_, i) => !cenasSemFala.has(i))
            plan.scenes.forEach((sc, i) => { sc.index = i + 1 })
            console.warn(
              `[contrato] C1 PODA: ${antes - plan.scenes.length} cena(s) sem fala removida(s) ` +
              `(${segundosPodados}s que sairiam MUDOS). Roteiro de ${totalWords} palavras ` +
              `≈ ${Math.round(totalWords / 2.3)}s de voz para um alvo de ${hollywoodTarget}s.`,
            )
          }

          // Sobra de roteiro (história maior que o plano): vira cenas de apoio
          // novas — o conteúdo do fundador NUNCA é dropado.
          while (si < sentences.length && plan.scenes.length < MAX_VERBATIM_SCENES) {
            const chunk: string[] = []
            let w = 0
            while (si < sentences.length && (chunk.length === 0 || w + wordsIn(sentences[si]) <= 26)) {
              chunk.push(sentences[si])
              w += wordsIn(sentences[si])
              si++
            }
            plan.scenes.push({
              index: plan.scenes.length + 1,
              type: 'support',
              beat: 'PAYOFF',
              seconds: Math.max(4, Math.min(SCENE_CAP, Math.round(w / 2.3) + 1)), // KINEO-OMNI-TETO10
              prompt: `slow cinematic insert continuing the story, ${plan.environmentSheet}, level horizon, stable slow dolly detail shot, ${plan.styleSheet}`,
              voiceover: chunk.join(' '),
              needsNarration: true,
              caption: '',
            } as PlanScene)
          }
          // KINEO-FALA-MAIOR-QUE-A-CENA — a sobra entra frase a frase nas cenas
          // narradas que ainda têm espaço (teto de palavras da cena = teto de
          // segundos × 2,3). O que não couber em lugar nenhum NÃO é colado:
          // vira recusa honesta antes do POST pago (verbatimOverflowWords).
          if (si < sentences.length) {
            // KINEO-ORDEM-DA-HISTORIA-2026-09-14 (auditoria, item 2): a sobra era
            // encaixada de TRÁS para frente (14 frases saíam 1…11, 14, 12, 13).
            // Agora só a ÚLTIMA cena narrada recebe o resto — é o fim da história.
            // O que não couber nela vira recusa honesta, nunca reordenação.
            const ultima = [...plan.scenes].reverse().find((sc) => sc.type !== 'dialogue')
            if (ultima) {
              const capSecs = ultima.type === 'cinematic' ? 8 : SCENE_CAP
              const capW = Math.floor(capSecs * 2.3)
              while (si < sentences.length && wordsIn(ultima.voiceover ?? '') + wordsIn(sentences[si]) <= capW) {
                ultima.voiceover = `${ultima.voiceover ?? ''} ${sentences[si]}`.trim()
                si++
              }
              ultima.seconds = Math.max(4, Math.min(capSecs, Math.round(wordsIn(ultima.voiceover ?? '') / 2.3) + 1))
            }
            if (si < sentences.length) {
              verbatimOverflowWords = sentences.slice(si).reduce((a, s) => a + wordsIn(s), 0)
              console.warn(`[contrato] C1 SOBRA SEM CENA: ${verbatimOverflowWords} palavras não cabem em ${MAX_VERBATIM_SCENES} cenas de ${SCENE_CAP}s — recusa antes do POST`)
            }
          }
          // ═══ KINEO-APARA-RESPIRO-2026-09-13 — a régua de silêncio (aprovada em
          // 11/09: ≤1,5 s por cena, ≤8 s no total) e o "+1 s de respiro" que
          // cada cena ganha acima discordam a partir de ~9 cenas: 10 cenas × ~0,9 s
          // = 9 s e o roteiro do fundador (80 s de fala, 10 cenas) reprovava por
          // 1 s. O planejador passa a aparar o respiro das cenas mais folgadas
          // até caber na régua — nunca abaixo de 4 s, nunca tocando na fala.
          // ═══ KINEO-MESMA-REGUA-DO-ESCRITOR-2026-09-25 — o C1 mede no passo da voz que VAI falar ═══
          // Render H3 7127d8b4 (fundador, 25/09 17:18Z, furacão Polo, roteiro pronto de 191 palavras, 60 s): 12 clipes
          // aceitos e PAGOS ao fal (~US$ 5,70) e o compose recusou (scene_speech_exceeds_footage). A cena 7 tinha 22
          // palavras em 10 s: nasceu com 11 s (round(22/2,3)+1); a apara abaixo mediu 1,43 s de folga A 2,3 PAL/S e tirou
          // 1 s; a voz pinada (luxury-narrator, 0,9) fala a 2,07 pal/s → 10,6 s de fala + 0,4 s de respiro = 11,0 s num
          // clipe de 10 s (×1,13), acima do que o FALA-CABE acelera (×1,10). Quatro réguas: 2,3 fixo AQUI, ritmoVoz nas
          // aparas seguintes, a proporcional no portão, e a voz real na montagem — a primeira era a mais frouxa e decidia
          // por último. Agora o C1 mede com a MESMA conta de `ritmoVoz` (espelho abaixo; o guardião compara os dois); a
          // variação da voz real (±5 %) fica para o FALA-CABE (×1,10) e para a travessia do corte, na montagem.
          // A parede nasce no escritor, nunca depois de pagar.
          // ═══ MIRROR: ritmoDaVoz ═══
          const ritmoC1 = (() => {
            try {
              const falas = sceneNarrationsForPlan(plan.scenes).filter(Boolean).join(' ')
              const voz = resolveHollywoodVoice(falas || prompt, hollywoodLanguage, hollywoodVertical, plan.characterSheet)
              return Math.round(2.3 * Math.max(0.85, Math.min(1.1, voz.defaultSpeed)) * 100) / 100
            } catch { return 2.3 }
          })()
          // ═══ END MIRROR: ritmoDaVoz ═══
          {
            const silencio = (sc: PlanScene) => (sc.seconds || 0) - wordsIn((sc.type === 'dialogue' ? sc.dialogueLine : sc.voiceover) ?? '') / ritmoC1
            let total = plan.scenes.reduce((a, sc) => a + Math.max(0, silencio(sc)), 0)
            let guard = 40
            while (total > 7.5 && guard-- > 0) {
              const alvo = plan.scenes.filter((sc) => (sc.seconds || 0) > 4 && silencio(sc) > 1).sort((a, b) => silencio(b) - silencio(a))[0]
              if (!alvo) break
              alvo.seconds = (alvo.seconds || 0) - 1
              total = plan.scenes.reduce((a, sc) => a + Math.max(0, silencio(sc)), 0)
            }
          }
          // KINEO-FRASE-MAIOR-QUE-A-CENA-2026-09-14 (auditoria, item 1): a régua
          // "fala > segundos + 1" só existia no dry-run. Aqui, no caminho pago:
          // primeiro a cena cresce até o teto da família; o que ainda estourar
          // entra na recusa honesta abaixo (422 sem cobrança), antes de qualquer POST.
          for (const sc of plan.scenes) {
            const palavras = wordsIn((sc.type === 'dialogue' ? sc.dialogueLine : sc.voiceover) ?? '')
            const fala = palavras / 2.3
            const teto = sc.type === 'dialogue' ? DIALOGUE_CAP : sc.type === 'cinematic' ? 8 : SCENE_CAP
            // KINEO-MESMA-REGUA-DO-ESCRITOR-2026-09-25: a cena guarda a fala inteira NO RITMO DA VOZ (a conta a 2,3 abaixo
            // continua valendo para a sobra). Acima do teto da família o teto-rede divide na frase — nunca recusa aqui.
            const precisaNoRitmo = Math.ceil(palavras / ritmoC1)
            if (palavras > 0 && palavras / ritmoC1 > (sc.seconds || 0)) sc.seconds = Math.max(sc.seconds || 0, Math.min(teto, precisaNoRitmo))
            if (fala > (sc.seconds || 0) + 1) sc.seconds = Math.max(sc.seconds || 0, Math.min(teto, Math.ceil(fala)))
            if (fala > (sc.seconds || 0) + 1) verbatimOverflowWords += Math.ceil((fala - (sc.seconds || 0) - 1) * 2.3)
          }
          console.log(
            `[contrato] C1 verbatim: ${totalWords} palavras do roteiro → ${plan.scenes.length} cenas, ${plan.scenes.reduce((a, sc) => a + (sc.seconds || 0), 0)}s falados (zero texto inventado)`,
          )
        }
      }

      let duracaoReconciliada: { reconciliado: boolean; aparado_s: number; excedente_s: number; base: 'estimate' } | null = null
      // ═══ KINEO-REGUA-PROPORCIONAL-2026-09-23 — o teto de SILÊNCIO TOTAL acompanha o tamanho do filme ═══
      // A régua (1,5 s por cena, 8 s no total — KINEO-SILENCIO-NA-CENA) nasceu para filmes de 60 s com ~8 cenas. Com
      // segundos INTEIROS por cena, cada cena carrega ~0,5 s de respiro inevitável: um roteiro pronto de 220 palavras
      // vira ~110 s em ~16 cenas e soma 9-10 s sem NENHUMA cena muda — e era recusado (render H3 do fundador, 23/09;
      // fuzz de 500 roteiros sobre esta fatia: 315/500 com 8 s fixo, 500/500 proporcional, pior cena 1,4 s). O limite
      // POR CENA (1,5 s), que é o que pega silêncio de verdade, não muda; o total vira 8 s a cada 60 s de filme (nunca
      // menos de 8). lib/cinematic fica intocada (trava 8.2): a proporção é aplicada aqui, sobre o relatório de lá.
      const reguaDoFilme = (scenes: Parameters<typeof planSilenceReport>[0], wps: number) => {
        const rep = planSilenceReport(scenes, wps)
        const filme = scenes.reduce((a, sc) => a + ((sc as { seconds?: number }).seconds || 0), 0)
        const totalMax = Math.round(SILENCE_TOTAL_MAX_SECONDS * Math.max(1, filme / 60) * 10) / 10
        const ok = rep.worst <= SILENCE_SCENE_MAX_SECONDS && rep.total <= totalMax
        return { ...rep, ok, wordsToAdd: ok ? 0 : rep.wordsToAdd, totalMax }
      }
      // ═══ KINEO-RITMO-DA-VOZ-2026-09-15 — a régua anda no passo da voz que VAI falar ═══
      // Render H3 7bb62a29 (fundador, 15/09): o plano contava 2,3 pal/s, a apara deixava
      // 0,25 s de folga, e a voz pinada (character:male:elderly, onyx 0,94) falou mais
      // devagar → em 3 cenas a fala medida + 0,6 s passou do clipe e o compose recusou
      // (scene_speech_exceeds_footage) DEPOIS de pagar 7 clipes (~$4,36; 45 cr estornados).
      // Aqui a MESMA resolução que o compose usa (resolveHollywoodVoice, ficha incluída)
      // decide o ritmo: 2,3 × velocidade da persona (0,94 → 2,16 pal/s). E toda conta de
      // "cabe" é feita nesse ritmo: a cena reescrita ganha round(pal/ritmo)+1 s (folga de
      // 0,5–1,5 s, dentro da régua), e nada fica com menos de 0,3 s (FOLGA_MIN_S). O compose
      // mede a voz real e, se ela estourar o clipe em até 8 %, re-sintetiza a cena na
      // velocidade que cabe (KINEO-FALA-CABE) — nunca mais recusa depois de pagar.
      const ritmoVoz = (() => {
        try {
          const falas = sceneNarrationsForPlan(plan.scenes).filter(Boolean).join(' ')
          const voz = resolveHollywoodVoice(falas || prompt, hollywoodLanguage, hollywoodVertical, plan.characterSheet)
          return Math.round(2.3 * Math.max(0.85, Math.min(1.1, voz.defaultSpeed)) * 100) / 100
        } catch { return 2.3 }
      })()
      const FOLGA_MIN_S = 0.3
      if (ritmoVoz !== 2.3) console.log(`[hollywood] KINEO-RITMO-DA-VOZ: persona mais lenta/rápida que a régua → ${ritmoVoz} pal/s (2,3 × velocidade da voz)`)
      // ═══ KINEO-APARA-NO-RITMO-DA-VOZ-2026-09-16 — verbatim: a apara do respiro do C1 (KINEO-APARA-RESPIRO) mede o silêncio a
      // 2,3 pal/s fixo, mas a régua (ensaio e render) julga em ritmoVoz. Ensaio verbatim do Omni (16/09, 149 palavras, 11 cenas):
      // a apara parou em ≤ 7,5 s e a régua mediu 9,3 s — 0,07 pal/s × 11 cenas. Aqui, com ritmoVoz em mãos, a mesma apara roda
      // de novo: tira 1 s da cena mais folgada enquanto o total passar de 7,5 s ou alguma cena passar de 1,4 s; nunca abaixo
      // de 4 s, nunca tocando na fala. Só em verbatim (em modo IA o enche-silêncio põe palavra, não tira segundo). ═══
      if (verbatim && plan.scenes.length > 0) {
        const mudoDe = (sc: (typeof plan.scenes)[number]) => (sc.seconds || 0) - ((sc.type === 'dialogue' ? sc.dialogueLine : sc.voiceover) ?? '').trim().split(/\s+/).filter(Boolean).length / ritmoVoz
        const totalDe = () => plan.scenes.reduce((a, sc) => a + Math.max(0, mudoDe(sc)), 0)
        const antesTotal = totalDe()
        let guard = 60
        while (guard-- > 0 && (totalDe() > 7.5 || plan.scenes.some((sc) => mudoDe(sc) > 1.4))) {
