          if (!isDialogue && !verbatim) {
            const cabeCauda = Math.max(4, Math.floor((tailSeconds - 0.3) * ritmoVoz))
            const faltam = cabeCauda - wordsArr(tail).length
            if (faltam >= 3) {
              try {
                const [cheia] = await appendNarrationToTargets([{ text: tail, addWords: faltam, maxWords: cabeCauda + 2 }], hollywoodLanguage, prompt.slice(0, 300))
                const w = wordsArr(cheia).length
                if (cheia && cheia !== tail && w > wordsArr(tail).length && w <= cabeCauda + 2 && cheia.startsWith(tail.replace(/[.!?…]$/, ''))) {
                  cauda = cheia
                  tailSeconds = Math.max(4, Math.min(SCENE_CAP, Math.round(w / ritmoVoz) + 1))
                  console.log(`[teto-rede] KINEO-CAUDA-CHEIA: cauda de ${wordsArr(tail).length} palavras cresceu para ${w} (cabe ${cabeCauda} em ${tailSeconds}s)`)
                } else console.warn(`[teto-rede] KINEO-CAUDA-CHEIA: continuação recusada (${wordsArr(tail).length} → ${w}, teto ${cabeCauda} + 2)`)
              } catch (e) { console.warn('[teto-rede] KINEO-CAUDA-CHEIA falhou:', e instanceof Error ? e.message : String(e)) }
            }
          }
          plan.scenes.splice(i + 1, 0, {
            ...sc,
            index: sc.index + 1,
            type: 'support',
            dialogueLine: undefined,
            voiceover: cauda,
            needsNarration: true,
            seconds: tailSeconds,
            prompt: `slow cinematic insert continuing the story, ${plan.environmentSheet ?? ''}, level horizon, stable slow dolly detail shot, ${plan.styleSheet ?? ''}`,
            caption: '',
          })
          console.warn(`[teto-rede] cena ${i + 1} (${sc.type}) dividida: ${fits} palavras ficam, ${wordsArr(cauda).length} viram apoio de ${tailSeconds}s`)
        }
      }

      // ═══ KINEO-H3-VERBATIM-CORTE-2026-09-23 (apara final do verbatim) — a apara no ritmo da voz roda ANTES do teto-rede;
      // as cabeças e caudas que ele cria depois trazem folga nova (plano do fundador: 8,9 s de silêncio somando 0,3–1,2 s
      // por cena). Em verbatim não há enche-silêncio (C1): a mesma apara roda de novo aqui — 1 s da cena mais folgada,
      // nunca abaixo de 4 s, nunca tocando na fala, e NUNCA abaixo da duração pedida. ═══
      if (verbatim && plan.scenes.length > 0) {
        const mudoFinal = (sc: (typeof plan.scenes)[number]) => (sc.seconds || 0) - ((sc.type === 'dialogue' ? sc.dialogueLine : sc.voiceover) ?? '').trim().split(/\s+/).filter(Boolean).length / ritmoVoz
        const silencioFinal = () => plan.scenes.reduce((a, sc) => a + Math.max(0, mudoFinal(sc)), 0)
        const totalFinal = () => plan.scenes.reduce((a, sc) => a + (sc.seconds || 0), 0)
        const antesFinal = silencioFinal()
        // KINEO-H3-FRASE-CURTA-2026-09-23 — o clipe tem piso de 4 s: uma cena que o planejador sorteou com UMA frase curta
        // ("But one man survives." = 4 palavras ≈ 1,8 s de fala) fica com ~2,1 s mudos que nenhuma apara alcança (ensaios
        // de $0 de 23/09: 2 de 4 reprovados por 2,1 s). A frase curta passa para a cena vizinha — anterior, senão a
        // seguinte — quando as duas cabem no teto: mesmas palavras, mesma ordem, um clipe a menos. Nunca diálogo, nunca
        // abaixo da duração pedida.
        {
          const falaDe = (sc: (typeof plan.scenes)[number]) => (sc.voiceover ?? '').trim()
          const nPal = (t: string) => t.split(/\s+/).filter(Boolean).length
          const tetoDe = (sc: (typeof plan.scenes)[number]) => sc.type === 'cinematic' ? 8 : SCENE_CAP
          let guardaJunta = 40
          for (let i = 0; i < plan.scenes.length && guardaJunta-- > 0; i++) {
            const sc = plan.scenes[i]
            if (sc.type === 'dialogue' || !falaDe(sc) || mudoFinal(sc) <= 1.4 || (sc.seconds || 0) > 4) continue
            const tentar = (viz: (typeof plan.scenes)[number] | undefined, antes: boolean): boolean => {
              if (!viz || viz.type === 'dialogue' || !falaDe(viz)) return false
              const junta = antes ? `${falaDe(viz)} ${falaDe(sc)}` : `${falaDe(sc)} ${falaDe(viz)}`
              const teto = tetoDe(viz)
              if (nPal(junta) > Math.floor((teto - FOLGA_MIN_S) * ritmoVoz)) return false
              // a vizinha fica com os segundos da fala juntada E com o que o piso pedido exigir — desde que continue sem
              // silêncio acima de 1,4 s e dentro do teto; senão não junta
              const pisoPede = duration - (totalFinal() - (sc.seconds || 0) - (viz.seconds || 0))
              const novos = Math.max(viz.seconds || 0, Math.ceil(nPal(junta) / ritmoVoz + FOLGA_MIN_S), pisoPede)
              if (novos > teto || novos - nPal(junta) / ritmoVoz > 1.4) return false
              viz.voiceover = junta
              viz.needsNarration = true
              viz.seconds = novos
              plan.scenes.splice(i, 1)
              console.log(`[hollywood] KINEO-H3-FRASE-CURTA: "${junta.slice(0, 40)}…" — frase de ${nPal(falaDe(sc))} palavras juntou-se à cena ${antes ? 'anterior' : 'seguinte'} (${novos}s)`)
              return true
            }
            if (tentar(plan.scenes[i - 1], true) || tentar(plan.scenes[i + 1], false)) { i--; continue }
            // Vizinhas cheias demais para receber a frase curta (ensaios de 23/09: "Follow for the next one." no fim;
            // "being evacuated to safety." cortada no teto de 8 s): a cena curta EMPRESTA frases inteiras da vizinha —
            // a última da anterior vai para o começo dela, ou a primeira da seguinte para o fim. Mesmas palavras, mesma
            // ordem; a vizinha só cede se ficar com fala para ≥ 2,7 s (senão ela é que ficaria muda).
            const frasesDe = (t: string) => t.split(/(?<=[.!?…]["”')\]]?)\s+/).filter(Boolean)
            const emprestar = (viz: (typeof plan.scenes)[number] | undefined, antes: boolean): boolean => {
              if (!viz || viz.type === 'dialogue' || !falaDe(viz)) return false
              const frasesViz = frasesDe(falaDe(viz))
              const minimoViz = Math.ceil(2.7 * ritmoVoz)
              const tetoSc = tetoDe(sc)
              let minhas = falaDe(sc)
              let cedidas = 0
              while (frasesViz.length > 1) {
                const frase = antes ? frasesViz[frasesViz.length - 1] : frasesViz[0]
                const restoViz = (antes ? frasesViz.slice(0, -1) : frasesViz.slice(1)).join(' ')
                const junta = antes ? `${frase} ${minhas}` : `${minhas} ${frase}`
                if (nPal(restoViz) < minimoViz || Math.ceil(nPal(junta) / ritmoVoz + FOLGA_MIN_S) > tetoSc) break
                if (antes) frasesViz.pop(); else frasesViz.shift()
                minhas = junta
                cedidas++
                if (Math.max(4, Math.ceil(nPal(minhas) / ritmoVoz + FOLGA_MIN_S)) - nPal(minhas) / ritmoVoz <= 1.4) break
              }
              if (cedidas === 0) return false
              const segSc = Math.max(4, Math.ceil(nPal(minhas) / ritmoVoz + FOLGA_MIN_S))
              if (segSc - nPal(minhas) / ritmoVoz > 1.4) return false
              const restoFinal = frasesViz.join(' ')
              const segViz = Math.max(4, Math.ceil(nPal(restoFinal) / ritmoVoz + FOLGA_MIN_S))
              // o piso pedido segue intacto: se encolher a vizinha furar a duração, ela mantém os segundos e a apara decide
              const totalDepois = totalFinal() - (sc.seconds || 0) - (viz.seconds || 0) + segSc + Math.min(viz.seconds || 0, segViz)
              sc.voiceover = minhas
              sc.needsNarration = true
              sc.seconds = segSc
              viz.voiceover = restoFinal
              if (totalDepois >= duration) viz.seconds = Math.min(viz.seconds || 0, segViz)
              console.log(`[hollywood] KINEO-H3-FRASE-CURTA: cena curta emprestou ${cedidas} frase(s) da ${antes ? 'anterior' : 'seguinte'} (${nPal(minhas)} palavras em ${segSc}s)`)
              return true
            }
            if (emprestar(plan.scenes[i - 1], true) || emprestar(plan.scenes[i + 1], false)) continue
            // Última saída — a vizinha é UMA frase longa e não tem frase inteira para ceder: cede PALAVRAS do seu fim (ou
            // começo). Mesmas palavras, mesma ordem; o custo é uma pausa no meio da frase, melhor que recusar o filme do
            // autor. Só o necessário para a cena curta sair de ≤ 1,4 s mudos; a vizinha fica com fala para ≥ 2,7 s.
            const emprestarPalavras = (viz: (typeof plan.scenes)[number] | undefined, antes: boolean): boolean => {
              if (!viz || viz.type === 'dialogue' || !falaDe(viz)) return false
              const pv = falaDe(viz).split(/\s+/).filter(Boolean)
              const ps = falaDe(sc).split(/\s+/).filter(Boolean)
              const precisa = Math.ceil(2.6 * ritmoVoz) - ps.length
              if (precisa <= 0 || pv.length - precisa < Math.ceil(2.7 * ritmoVoz)) return false
              const cedidas = antes ? pv.splice(pv.length - precisa, precisa) : pv.splice(0, precisa)
              const minhas = antes ? [...cedidas, ...ps] : [...ps, ...cedidas]
              const segSc = Math.max(4, Math.ceil(minhas.length / ritmoVoz + FOLGA_MIN_S))
              if (segSc > tetoDe(sc)) return false
              const segViz = Math.max(4, Math.ceil(pv.length / ritmoVoz + FOLGA_MIN_S))
              const totalDepois = totalFinal() - (sc.seconds || 0) - (viz.seconds || 0) + segSc + Math.min(viz.seconds || 0, segViz)
              sc.voiceover = minhas.join(' ')
              sc.needsNarration = true
              sc.seconds = segSc
              viz.voiceover = pv.join(' ')
              if (totalDepois >= duration) viz.seconds = Math.min(viz.seconds || 0, segViz)
              console.log(`[hollywood] KINEO-H3-FRASE-CURTA: cena curta emprestou ${precisa} palavra(s) da ${antes ? 'anterior' : 'seguinte'} (${minhas.length} palavras em ${segSc}s)`)
              return true
            }
            if (emprestarPalavras(plan.scenes[i - 1], true) || emprestarPalavras(plan.scenes[i + 1], false)) continue
          }
        }
        let guardaFinal = 60
        while (guardaFinal-- > 0 && totalFinal() - 1 >= duration && (silencioFinal() > 7.5 || plan.scenes.some((sc) => mudoFinal(sc) > 1.4))) {
          const alvo = plan.scenes.filter((sc) => (sc.seconds || 0) > 4 && mudoFinal(sc) > 1.0).sort((a, b) => mudoFinal(b) - mudoFinal(a))[0]
          if (!alvo) break
          alvo.seconds = (alvo.seconds || 0) - 1
        }
        if (Math.abs(antesFinal - silencioFinal()) > 0.05) console.log(`[hollywood] KINEO-H3-VERBATIM-CORTE: apara final ${antesFinal.toFixed(1)}s → ${silencioFinal().toFixed(1)}s (${plan.scenes.length} cenas, ${totalFinal()}s)`)
      }

      // ═══ KINEO-ULTIMA-ENCHIDA-2026-09-15 — a última palavra sobre o silêncio é do código, DEPOIS do teto-rede e do
      // esticão ao piso (fitCinematicPlanFloor). Ensaio do Omni com gpt-4o (deploy cfbe20b1): o enche-silêncio aprovava o
      // plano projetado (3,9 s) e a régua final reprovava (10,5 s) porque o teto-rede dividia cenas e o esticão alongava
      // outras DEPOIS do enchimento. Cada cena que ficou com > 1,0 s mudo ganha uma continuação até caber nos seus
      // segundos ((s − 0,3) × ritmo); recusa do modelo mantém a fala como está. Verbatim nunca passa por aqui (C1).
      // R3 (ensaio 4 do Omni, 16/09): a passada roda ANTES da varredura final de datas/lugares — a continuação trazia
      // "Salar de Uyuni, Bolivia, 10,000 square kilometers" numa história de ficção sem lugar, e nada a limpava depois. ═══
      if (!verbatim && plan.scenes.length > 0) {
        try {
          const wordsN = (t?: string) => (t ?? '').trim().split(/\s+/).filter(Boolean).length
          // R2 (render real ee7d62ec, 15/09): a 1ª rodada deixou a última cena em 1,6 s (a continuação veio longa e foi aparada
          // à primeira oração: 8 → 4 palavras). Duas rodadas: a segunda só pede para o que ainda passa de 1,0 s.
          for (let rodada = 1; rodada <= 2; rodada++) {
          const alvos = plan.scenes
            .filter((sc) => sc.type !== 'dialogue' && typeof sc.voiceover === 'string' && sc.voiceover.trim().length > 0)
            .map((sc) => { const cabe = Math.max(1, Math.floor(((sc.seconds ?? 0) - 0.3) * ritmoVoz)); const w = wordsN(sc.voiceover); return { sc, cabe, w, mudo: (sc.seconds ?? 0) - w / ritmoVoz } })
            .filter((x) => x.mudo > 1.0 && x.cabe - x.w >= 2)
          if (alvos.length === 0) break
          {
            // R4 (render real 31d0f1c2, 16/09): appendNarrationToTargets IGNORA em silêncio pedidos de menos de 3 palavras — os três
            // alvos pediam 2 e "0 cresceram" sem aviso. Pede pelo menos 3 (o teto + 2 dá a sobra) e a 2ª rodada roda mesmo com zero.
            const novas = await appendNarrationToTargets(alvos.map((x) => ({ text: x.sc.voiceover ?? '', addWords: Math.max(3, x.cabe - x.w), maxWords: x.cabe + 2 })), hollywoodLanguage, prompt.slice(0, 300))
            let cresceram = 0
            alvos.forEach((x, k) => {
              const nova = typeof novas[k] === 'string' ? novas[k].trim() : ''
              const wn = wordsN(nova)
              if (nova && nova !== x.sc.voiceover && wn > x.w && wn <= x.cabe + 2 && nova.startsWith((x.sc.voiceover ?? '').trim().replace(/[.!?…]$/, ''))) { x.sc.voiceover = nova; x.sc.needsNarration = true; cresceram++ }
            })
            const depois = reguaDoFilme(plan.scenes, ritmoVoz)
            console.log(`[hollywood] KINEO-ULTIMA-ENCHIDA: ${alvos.length} cena(s) com > 1,0 s mudo depois do teto-rede/esticão → ${cresceram} cresceram → ${depois.total}s no total (pior ${depois.worst}s) ${depois.ok ? 'PASSA' : 'ainda reprova'} (rodada ${rodada})`)
            if (depois.ok) break
          }
          }
        } catch (e) { console.warn('[hollywood] KINEO-ULTIMA-ENCHIDA falhou:', e instanceof Error ? e.message : String(e)) }
      }
      // ═══ KINEO-DATA-INVENTADA-2026-09-15 (varredura final) — o planejador já limpa a fala, mas o enche-silêncio e o
      // acréscimo de palavras REESCREVEM linhas depois (ensaio do S25 no deploy b615127b: "On June 15th, 2023" na cena 1
      // depois do filtro do planejador). A última palavra é do código, depois de toda reescrita. ═══
      {
        // Contexto = só o pedido (em verbatim o pedido É o texto): o brief escrito pela IA trazia "In 2023" e "legitimava" a data.
        const contextoDatas = comVocabularioDoLugar(prompt) // KINEO-MONUMENTO-2026-10-13 — sem lugar real curado = `prompt`, a mesma string
        const tiradas: string[] = []
        const mantidasH: string[] = [] // KINEO-META95-ASSUNTO-1910 — frases que ficariam com buraco: ficam inteiras
        const reescritasH: string[] = [] // KINEO-META95-ASSUNTO-1910 — frases reescritas sem a oração do buraco (inclusive as que o planejador já entregou com buraco)
        for (const sc of plan.scenes) {
          for (const campo of ['voiceover', 'dialogueLine'] as const) {
            const v = sc[campo]
            if (typeof v !== 'string' || !v.trim() || verbatim) continue // KINEO-META95-ASSUNTO-1910 — contrato C1: a fala do roteiro colado ("Use my script as is") nunca é tocada (era: sem o `|| verbatim`; em verbatim o pedido É o texto, mas o guarda agora é explícito)
            const f = filtrarFalaSemBuraco(v, contextoDatas, { repararExistentes: true }) // KINEO-META95-ASSUNTO-1910 — frase a frase, nunca com buraco (era removerDatasInventadas + scrubInventedSetting direto na fala)
            // KINEO-LUGAR-INVENTADO-2026-09-15 — "Bolivia's Salar de Uyuni", "Emily Carter": nome próprio/lugar/época fora do pedido sai
            // da fala com o mesmo filtro que já protege os prompts de imagem do clássico (scrubInventedSetting, puro).
            if (f.mantidas.length) mantidasH.push(...f.mantidas) // KINEO-META95-ASSUNTO-1910
            if (f.reescritas.length) reescritasH.push(...f.reescritas) // KINEO-META95-ASSUNTO-1910
            if (f.texto !== v) { sc[campo] = f.texto; tiradas.push(...f.removidas) } // KINEO-META95-ASSUNTO-1910
          }
        }
        if (tiradas.length) console.log(`[hollywood] KINEO-DATA-INVENTADA (final): ${tiradas.length} data(s)/hora(s) fora do pedido removida(s): ${tiradas.map((t) => JSON.stringify(t)).join(', ')}`)
        if (mantidasH.length || reescritasH.length) console.log(`[hollywood] KINEO-META95-ASSUNTO: fala sem buraco — ${reescritasH.length} frase(s) reescrita(s), ${mantidasH.length} mantida(s) inteira(s): ${[...reescritasH, ...mantidasH].map((t) => JSON.stringify(t.slice(0, 80))).join(', ')}`) // KINEO-META95-ASSUNTO-1910
      }

      // ═══ KINEO-OMNI-ALVO-CRAVADO-2026-08-25 (V6.1, fundador aprovou) ═══
      // O Omni cobra $0.13/s DESPACHADO: overshoot é margem indo embora
      // (80s despachados no 1º render = ~23% de margem; 68s = ~35%). Este
      // passe apara SÓ FOLGA — cena não-dialogue cujos segundos excedem o
      // que a própria fala sustenta (~2.3 pal/s +1 respiro). Verbatim não
      // tem folga (C1 dimensiona tudo pela palavra) → no-op; plano do GPT
      // com gordura → enxuga até alvo+4. Nenhuma palavra é tocada, nunca.
      if (family === 'omni') {
        const wordsOf2 = (t?: string | null) => (t ?? '').trim().split(/\s+/).filter(Boolean).length
        let total2 = plan.scenes.reduce((a, sc) => a + (sc.seconds || 0), 0)
        const ceiling = hollywoodTarget + 4
        let guard2 = 40
        while (total2 > ceiling && guard2-- > 0) {
          const slacky = plan.scenes.filter((sc) => sc.type !== 'dialogue' && (sc.seconds || 0) > Math.max(4, Math.round(wordsOf2(sc.voiceover) / 2.3) + 1))
          if (slacky.length === 0) break
          for (const sc of slacky) {
            if (total2 <= ceiling) break
            sc.seconds = (sc.seconds || 0) - 1
            total2 -= 1
          }
        }
        if (total2 < plan.scenes.reduce((a, sc) => a + (sc.seconds || 0), 0)) { /* unreachable, log below */ }
        console.log(`[cinematic] KINEO-OMNI-ALVO: plano final ${total2}s (teto ${ceiling}s) — folga aparada sem tocar palavra`)
      }

      // `dry_run: true` (restrito às contas do fundador) devolve o plano
      // completo NESTE ponto: por cena — tipo, segundos, palavras e o texto
      // exato que seria falado — mais os totais que os contratos C1/C2
      // prometem. Custo: os centavos do GPT do planner. Zero fal, zero
      // Creatomate, zero TTS, e o débito é estornado na hora pelo mesmo
      // caminho do FAILFAST. Testar um roteiro passa de $7 para ~$0,02.
      {
        const dryRunEmails = new Set(['josephsskaf@gmail.com', 'josephskaf@gmail.com', 'joseph-test@shortsforgeai.com'])
        if (body.dry_run === true && dryRunEmails.has((user.email ?? '').toLowerCase())) {
          const wordsOf = (t?: string) => (t ?? '').trim().split(/\s+/).filter(Boolean).length
          const planReport = plan.scenes.map((sc, i) => ({
            scene: i + 1,
            type: sc.type,
            seconds: sc.seconds ?? null,
            words: wordsOf(sc.type === 'dialogue' ? sc.dialogueLine : sc.voiceover),
            speech: sc.type === 'dialogue' ? (sc.dialogueLine ?? null) : (sc.voiceover ?? null),
          }))
          const spokenSeconds = planReport.reduce((a, r) => a + (r.words > 0 ? (r.seconds ?? 0) : 0), 0)
          const totalSeconds = planReport.reduce((a, r) => a + (r.seconds ?? 0), 0)
          const muteSeconds = totalSeconds - spokenSeconds
          // KINEO-SILENCIO-NA-CENA-2026-09-11 — a mesma régua do render pago, a $0.
          // KINEO-RITMO-DA-VOZ-2026-09-15 — no MESMO ritmo da voz pinada que o portão pago usa (ritmoVoz),
          // senão o ensaio de $0 aprova/reprova um plano diferente do que o render de verdade julga.
          const silence = reguaDoFilme(plan.scenes, ritmoVoz)
          // ═══ KINEO-DRYRUN-PREFLIGHT-2026-08-25 — O CONTRATO DO FORNECEDOR ═══
          // O 422 do primeiro render Omni (image_url faltando, 8/8 cenas)
          // passou LIMPO pelo dry-run porque ele parava no plano e nunca
          // olhava o payload. Agora o dry-run também simula o DESPACHO: modelo
          // por cena (com e sem âncora) + violações do schema (teto de
          // segundos da família, i2v sem imagem). Qualquer violação = FAIL.
          const sceneCapViolations = planReport.filter((r) => (r.seconds ?? 0) > (r.type === 'dialogue' ? DIALOGUE_CAP : SCENE_CAP))
          const dispatchPreview = plan.scenes.map((sc, i) => ({
            scene: i + 1,
            model_with_anchor: cinematicSceneModel(family, sc.type, true),
            model_without_anchor: cinematicSceneModel(family, sc.type, false),
          }))
          const preflightProblems: string[] = []
          // KINEO-FALA-MAIOR-QUE-A-CENA — o inverso da régua de silêncio: fala
          // maior que o clipe. O compose recusa isso depois de pagar; aqui é $0.
          // KINEO-MESMA-REGUA-DO-ESCRITOR-2026-09-25: no ritmo da voz pinada e com a DECISÃO da montagem, não só as constantes
          // (revisão adversarial de 25/09: "constantes iguais não são decisão igual"). O compose (app/api/compose/route.ts,
          // KINEO-FALA-CABE + KINEO-FALA-ATRAVESSA-O-CORTE) aceita a fala que cabe com 0,4 s de respiro; re-sintetiza um fio
          // mais rápido quando fala + 0,4 ≤ clipe × 1,1; e ainda aceita fala ≤ clipe × 1,1 acelerando a ×1,1 sem respiro.
          // Acima disso só a travessia do corte (vão das vizinhas, medido na voz real) salva — o ensaio, que só estima a
          // fala (palavras ÷ ritmo), não conta com ela. A 2,3 fixo e com "+1 s" o ensaio aprovava planos que o render pago
          // recusava (cena 7 do Polo: 22 palavras em 10 s passava por aqui). O guardião executa os dois lados com os mesmos
          // planos: PASS aqui ⇔ a montagem fecha sem precisar das vizinhas.
          // ═══ MIRROR: cabeNaMontagem ═══
          const RESPIRO_MONTAGEM_S = 0.4 // = FALA_CABE_RESPIRO_S
          const ACELERA_MAX_MONTAGEM = 1.1 // = FALA_CABE_MAX_FATOR
          // a mesma tolerância de 0,01 s do compose (`sobra > capacidade + 0.01` / `falta > 0.01`)
          const cabeNaMontagem = (fala: number, segundos: number) => fala + RESPIRO_MONTAGEM_S <= segundos || fala / ACELERA_MAX_MONTAGEM - segundos <= 0.01
          // ═══ END MIRROR: cabeNaMontagem ═══
          for (const r of planReport) {
            const fala = r.words / ritmoVoz
            if (r.words > 0 && (r.seconds ?? 0) > 0 && !cabeNaMontagem(fala, r.seconds ?? 0)) preflightProblems.push(`cena ${r.scene}: ${r.words} palavras ≈ ${fala.toFixed(1)}s de fala (${ritmoVoz} pal/s) num clipe de ${r.seconds}s (×${(fala / (r.seconds ?? 1)).toFixed(2)} > ${ACELERA_MAX_MONTAGEM}) — nem acelerando a ×${ACELERA_MAX_MONTAGEM} cabe; o compose recusaria (scene_speech_exceeds_footage)`)
          }
          for (const v of sceneCapViolations) preflightProblems.push(`cena ${v.scene} (${v.type}) tem ${v.seconds}s > teto ${v.type === 'dialogue' ? DIALOGUE_CAP : SCENE_CAP}s da família ${family}`)
          for (const d of dispatchPreview) {
            const input = buildFalInput(d.model_with_anchor, 'preflight', false, true, plan.scenes[d.scene - 1].seconds, 'https://preflight.local/anchor.png')
            if (d.model_with_anchor.includes('image-to-video') && !input.image_url) preflightProblems.push(`cena ${d.scene}: modelo i2v ${d.model_with_anchor} sem image_url no payload`)
          }
          // ═══ KINEO-S25-NOTA95-2026-10-06 — o ensaio de $0 do S25 mostra o prompt que cada cena levaria ao motor ═══
          // O render pago monta o prompt DEPOIS do supervisor fala×imagem (que reescreve parte das cenas): numa CÓPIA do plano, [KINEO-S25-NOTA95-2026-10-06]
          // supervisor (mesma chamada e mesmo filtro do caminho pago, ~US$ 0,002) → planejarCenasS25 → fidelidade 'fim' → [KINEO-S25-NOTA95-2026-10-06]
          // montarPromptS25. Sem still/âncora (nada é gerado); boca fechada, nitidez e textSafety entram no laço como em toda cena. [KINEO-S25-NOTA95-2026-10-06]
          let s25Ensaio: Record<string, unknown> | null = null // KINEO-S25-NOTA95-2026-10-06
          if (family === 's25') { // KINEO-S25-NOTA95-2026-10-06
            const copia = plan.scenes.map((s) => ({ ...s })) // KINEO-S25-NOTA95-2026-10-06
            try { // KINEO-S25-NOTA95-2026-10-06
              const idxs = copia.map((_, i) => i).filter((i) => copia[i].type !== 'dialogue' && (copia[i].voiceover ?? '').trim().length > 0 && (copia[i].prompt ?? '').trim().length > 0) // KINEO-S25-NOTA95-2026-10-06
              const alinhadoE = idxs.length > 0 ? await alignShotsToSpeech({ topic: prompt, scenes: idxs.map((i) => ({ voiceover: copia[i].voiceover ?? '', shot: copia[i].prompt })) }) : null // KINEO-S25-NOTA95-2026-10-06
              const historiaE = await contextoDoFiltro(`${prompt} ${copia.map((sc) => sc.voiceover ?? '').join(' ')}`) // KINEO-META95-ASSUNTO-1910 — + o assunto traduzido (era a string direta) [KINEO-S25-NOTA95-2026-10-06]
              if (alinhadoE) for (const c of alinhadoE.rewritten) copia[idxs[c.index]].prompt = historiaE === null ? c.shot : scrubInventedSetting(c.shot, historiaE).text // KINEO-META95-ASSUNTO-1910 — null = sem scrub (era scrubInventedSetting direto) [KINEO-S25-NOTA95-2026-10-06]
            } catch { /* falha aberta, como no render pago */ } // KINEO-S25-NOTA95-2026-10-06
            try { // KINEO-S25-NOTA95-2026-10-06
              const s25PlanoE = planejarCenasS25({ cenas: copia.map((s) => ({ prompt: s.prompt, voiceover: s.voiceover ?? null, type: s.type })), roteiro: `${prompt} ${copia.map((s) => s.voiceover ?? '').join(' ')}`, characterSheet: plan.characterSheet, styleSheet: plan.styleSheet, idioma: hollywoodLanguage }) // KINEO-S25-NOTA95-2026-10-06
              s25Ensaio = { // KINEO-S25-NOTA95-2026-10-06
                ...s25PlanoE.relato, // KINEO-S25-NOTA95-2026-10-06
                ambiente_ancora: ambienteComEpoca(plan.environmentSheet ?? '', epocaDoFilmeS25(`${prompt} ${copia.map((s) => s.voiceover ?? '').join(' ')}`, hollywoodLanguage)), // KINEO-S25-NOTA95-2026-10-06
                prompts: s25PlanoE.cenas.flatMap((c) => c ? [{ cena: c.indice + 1, prompt: montarPromptS25({ promptCena: garantirAcaoCentral(silenciarFalaNoPrompt(c.prompt), copia[c.indice].voiceover ?? '', plan.characterSheet ?? '', 'fim').prompt, epoca: c.epoca, eraReserva: eraSuffix, mouthSuffix: '', spectacleSuffix: '' }) }] : []), // KINEO-S25-NOTA95-2026-10-06
              } // KINEO-S25-NOTA95-2026-10-06
            } catch (e) { s25Ensaio = { erro: e instanceof Error ? e.message : String(e) } } // KINEO-S25-NOTA95-2026-10-06 — falha aberta: o render pago seguiria com as cenas do planejador
          } // KINEO-S25-NOTA95-2026-10-06
          await releaseBirthClaim('dry_run_no_charge')
          return NextResponse.json({
            dry_run: true,
            verbatim,
            family,
            // KINEO-UNIVERSAL-2026-08-25 — a DECISÃO DE DIREÇÃO no relatório:
            // é o que permite validar 5 gêneros opostos a $0 (o teste do
            // 'sistema perfeito pra qualquer assunto' que o fundador pediu).
            direction: { genre: plan.genre, hostFits: plan.hostFits, stylized: plan.stylized },
            // KINEO-PRIMEIRA-PESSOA-2026-09-11 — o dry-run de $0 passa a dizer o que
            // o render pago faria com a PESSOA: modo visual (quem fala), a ficha
            // do personagem e a voz que sairia da boca dele. Foi o que faltou
            // para o canario do faroleiro custar $0 em vez de 150 creditos.
            visual_mode: formatoVisual.modo,
            visual_mode_reason: formatoVisual.motivo,
            character_sheet: plan.characterSheet ?? null,
            character_voice: resolveCharacterVoice(plan.characterSheet ?? ''),
            dialogue_scenes: plan.scenes.filter((sc) => sc.type === 'dialogue').length,
            // KINEO-ESTRELA-DO-FILME-2026-09-29 — o ensaio de $0 mostra, cena a cena, qual still iria ao edit com o rosto (nada é gerado)
            ...(estrelaAtiva ? { estrela: { ficha: fichaDaEstrela(prompt, plan.characterSheet), sobretaxa_cr: estrelaSobretaxaDe(duration), cenas: planoDaEstrela(plan.scenes.map((s) => ({ prompt: s.prompt, visual: s.prompt, tipo: s.type })), fichaDaEstrela(prompt, plan.characterSheet), true, prompt).map((p) => ({ cena: p.indice + 1, estrela: p.protagonista })) } } : {}), // KINEO-ESTRELA-DO-FILME-2026-09-29
            target_seconds: hollywoodTarget,
            // KINEO-DEGRAU-2026-09-03 — o plano de $0 reporta a duração que o
            // render pago realmente usaria (já descida) e de onde ela veio.
            requested_seconds: requestedDuration,
            effective_seconds: duration,
            autofit_down: degrau?.applied === true,
            total_seconds: totalSeconds,
            spoken_seconds: spokenSeconds,
            mute_seconds: muteSeconds,
            silence_inside_scenes_seconds: silence.total,
            silence_worst_scene: silence.worstScene,
            silence_worst_seconds: silence.worst,
            silence_per_scene: silence.perScene,
            silence_words_to_add: silence.wordsToAdd,
            preflight_problems: preflightProblems,
            dispatch_preview: dispatchPreview,
            ...(s25Ensaio ? { s25_cenas: s25Ensaio } : {}), // KINEO-S25-NOTA95-2026-10-06
            verdict: muteSeconds <= 6 && totalSeconds >= duration && preflightProblems.length === 0 && silence.ok
              ? 'PASS — todos os segundos têm história (mudo ≤6s, silêncio dentro da cena ≤1,5s/≤8s), a duração fecha e o payload respeita o schema do fornecedor'
              : preflightProblems.length > 0
                ? `FAIL — preflight: ${preflightProblems.join(' · ')}`
                : !silence.ok
                  ? `FAIL — cena ${silence.worstScene} fica ${silence.worst}s sem fala (${silence.total}s no total); faltam ~${silence.wordsToAdd} palavras`
                  : `FAIL — ${muteSeconds}s mudos ou duração ${totalSeconds}s abaixo do piso`,
            scenes: planReport,
            note: 'Nada foi enviado ao fal e os créditos foram estornados. Custo real: só o GPT do planner.',
          })
        }
      }

      // KINEO-HOLLYWOOD-30-2026-07-10 — HOLLYWOOD 3.0 "UM MUNDO": generate the
      // two image anchors from the plan's sheets (portrait + environment
      // still, ~$0.10, synchronous — flux/schnell is fast). FAIL-OPEN: null →
      // every scene falls back to the v2.4 t2v engines below; the render
      // never dies because of anchors.
      // All final cap/split passes have run. Never spend on video scenes for
      // a plan already known to be shorter than the user's selected duration.
      const finalPlannedSeconds = plan.scenes.reduce((sum, scene) => sum + scene.seconds, 0)
      if (finalPlannedSeconds < duration) {
        const refunded = await confirmCinematicRefund()
        const released = refunded && await releaseBirthClaim('plan_duration_below_request')
        return NextResponse.json({
          error: 'The scene plan did not cover the duration you selected. No video scenes were submitted. Review or expand the script before generating again.',
          qualityCheckFailed: true, reason: 'plan_duration_below_request',
          generationId, refunded, refundConfirmed: refunded, claimReleased: released, retryable: false,
          plannedSeconds: finalPlannedSeconds, requestedSeconds: duration,
        }, { status: 422 })
      }
      // ═══ KINEO-SILENCIO-NA-CENA-2026-09-11 — aprovado pelo fundador ═══════
      // Cena de 4 s com 2 palavras passava como "com história" e saía 3 s muda.
      // Régua: silêncio por cena = segundos − palavras ÷ 2,3; reprova acima de
      // 1,5 s numa cena ou 8 s no total. Estorna e diz quantas palavras faltam.
      {
        // KINEO-RITMO-DA-VOZ-2026-09-15: a mesma régua, no passo da voz pinada (ritmoVoz).
        const silence = reguaDoFilme(plan.scenes, ritmoVoz)
        if (!silence.ok) {
          const refunded = await confirmCinematicRefund()
          const released = refunded && await releaseBirthClaim('plan_silence_inside_scenes')
          await writeServerEvent({ name: 'plan_silence_rejected', userId: user.id, path: '/api/generate-video-cinematic', metadata: { generation_id: generationId, family, total_silence: silence.total, worst_scene: silence.worstScene, worst_seconds: silence.worst, per_scene: silence.perScene, words_to_add: silence.wordsToAdd } })
          return NextResponse.json({
            error: `Scene ${silence.worstScene} would sit ${silence.worst.toFixed(1)} seconds with no narration (${silence.total.toFixed(1)} s of silence across the film). Kineo will not pad your story with dead air. Add about ${silence.wordsToAdd} more words, or choose a shorter length. No video scenes were submitted and your credits are back.`,
            qualityCheckFailed: true, reason: 'plan_silence_inside_scenes',
            generationId, refunded, refundConfirmed: refunded, claimReleased: released, retryable: false,
            silenceSeconds: silence.total, worstScene: silence.worstScene, worstSceneSilence: silence.worst, wordsToAdd: silence.wordsToAdd,
            sceneMax: SILENCE_SCENE_MAX_SECONDS, totalMax: silence.totalMax,
          }, { status: 422 })
        }
      }
      // ═══ KINEO-VOZ-NA-BOCA-2026-09-11 — LIGADO POR PADRÃO ═══════════════════
      // Ordem do fundador (11/09): "a gente vai colocar a voz na boca do avatar".
      // Toda cena de diálogo com retrato-âncora sai com a NOSSA voz (TTS, gênero
      // pela ficha) sincronizada nos lábios pelo Kling AI Avatar v2 — a mesma voz
      // que narra o resto do filme. O motor deixa de inventar voz por cena (Kling
      // 3) e a cena deixa de sair muda (Omni/H3). KINEO_HOLLYWOOD_HOST_TTS=off é
      // o interruptor de emergência; qualquer outro valor (inclusive ausente) = ligado.
      // KINEO-S25-FALA-SEM-VOZ-2026-09-14 — o interruptor é lido ANTES das âncoras
      // porque o S25 precisa dele para decidir se pode gastar (abaixo).
      const hostTtsEnabled = process.env.KINEO_HOLLYWOOD_HOST_TTS !== 'off'
      // ═══ KINEO-S25-FALA-SEM-VOZ-2026-09-14 (Board, MOTORES-ESPECIFICOS-R2) ═══
      // O Seedance 2.5 vai ao fal com generate_audio:false (contrato C1). Nesta
      // família uma cena de diálogo SÓ tem voz pelo caminho HOST (TTS na voz
      // pinada + Avatar lip-sync); o fallback nativo entrega um clipe MUDO que o
      // compose recusa (cinematic_dialogue_unverified) DEPOIS de a fal ter cobrado.
      // A primeira tentativa (cb5f746b) forçava faceless em todo pedido S25 — e
      // apagava o caminho saudável do host, trocando em silêncio um apresentador
      // pedido por narração sem rosto. Agora o pedido fica INTACTO: se o host não
      // pode rodar, a incompatibilidade é conhecida antes do POST de cena — a rota
      // para aqui, com o motivo, e devolve pelo padrão dos outros portões do plano
      // (confirmCinematicRefund + releaseBirthClaim). Estorno só é afirmado ao
      // cliente quando confirmado; o custo de âncora já gasto é nosso, como no piso
      // de 90 %. Cena de apoio/documentário do S25 não passa por aqui.
      const s25DialogueScenes = family === 's25' ? plan.scenes.filter((s) => s.type === 'dialogue').length : 0
      // KINEO-S25-FALA-SEM-VOZ-R5-2026-09-14 (Board, MOTORES-ESPECIFICOS-R4 §2) —
      // o mesmo portão serve à terceira porta, DEPOIS de cenas já aceitas: a
      // parte `partial` traz o que já foi ao fornecedor (IDs aceitos, POSTs,
      // tentativa real do host por cena retida). Sem ela = portas 1/2 (0 POST).
      type S25PartialOutcome = {
        heldScenes: number[]
        hostAttempts: Array<{ scene_index: number; host_model: string | null; host_post: boolean | 'unknown'; host_status: number | null }>
        acceptedScenes: Array<{ scene_index: number; request_id: string; model: string | null }>
        scenePosts: number
        stoppedAfterScene: number
      }
      const rejectS25DialogueWithoutHost = async (motivo: string, anchorsGenerated: boolean, partial?: S25PartialOutcome): Promise<NextResponse> => {
        const refunded = await confirmCinematicRefund()
        const released = refunded && await releaseBirthClaim('s25_dialogue_without_host')
        // O desfecho financeiro vai ao contexto: o finalizador único grava
        // claim_action/refund_confirmed em vez de 'unknown' (contabilidade real).
        { const c = ctxDespacho(); c.claimAction = released ? 'released' : 'release_failed'; c.refundConfirmed = refunded; c.planned = plan.scenes.length }
        const scenePosts = partial?.scenePosts ?? 0
        const accepted = partial?.acceptedScenes ?? []
        console.warn(`[cinematic] s25 dialogue without host path (${motivo}): ${s25DialogueScenes} dialogue scene(s), ${scenePosts} scene POST(s), ${accepted.length} accepted scene(s) set aside, held=[${(partial?.heldScenes ?? []).join(',')}], anchors=${anchorsGenerated ? 'spent' : 'not_generated'}, refunded=${refunded}, released=${released}`)
        await writeServerEvent({ name: 's25_dialogue_without_host', userId: user.id, path: '/api/generate-video-cinematic', metadata: {
          generation_id: generationId, family, motivo, dialogue_scenes: s25DialogueScenes, planned_scenes: plan.scenes.length, visual_mode_requested: formatoVisual.modo,
          anchors_generated: anchorsGenerated, scene_posts: scenePosts, refunded, claim_released: released,
          // §1/§2 — o que já existia quando a impossibilidade ficou conhecida: a
          // tentativa REAL do host (POST comprovado / antes do POST / desconhecido),
          // as cenas aceitas (custo nosso, IDs preservados) e o fallback nativo
          // das retidas, que teve ZERO POST por decisão nossa.
          held_scenes: partial?.heldScenes ?? [], host_attempts: partial?.hostAttempts ?? [],
          accepted_scenes: accepted.length, accepted_request_ids: accepted.map((a) => a.request_id),
          native_posts_for_held: 0, stopped_after_scene: partial?.stoppedAfterScene ?? 0,
        } })
        const submittedPart = accepted.length > 0
          ? `${accepted.length} scene${accepted.length === 1 ? '' : 's'} had already started and ${accepted.length === 1 ? 'was' : 'were'} set aside`
          : 'No video scene was started'
        return NextResponse.json({
          error: `Seedance 2.5 cannot voice an on-camera presenter for this film (${motivo}). ${submittedPart}${released ? ' and your credits are back' : ''}. Choose Kling 3, MiniMax H3 or MiniMax H3 Max for a presenter, or ask for a narrated film without a presenter on Seedance 2.5.`, // KINEO-H3MAX-2026-10-13 (o Omni saiu da oferta em 12/10 — pendência do KINEO-SELO-OMNI-2026-10-13)
          qualityCheckFailed: true, reason: 's25_dialogue_without_host', motivo,
          generationId, refunded, refundConfirmed: refunded, claimReleased: released, retryable: false,
          dialogueScenes: s25DialogueScenes, visualMode: formatoVisual.modo,
          heldScenes: partial?.heldScenes ?? [], acceptedScenes: accepted, scenePosts,
        }, { status: 422 })
      }
      if (s25DialogueScenes > 0 && !hostTtsEnabled) {
        return rejectS25DialogueWithoutHost('presenter voice path is switched off', false)
      }
      let anchors: HollywoodAnchors | null = null
      try {
        // Anchor generation is itself paid Fal work. From this point onward an
        // unexpected exception must keep the deterministic claim pending; it
        // must never release and let a new generationId repeat provider spend.
        providerSubmissionMayExist = true
        anchors = await generateHollywoodAnchors({
          characterSheet: plan.characterSheet,
          environmentSheet: plan.environmentSheet,
          // KINEO-S25-NOTA95-2026-10-06 — no S25 a âncora de ambiente nasce com a época do filme ("London, 1952: period clothing…"); antes era a
          // environmentSheet do GPT sem trava nenhuma. Só acrescenta (sobrescreve a chave no S25); as outras famílias: byte a byte. [KINEO-S25-NOTA95-2026-10-06]
          ...(family === 's25' ? { environmentSheet: ambienteComEpoca(plan.environmentSheet, epocaDoFilmeS25(`${prompt} ${plan.scenes.map((s) => s.voiceover ?? '').join(' ')}`, hollywoodLanguage)) } : {}), // KINEO-S25-NOTA95-2026-10-06
          styleSheet: plan.styleSheet,
        })
      } catch (e) {
        if (e instanceof FalQueueSubmitError && e.ambiguous) throw e
        console.error('[cinematic] hollywood anchors threw (falling back to t2v):', e instanceof Error ? e.message : String(e))
        anchors = null
      }
      if (!anchors) console.warn('[cinematic] hollywood 3.0 anchors unavailable — using v2.4 t2v path')

      // KINEO-CHARACTER-LOCK-2026-07-10 — a saved character OVERRIDES the
      // generated portrait anchor: dialogue scenes are seeded with the user's
      // character image, so the presenter is the SAME person in every video.
      // Server-side ownership lookup (id → url); the client never injects raw
      // URLs. Fail-open: an invalid id just falls back to the generated portrait.
      const characterIdRaw = (body.characterId ?? '').toString().trim()
      if (characterIdRaw) {
        try {
          const { getCharacterImageUrl } = await import('@/lib/characters')
          const charUrl = await getCharacterImageUrl(user.id, characterIdRaw)
          if (charUrl) {
            if (anchors) {
              anchors = { ...anchors, portraitUrl: charUrl }
            } else {
              // No generated anchors (flux hiccup) — still lock the character
              // for dialogue scenes; support scenes use the same image as a
              // world reference rather than dropping the lock entirely.
              anchors = { portraitUrl: charUrl, environmentUrl: charUrl }
            }
            console.log(`[cinematic] hollywood character-lock active char=${characterIdRaw.slice(0, 8)}`)
          } else {
            console.warn('[cinematic] character-lock id not found/owned — using generated portrait')
          }
        } catch (e) {
          console.warn('[cinematic] character-lock lookup failed (fail-open):', e instanceof Error ? e.message : String(e))
        }
      }

      // KINEO-HOLLYWOOD-HOST-2026-07-13 (item 2, prepared hook) — the user's
      // OWN clips for demo scenes. Same authorization contract as
      // generate-video-fast (KINEO-USER-FOOTAGE): only URLs inside THIS
      // user's folder of our public user-footage bucket are accepted, so
      // upload gating stays the real authorization. NOT spliced into the
      // render yet: hollywood clip URLs travel client-side exclusively via
      // the fal poll (cinematic-clip-status), so a pre-existing URL has no
      // lane to compose today. When compose grows a per-scene clip-override
      // param, demo scenes should consume `demoUserFootage` in order instead
      // of generating. Until then we log availability and generate demo
      // b-roll (fail-open, zero behavior change).
      const footagePrefix = `${process.env.NEXT_PUBLIC_SUPABASE_URL}/storage/v1/object/public/user-footage/${user.id}/`
      const demoUserFootage = planScenes
        .map((s) => (typeof s.userFootageUrl === 'string' && s.userFootageUrl.startsWith(footagePrefix) ? s.userFootageUrl : null))
        .filter((u): u is string => !!u)
      const demoSceneCount = plan.scenes.filter((s) => s.isDemo === true).length
      if (demoSceneCount > 0) {
        console.log(
          `[cinematic] hollywood demo beat: ${demoSceneCount} demo scene(s) planned${demoUserFootage.length > 0 ? ` — ${demoUserFootage.length} user clip(s) available (inline splicing pending compose hook; generating demo b-roll)` : ''}`,
        )
      }

      // KINEO-HOLLYWOOD-HOST-2026-07-13 (item 1) — narration metadata hoisted
      // ABOVE the submit loop: hVoiceoverScript is the exact voiceover_script
      // string compose receives back from the client, and BOTH routes resolve
      // the narrator persona from it (lib/hollywood/hostVoice) — that's what
      // guarantees the host lines and the b-roll narration share ONE voice.
      // One speech source across Kling/H3/Omni: native dialogue or pinned
      // narration. Compose verifies dialogue; it never covers missing speech
      // with an external narrator. Provider audio capabilities are not a guarantee.
      const hNarrations = sceneNarrationsForPlan(plan.scenes)
      const hVoiceoverScript =
        hNarrations.filter(Boolean).join(' ') ||
        plan.scenes.map((s) => s.dialogueLine ?? '').filter(Boolean).join(' ') ||
        prompt

      // One voice for the whole video. Only meaningful on the anchored path
      // (the presenter engine needs the portrait anchor); resolution is pure
      // and can only fail on truly broken input — fail-open to null → every
      // dialogue scene takes the v3.0 O3 native-audio path unchanged.
      let hostVoice: HollywoodVoice | null = null
      if (anchors) {
        try {
          // KINEO-VOZ-NA-BOCA-2026-09-11 — a ficha do personagem decide o gênero da voz.
          hostVoice = resolveHollywoodVoice(hVoiceoverScript, hollywoodLanguage, hollywoodVertical, plan.characterSheet)
          console.log(
            `[cinematic] hollywood host voice pinned: persona=${hostVoice.personaId} voice=${hostVoice.voice} speed=${hostVoice.defaultSpeed}`,
          )
        } catch (e) {
          console.warn('[cinematic] hollywood host voice resolution failed (falling back to O3 native audio):', e instanceof Error ? e.message : String(e))
          hostVoice = null
        }
      }
      // KINEO-S25-FALA-SEM-VOZ-2026-09-14 — segunda porta: com o interruptor
      // ligado, o host ainda depende das âncoras (retrato) e da voz pinada. Sem
      // uma delas a cena de diálogo do S25 só teria o POST nativo mudo. Para
      // aqui, antes do primeiro POST de cena (âncoras já gastas: custo nosso).
      if (s25DialogueScenes > 0 && (!anchors || !hostVoice)) {
        return rejectS25DialogueWithoutHost(!anchors ? 'the portrait anchor could not be generated' : 'no presenter voice could be pinned', Boolean(anchors))
      }
      const hostPerformancePrompt = buildHostPerformancePrompt(plan.characterSheet, plan.styleSheet)
      // KINEO-VOZ-NA-BOCA-2026-09-11 — `hostTtsEnabled` (ligado por padrão) é
      // declarado acima das âncoras; a explicação vive lá.
      // Verbatim scripts may carry an explicit `speed:` directive — apply it
      // to the host lines exactly like compose applies it to the narration
