      const trabalhadorP = async () => { while (filaP.length > 0 && Date.now() < prazoP) { const c = filaP.shift()!; const r = await gerarStillComFolha({ prompt: promptDoStillComFolhaAjuste(classicScenePrompts[c.indice], fichasDaCena(c), aspectRequested), imageUrls: folhasDaCena(c), aspect: aspectRequested, userId: user.id, engine: `personagem:${personagemMotor}`, pollWindowMs: Math.max(5_000, Math.min(40_000, prazoP - Date.now())), fichas: fichasDaCena(c) }); motivosP[r.motivo] = (motivosP[r.motivo] ?? 0) + 1; if (r.reconferida && r.url) reconferidasP++; if (r.url) stillsP[c.indice] = r.url } } // KINEO-META95-PERSONAGEM-AJUSTE-2010 — formato do filme por extenso + sem painel; still fora do formato ou barrado = o FLUX; era: gerarStillDaEstrela({ prompt: promptDoStillComFolha(…) … })
      if (filaP.length > 0) await Promise.all(Array.from({ length: Math.min(4, filaP.length) }, () => trabalhadorP())) // KINEO-META95-PERSONAGEM-2010
      const criticoP = novoFilmeDoCritico(modoDoCriticoDoStill() === 'off' ? 'off' : 'enforce', { prazo: Date.now() + PERSONAGEM_CRITICO_PRAZO_MS }) // KINEO-META95-PERSONAGEM-AJUSTE-2010 — o edit leva 15-40 s: 35 s de prazo matavam a refação; era: { prazo: Date.now() + 35_000 }
      const relatosP: RelatoCriticoStill[] = [] // KINEO-META95-PERSONAGEM-2010
      await Promise.all(cenasP.filter((c) => stillsP[c.indice]).map(async (c) => { // KINEO-META95-PERSONAGEM-2010
        const fichas = fichasDaCena(c) // KINEO-META95-PERSONAGEM-2010
        const julgado = await criticarStill({ indice: c.indice, url: stillsP[c.indice] as string, mostra: visuaisP[c.indice], fala: scenes[c.indice].voiceover ?? '', prompt: promptDoStillComFolhaAjuste(classicScenePrompts[c.indice], fichas, aspectRequested), seed: generationSeed, referencia: { url: folhasDaCena(c)[0], descricao: fichas.map((f) => f.canonica).join('; ') } }, { // KINEO-META95-PERSONAGEM-AJUSTE-2010 — a foto nova parte do MESMO prompt do still (formato + sem painel); era: promptDoStillComFolha(classicScenePrompts[c.indice], fichas)
          filme: criticoP, tetoCenaMs: PERSONAGEM_CRITICO_TETO_CENA_MS, janelaRegeracaoMs: PERSONAGEM_REGERACAO_JANELA_MS, minRegeracaoMs: PERSONAGEM_REGERACAO_MIN_MS, relatarMotivo: true, // KINEO-META95-PERSONAGEM-AJUSTE-2010 — CAUSA da refação que não saía (regeracao_ok=false): o crítico esperava a foto nova 9 s (janela do FLUX) e o edit leva 15-40 s → provider_timeout; era: filme: criticoP,
          gerarStill: async (promptNovo, _seed, pollWindowMs) => { const r = await gerarStillComFolha({ prompt: promptNovo, imageUrls: folhasDaCena(c), aspect: aspectRequested, userId: user.id, engine: `personagem:${personagemMotor}`, pollWindowMs, fichas }); return { url: r.url, motivo: r.motivo } }, // KINEO-META95-PERSONAGEM-AJUSTE-2010 — a foto nova também sai do edit com a folha, com formato e moderação conferidos, e o MOTIVO vai ao relato; era: (await gerarStillDaEstrela({ … })).url
        }) // KINEO-META95-PERSONAGEM-2010
        relatosP.push(julgado.relato) // KINEO-META95-PERSONAGEM-2010
        stillsP[c.indice] = julgado.url // KINEO-META95-PERSONAGEM-2010
        void writeServerEvent({ name: STILL_CRITIC_EVENTO, userId: user.id, path: '/api/generate-video-cinematic', sessionId: generationId, metadata: { generation_id: generationId, engine: personagemMotor, path_kind: 'personagem', ...julgado.relato } }) // KINEO-META95-PERSONAGEM-2010
      })) // KINEO-META95-PERSONAGEM-2010
      for (let i = 0; i < scenes.length; i++) if (stillsP[i]) sceneStills[i] = stillsP[i] // KINEO-META95-PERSONAGEM-2010 — o still com folha vence o FLUX daquela cena
      personagemRelatoFinal = { ...relatoDoPersonagem({ engine: personagemMotor, elenco: elencoP, casting: personagemElenco.casting, folhas: folhaDe.size, folhasFalhadas: elencoP.length - folhaDe.size, cenas: scenes.length, cenasComPersonagem: cenasP.length, stillsOk: stillsP.filter(Boolean).length, critico: relatosP.map((r) => ({ cena: r.cena, veredito: r.veredito, problemas: r.problemas, regerou: r.regerou, escolhida: r.escolhida })), ms: Date.now() - t0Personagem }), ...relatoDoAjuste({ motivos: motivosP, reconferidas: reconferidasP, cenas: personagemCenas?.cenas ?? cenasDoElenco(visuaisP, scenes.map((s) => s.voiceover ?? ''), elencoP), comFicha: personagemCenas?.comFicha ?? [], semGente: personagemCenas?.semGente ?? [], regeracoes: relatosP, elenco: elencoP }) } // KINEO-META95-PERSONAGEM-AJUSTE-2010 — + os motivos de cada still, a reconferência, as cenas pela fala/sem gente e o motivo de cada refação; era: personagemRelatoFinal = relatoDoPersonagem({ … })
      console.log(`[personagem] gen=${generationId} engine=${personagemMotor} elenco=${elencoP.length} folhas=${folhaDe.size}/${elencoP.length} cenas_com_personagem=${cenasP.length}/${scenes.length} stills_ok=${personagemRelatoFinal.stills_ok} fallback=${personagemRelatoFinal.fallback} critico=${relatosP.map((r) => `${r.cena}:${r.veredito}${r.regerou ? '→' + r.escolhida : ''}`).join(' ')} extra_usd=${personagemRelatoFinal.extra_usd.toFixed(3)} ${personagemRelatoFinal.ms} ms`) // KINEO-META95-PERSONAGEM-2010
      void writeServerEvent({ name: PERSONAGEM_EVENTO, userId: user.id, path: '/api/generate-video-cinematic', sessionId: generationId, metadata: { generation_id: generationId, ...personagemRelatoFinal } }) // KINEO-META95-PERSONAGEM-2010
    } // KINEO-META95-PERSONAGEM-2010
    // <<< KINEO-META95-PERSONAGEM-2010 bloco

    // KINEO-CINEMATIC-ANCHOR-2026-07-24 — returns per-scene ids AND the model
    // each scene actually ran on (i2v for anchored scenes, t2v otherwise), both
    // index-aligned to scenes[]. When anchoring is OFF the models array is
    // uniformly `model`, so claim.falModels is identical to the pre-feature
    // `falRequestIds.map(() => usedModel)`.
    async function submitAllScenes(model: string): Promise<{ ids: (string | null)[]; models: string[] }> {
      // KINEO-PARALLEL-2026-07-24 — engines with NO shared-alias limit
      // (Seedance, Veo) submit with bounded concurrency (pool of 3) to cut
      // submit latency; Kling stays SERIAL with the 450ms stagger because the
      // kling-video alias throttles per user (same shared-alias family as the
      // Hollywood v3 path — kept serial when unsure to avoid burst 4xx drops).
      const canParallelize = model === SEEDANCE_MODEL || model === VEO_MODEL
      const PARALLEL_POOL = 3

      if (canParallelize) {
        // Index-aligned so fal_request_ids[i] always maps to scenes[i] even when
        // some scenes drop out (ambiguous/failed stay null at their own index).
        const ids: (string | null)[] = new Array(scenes.length).fill(null)
        const models: string[] = new Array(scenes.length).fill(model)
        let ambiguousErr: FalQueueSubmitError | null = null
        let stop = false
        for (let start = 0; start < scenes.length && !stop; start += PARALLEL_POOL) {
          const batch: number[] = []
          for (let i = start; i < Math.min(start + PARALLEL_POOL, scenes.length); i++) batch.push(i)
          const settled = await Promise.all(
            // Seedance/Veo are never anchored, so sceneStills[idx] is null here;
            // passed for uniformity (undefined imageUrl → identical t2v submit).
            batch.map(async (idx) => ({ idx, res: await submitScene(scenes[idx], model, idx, sceneStills[idx] ?? undefined) })),
          )
          // An unexpected (non-ambiguous, non-explicit) failure propagates — the
          // outer handler keeps the claim safe. Explicit rejects already became
          // a null id inside submitScene (after the retry).
          const fatal = settled.find(({ res }) => res.kind === 'fatal')
          if (fatal && fatal.res.kind === 'fatal') throw fatal.res.error
          // Record every accepted id FIRST (at its own index), then decide on
          // ambiguity — so an ambiguous sibling never discards a paid job.
          for (const { idx, res } of settled) {
            if (res.kind === 'id') {
              if (res.id) providerSubmissionMayExist = true
              ids[idx] = res.id
              models[idx] = res.model
            } else if (res.kind === 'ambiguous') {
              cinematicSubmissionUncertain = true
              ambiguousErr = res.error
            }
          }
          if (ambiguousErr) {
            if (ids.some((requestId) => requestId !== null)) {
              // A job MAY exist for the ambiguous scene(s); leave them null and
              // stop submitting more — keep the claim pending, never re-POST.
              providerSubmissionMayExist = true
              console.warn('[cinematic] scene submit became ambiguous; preserving earlier accepted scenes')
              stop = true
            } else {
              // Nothing accepted anywhere yet — propagate so the claim stays
              // pending (the ambiguous job may still exist; do not release/refund).
              throw ambiguousErr
            }
          }
        }
        return { ids, models }
      }

      // Serial path (Kling): 450ms stagger between submits + the same real retry.
      const ids: (string | null)[] = []
      const models: string[] = []
      for (let i = 0; i < scenes.length; i++) {
        // KINEO-CINEMATIC-ANCHOR-2026-07-24 — anchored Kling scene → its own
        // FLUX still (i2v); null still → per-scene t2v fallback inside submitScene.
        const res = await submitScene(scenes[i], model, i, sceneStills[i] ?? undefined)
        if (res.kind === 'fatal') throw res.error
        if (res.kind === 'ambiguous') {
          cinematicSubmissionUncertain = true
          if (ids.some((requestId) => requestId !== null)) {
            providerSubmissionMayExist = true
            console.warn('[cinematic] scene submit became ambiguous; preserving earlier accepted scenes')
            ids.push(null)
            models.push(model)
            break
          }
          throw res.error
        }
        if (res.id) providerSubmissionMayExist = true
        ids.push(res.id)
        models.push(res.model)
        await new Promise((r) => setTimeout(r, 450))
      }
      while (ids.length < scenes.length) { ids.push(null); models.push(model) }
      return { ids, models }
    }

    // KINEO-353A.1 — motor e plano REAIS no contexto, antes de despachar.
    {
      const c = ctxDespacho()
      c.engine = usedModel
      c.quality = String(claimQuality)
      c.planned = scenes.length
    }
    const submittedScenes = await submitAllScenes(usedModel)
    const falRequestIds = submittedScenes.ids
    const usedModels = submittedScenes.models
    let validIds = falRequestIds.filter((id): id is string => id !== null)

    // ═══ KINEO-SALDO-PARCIAL-2026-09-21 — recusa por SALDO da fal em QUALQUER cena aborta o filme ═══
    //
    // Caso do fundador (21/09, 00:28 e 01:07 UTC, Seedance 60 s): a fal aceitou 4/8 e depois 3/8 cenas e recusou o
    // resto com "403 User is locked. Reason: Exhausted balance". O ramo de ZERO aceitas (abaixo) estorna e avisa;
    // este caso PARCIAL seguia em frente: publicava o pedido, cobrava 25 cr, a tela esperava "8/8" para sempre,
    // o resgate girava em too_few a cada 5 min, e o estorno só viria pela varredura de 100 min. Pior: as cenas
    // "aceitas" rodaram com a conta travada e também morreram (403 no resultado) — filme impossível desde o início.
    // Saldo esgotado é pane de SUPRIMENTO, não do prompt: a próxima cena também falha. Regra: qualquer 403 de saldo
    // → estorno imediato + alarme ao fundador + mensagem calma. As cenas já submetidas ficam para a fal (custo
    // pequeno) — a pessoa não paga por filme que não vai nascer.
    if (ctxDespacho().balanceExhausted && validIds.length > 0) {
      const released = await releaseBirthClaim('provider_balance_rejected_partial')
      {
        const c = ctxDespacho()
        c.claimAction = released ? 'released' : 'release_failed'
        c.refundConfirmed = released
      }
      console.error(`[cinematic] FAL BALANCE EXHAUSTED mid-dispatch: ${validIds.length}/${scenes.length} accepted — aborting user=${user.id.slice(0, 8)} gen=${generationId} refunded=${released}`)
      // KINEO-FAL-SALDO-ALERTA-2026-09-28 — alarme ao fundador sai do finalizador único, com accepted/planned do resumo.
      if (!released) {
        return NextResponse.json(
          { error: 'Our video provider ran out of capacity mid-way and your automatic refund is still being confirmed. Please retry this same generation in a few minutes.' },
          { status: 503 },
        )
      }
      return NextResponse.json(
        {
          queued: true,
          error: "We're experiencing high demand right now. Nothing was kept from this attempt and your credits were refunded automatically — please try again in a few minutes.",
        },
        { status: 503 },
      )
    }

    // Do not silently downgrade Kling to Seedance after the signed cost/engine
    // claim is born. A rejected premium submit is retriable and never charged.

    // Um único clipe aceito já é renderizável: o compose o recicla até cobrir
    // toda a duração. Nunca descarte/refunde jobs pagos só por cobertura <50%.
    if (!hasRenderableClassicScene(falRequestIds)) {
      // ═══ sprint-retencao #20 (04/09/2026) — PLANO VAZIO NAO E CULPA DA FAL ══
      //
      // `scenes.length === 0` significa que NAO HAVIA UMA UNICA CENA PARA
      // ENVIAR: o laco de submissao nao roda, nenhum POST sai, e o desfecho
      // cai neste mesmo `if` por um caminho completamente diferente do da
      // fal ter recusado. Ate hoje os dois saiam pela mesma porta e a pessoa
      // lia "our video provider did not accept the job" — uma frase sobre um
      // fornecedor que NUNCA foi chamado (`attempted: 0`, `total_posts: 0`).
      //
      // Medido em 21 dias (contas externas): 34 despachos vazios de 25
      // PESSOAS, e NOVE delas nunca viram um filme da Kineo na vida.
      //
      // A razao de release separada tambem tira estes casos do contador de
      // resfriamento la em cima (`/^provider_.*_refunded$/`): aquele guarda
      // existe para impedir que prompt propositalmente ruim vire trabalho
      // PAGO de graca na fal — e com zero POST nao houve trabalho nenhum
      // para farmar. Caso vivo de hoje (pessoa ffd78315, 20:27→20:42 UTC):
      // 4 falhas de plano vazio a levaram ao 429 de 15 minutos, e ela so
      // escapou porque mudou o texto por conta propria.
      const planoVazio = scenes.length === 0
      const released = await releaseBirthClaim(
        ctxDespacho().balanceExhausted
          ? 'provider_balance_rejected'
          : planoVazio
            ? 'empty_plan_rejected'
            : 'provider_rejected',
      )
      // KINEO-353A — o desfecho vai para o banco ANTES de responder, e vai
      // awaitado. Se a lambda morrer logo depois, a linha ja existe.
      {
        const c = ctxDespacho()
        c.claimAction = released ? 'released' : 'release_failed'
        c.refundConfirmed = released
      }
      if (!released) {
        return NextResponse.json(
          { error: 'No AI scenes started and your automatic refund is still being confirmed. Please retry this same generation.' },
          { status: 503 },
        )
      }
      // KINEO-FAL-ALARM-2026-07-06 — if the failure was an exhausted fal balance,
      // don't show a dead error: return a soft "queued" message so the user waits
      // calmly instead of thinking the product broke. The deterministic upfront
      // debit has already been refunded above. KINEO-FAL-SALDO-ALERTA-2026-09-28 —
      // the founder is alerted once, by finalizarDespacho.
      if (ctxDespacho().balanceExhausted) {
        return NextResponse.json(
          {
            queued: true,
            error: "We're experiencing high demand right now. Nothing started and your credits were refunded automatically.",
          },
          { status: 503 },
        )
      }
      // ═══ KINEO-ZERO-POSTS-2026-08-28 — o ramo que quebrou o Joscha ═══════
      //
      // 19joschaschuetz96 falhou SEIS vezes em 25-26/08: claim com
      // fal_models:[], total_posts=0 — NENHUM POST saiu para o fornecedor —
      // e a resposta era o genérico "Please try again" logo abaixo. Ele
      // obedeceu: tentou de novo, e de novo, 6 vezes, achando que a culpa
      // era dele. Zero POSTs significa que o pedido NUNCA CHEGOU no
      // fornecedor: é pane do NOSSO lado do balcão (chave, rede da lambda,
      // client da fal quebrando antes do HTTP) e "tente de novo" é conselho
      // cruel — vai falhar igual. O tratamento certo é o mesmo do saldo
      // esgotado: alarme para o fundador + mensagem que acalma e diz a
      // verdade (nada começou, crédito devolvido, nós fomos avisados).
      if (ctxDespacho().totalPosts === 0) {
        // O ramo do Joscha continua igual quando HAVIA plano: cenas existiam,
        // o POST e que nao saiu. Ai "tente de novo em alguns minutos" e o
        // conselho certo, porque a proxima tentativa pega outra lambda.
        //
        // Com plano VAZIO a frase muda porque o fato e outro. Ela mantem de
        // proposito o fragmento "on our side, not yours": e ele que o
        // classificador de `app/api/cron/send-failure-recovery/route.ts`
        // (DEFEITO_EXPLICITO) usa para reconhecer defeito nosso e mandar o
        // e-mail de resgate. Trocar a copy sem esse pedaco tiraria estas 25
        // pessoas da fila de recuperacao sem ninguem perceber.
        if (planoVazio) {
          // KINEO-ZERO-SCENES-TELEMETRIA-2026-09-04 — o #21 conserta a copy e o
          // motivo do estorno; isto grava O QUE FALTAVA para achar a causa raiz:
          // por que o planner devolve zero cenas em 60s e nao em 35s (caso
          // archiveunknownmedia, 3 falhas, 4a passou so pelo autofit_down).
          // 14 dias: 34 ocorrencias / 25 pessoas / 10 sem nenhum filme.
          try {
            await cinematicAdmin.from('events').insert({
              user_id: user.id,
              name: 'cinematic_zero_scenes_planned',
              path: '/api/generate-video-cinematic',
              metadata: {
                generation_id: generationId,
                engine: usedModel,
                quality: String(claimQuality),
                requested_seconds: requestedDuration,
                effective_seconds: duration,
                clip_count: clipCount,
                verbatim,
                has_markers: parsedScript.hasMarkers === true,
                segments: parsedScript.segments?.length ?? 0,
                narration_chars: (parsedScript.narration ?? '').length,
                refunded: released,
              },
            })
          } catch { /* telemetria nunca derruba a resposta */ }
          // KINEO-FAL-SALDO-ALERTA-2026-09-28 — plano vazio NÃO é saldo: ia como "fal.ai balance EXHAUSTED". Agora o
          // alarme diz o que é (defeito nosso, nada foi enviado), um por janela de 6 h.
          await alertDispatchDefect({ kind: 'EMPTY_PLAN', engine: usedModel, userId: user.id, generationId, context: `user=${user.id.slice(0, 8)} duration=${duration}` })
          return NextResponse.json(
            {
              queued: true,
              error: "We couldn't build a single scene from this text, so nothing was ever sent to our video provider — this is on our side, not yours. Your credits were refunded automatically and the team was alerted. Editing the text, or letting the AI structure it for you, is the change most likely to get this through.",
            },
            { status: 503 },
          )
        }
        // KINEO-FAL-SALDO-ALERTA-2026-09-28 — zero POSTs também não é saldo: alarme de defeito com assunto verdadeiro.
        await alertDispatchDefect({ kind: 'ZERO_POSTS', engine: usedModel, userId: user.id, generationId, context: `user=${user.id.slice(0, 8)} planned=${ctxDespacho().planned}` })
        return NextResponse.json(
          {
            queued: true,
            error: 'Our video provider did not accept the job — this is on our side, not yours. Nothing started, your credits were refunded automatically, and the team was alerted. Please try again in a few minutes.',
          },
          { status: 503 },
        )
      }
      return NextResponse.json(
        { error: 'Could not submit clips to AI generator. Please try again.' },
        { status: 502 }
      )
    }

    const voiceoverScript = verbatim && parsedScript.narration
      ? parsedScript.narration
      : scenes.map((s) => s.voiceover).filter(Boolean).join(' ')

    console.log(
      `[cinematic] submitted ${validIds.length}/${scenes.length} clips to fal.ai user=${user.id.slice(0, 8)} generationId=${generationId}`
    )

    const response: Record<string, unknown> = {
      mode: 'cinematic_ai',
      freeTrial: false,
      generationId,
      prompt,
      duration,
      // KINEO-DEGRAU-2026-09-03 — idem ao caminho hollywood: efetiva + pedida.
      requested_duration: requestedDuration,
      aspect: aspectRequested, // KINEO-VIGIA-FORMATO-2026-09-11
      autofit_down: degrau?.applied === true,
      scenes: scenes.map((s) => s.description),
      scene_captions: scenes.map((s) => s.caption),
      voiceover_script: voiceoverScript,
      fal_request_ids: falRequestIds, // null for failed submissions
      fal_model: usedModel, // #401 — which engine ran (client passes it to clip-status)
      // KINEO-CINEMATIC-ANCHOR-2026-07-24 — per-scene models (i2v for anchored
      // scenes, t2v otherwise), so the client polls each clip on its own endpoint.
      // KINEO-CENA-CLASSICA-2026-09-28 — agora SEMPRE (antes só com âncora): é o
      // modelo que o cliente manda na retomada da cena, e o claim já o assina
      // (fal_models ≡ claim.falModels na amarração da resposta).
      fal_models: usedModels,
      // KINEO-CENA-CLASSICA-2026-09-28 — scene_prompts abre o portão de retomada do
      // cliente (2 rodadas, como na família hollywood); scene_fal_inputs é o payload
      // assinado que /api/retry-hollywood-scene reenvia (só o prompt troca, e só
      // suavizado). O compose e o cron de resgate não leem nenhum dos dois: o
      // cliente só manda scene_* ao compose nas qualidades hollywood, e o cron só
      // quando há scene_engines (que o clássico não tem).
      scene_prompts: classicSceneInputs.map((input) => (typeof input?.prompt === 'string' ? input.prompt : '')),
      scene_fal_inputs: classicSceneInputs,
      // KINEO-KLING25-PLANOS-5S-2026-09-28 — segundos pedidos à fal por cena (5|10), SÓ quando o plano os definiu (Kling 2.5).
      // No claim assinado: o compose monta cada clipe dentro do próprio comprimento (plano de 5 s nunca ocupa 10 s de tela).
      // Ausente (Seedance/Veo/Sora e claims de antes deste deploy) = montagem de hoje.
      // Revisão adversarial (28/09): e onde a fala de CADA cena começa em voiceover_script (também assinado) — o compose
      // corta cada plano no instante da 1ª palavra da própria cena, não numa fatia de tempo cega à cena.
      ...(scenes.some((s) => typeof s.clipSeconds === 'number') ? { clip_seconds: scenes.map((s) => s.clipSeconds ?? null), clip_word_starts: kling25SceneWordStarts(voiceoverScript, scenes.map((s) => s.voiceover)) } : {}),
      quality: claimQuality,
      verbatim,
      speed: parsedScript.speed,
      // Contrato de Cena no caminho classico (Veo, Kling 2.5, Seedance,
      // Kineo 1). Mesmos campos do caminho hollywood, para o placar medir a
      // cobertura REAL do gate sem precisar adivinhar por qual estrada o
      // render passou.
      contrato_cena: contratoRelatoClassico,
      visual_mode: formatoVisual.modo,
