//
// This mirrors groundedFallbackQuery() in lib/broll/aesthetic-packs.ts (proper
// nouns first, then >=4-char non-stopword / non-people / non-numeric tokens).
// That helper is module-private (NOT exported) and additionally requires an
// AestheticPack for its ban check, so this is a deliberate minimal local
// equivalent — DUPLICATED LOGIC. If it is ever exported, delete this and import
// it instead. Stopword/people lists are the ones already defined in this file.
const SCENE_HINT_MAX_CHARS = 240
const SCENE_HINT_MAX_TOKENS = 6

function buildSceneHint(voiceover: string): string {
  const text = (voiceover ?? '').trim()
  if (!text) return ''
  // Short scene: the whole narration IS the signal — no truncation at all.
  if (text.length <= SCENE_HINT_MAX_CHARS) return text

  // Long scene: cut on a word boundary so a proper noun is never split in half.
  let head = text.slice(0, SCENE_HINT_MAX_CHARS)
  const lastSpace = head.lastIndexOf(' ')
  if (lastSpace > 0) head = head.slice(0, lastSpace)

  // ...then append the content-bearing tokens taken from the WHOLE voiceover,
  // proper nouns first, so a distinguishing noun that lands after the cut still
  // reaches the concept matcher instead of being thrown away.
  const proper = (text.match(/\b[A-Z][a-zA-Z]{3,}\b/g) ?? []).map((w) => w.toLowerCase())
  const rest = text.toLowerCase().replace(/[^a-z0-9\s]/g, ' ').split(/\s+/).filter(Boolean)
  const headLower = head.toLowerCase()
  const picked: string[] = []
  for (const w of [...proper, ...rest]) {
    if (w.length < 4) continue
    if (/^\d+$/.test(w)) continue // bare years/numbers are useless stock terms
    if (ALIGN_STOPWORDS.has(w)) continue
    if (PEOPLE_LIFESTYLE_RE.test(w)) continue // never steer the concept map at stock people
    if (picked.includes(w)) continue
    if (headLower.includes(w)) continue // already carried by the kept head
    picked.push(w)
    if (picked.length === SCENE_HINT_MAX_TOKENS) break
  }
  return picked.length > 0 ? `${head} ${picked.join(' ')}` : head
}

// PUSH #96 — the client recorded 1428 `generate_started` against 2
// `generate_failed`, so every server-side rejection of a Fast dispatch was
// invisible in the funnel: a 401, a config gap or an empty stock-footage result
// all looked identical to a user who simply walked away. This helper writes the
// same `generation_stage_error` name the client uses, with the same stage
// vocabulary as `generation_stage_reached`. It never throws (writeServerEvent
// returns false on failure) and never records the prompt, the user's email or
// any API key — only the reason, the HTTP status and non-identifying counts.
function recordFastFailure(
  stage: 'generating' | 'scripting' | 'clips_ready',
  reason: string,
  httpStatus: number,
  userId?: string | null,
  extra?: Record<string, unknown>,
): void {
  void writeServerEvent({
    name: 'generation_stage_error',
    userId: userId ?? null,
    path: '/api/generate-video-fast',
    metadata: {
      stage,
      reason,
      http_status: httpStatus,
      engine: 'fast',
      ...(extra ?? {}),
    },
  })
}

export async function POST(req: NextRequest) {
  try {
    if (!process.env.OPENAI_API_KEY) {
      console.error('[generate-fast] OPENAI_API_KEY is not configured')
      recordFastFailure('generating', 'missing_openai_config', 500)
      return NextResponse.json(
        { error: 'AI service is not configured. Please contact support.' },
        { status: 500 }
      )
    }
    // Push #087 — fail fast if the downstream renderer isn't configured.
    // /api/compose will hard-error on this same check; surfacing it here
    // saves an OpenAI scene-generation call for a job we can't finish.
    if (!process.env.CREATOMATE_API_KEY) {
      console.error('[generate-fast] CREATOMATE_API_KEY is not configured')
      recordFastFailure('generating', 'missing_creatomate_config', 500)
      return NextResponse.json(
        { error: 'Video assembly is not configured — please contact support.' },
        { status: 500 }
      )
    }

    // KINEO-RENDER-CONDUZIDO-PELO-SERVIDOR-2026-09-18 — modo serviço: o cron finish-orphan-jobs termina o pedido de
    // quem fechou a aba antes dos clipes (ver lib/renderJobs.ts). Mesmo contrato do compose (KINEO-SERVICE-FINISH):
    // Bearer CRON_SECRET + x-kineo-service-user = id da conta dona do pedido. Sem os dois, o caminho é o de sempre.
    const serviceSecret = process.env.CRON_SECRET
    const serviceUserHeader = (req.headers.get('x-kineo-service-user') ?? '').trim()
    const isServiceJob =
      !!serviceSecret &&
      req.headers.get('authorization') === `Bearer ${serviceSecret}` &&
      /^[0-9a-f-]{36}$/i.test(serviceUserHeader)
    let user: { id: string; email?: string | null } | null = null
    let supabase: SupabaseClient
    if (isServiceJob) {
      const svcUrl = process.env.NEXT_PUBLIC_SUPABASE_URL
      const svcKey = process.env.SUPABASE_SERVICE_ROLE_KEY
      if (!svcUrl || !svcKey) return NextResponse.json({ error: 'Service mode unavailable.' }, { status: 503 })
      const svc = createAdminClientForService(svcUrl, svcKey, { auth: { persistSession: false, autoRefreshToken: false } })
      supabase = svc // leituras abaixo já filtram por user.id; em modo serviço a chave de serviço faz o papel do cookie
      const { data: svcProfile } = await svc.from('profiles').select('email').eq('id', serviceUserHeader).maybeSingle()
      user = { id: serviceUserHeader, email: svcProfile?.email ?? null }
      console.log(`[fast] service-job mode for user=${serviceUserHeader.slice(0, 8)}`)
    } else {
      supabase = createClient()
      const { data: { user: cookieUser } } = await supabase.auth.getUser()
      user = cookieUser
    }
    if (!user) {
      recordFastFailure('generating', 'unauthenticated', 401)
      return NextResponse.json(
        { error: 'You must be signed in to generate a video.' },
        { status: 401 }
      )
    }

    // ═══ KINEO-E4-SAIDA-B-2026-09-29 [TRAVA 8.2 — "vai E4" do fundador] — PORTÃO DO KINEO 1, ANTES DE QUALQUER FORNECEDOR ═══
    // Kineo 1 fora do jogo (fundador 29/09): só passa quem paga (has_paid / plano pago / Autopilot) ou a casa (lista
    // exata). Fica AQUI — antes do dry-run, do corpo, do planejador (OpenAI), do Pixabay e dos clipes de IA do "1º filme"
    // (~US$ 0,39 de fal por clique que o compose recusaria depois). Regra e razões em lib/kineo1Gate.ts. Leitura falhou
    // = 503 sem gasto (falha FECHADA: esta é uma guarda de dinheiro). Em modo serviço (cron finish-orphan-jobs) o
    // e-mail vem de profiles, que o cliente edita: não vale como "casa" — só plano/has_paid decidem.
    {
      let { data: portaoPerfil, error: portaoErro } = await supabase
        .from('profiles')
        .select('plan, has_paid, trial_status')
        .eq('id', user.id)
        .maybeSingle()
      if (portaoErro && !isServiceJob) {
        const resgatado = await retryOwnReadOnSkew(portaoErro, 'generate-fast', (admin) =>
          admin.from('profiles').select('plan, has_paid, trial_status').eq('id', user!.id).maybeSingle(),
        )
        if (resgatado) { portaoPerfil = resgatado as typeof portaoPerfil; portaoErro = null }
      }
      if (portaoErro) {
        recordFastFailure('generating', 'kineo1_gate_read_failed', 503, user.id)
        return NextResponse.json({ error: 'Your access could not be verified. Nothing was charged. Please retry.', charged: false }, { status: 503 })
      }
      let portao = kineo1GateReason({
        email: isServiceJob ? null : user.email ?? null,
        plan: (portaoPerfil as { plan?: string | null } | null)?.plan ?? null,
        hasPaid: (portaoPerfil as { has_paid?: boolean | null } | null)?.has_paid ?? null,
      })
      // KINEO-E4-CONSERTO-2026-09-29 — em modo serviço a "casa" se decide pelo e-mail do AUTH (nunca o de profiles,
      // editável), lido só quando o resto recusaria. Mesma régua do compose.
      if (portao === 'retired' && isServiceJob) {
        const { data: authData, error: authErr } = await supabase.auth.admin.getUserById(user.id)
        if (!authErr) portao = kineo1GateReason({ email: authData?.user?.email ?? null, plan: (portaoPerfil as { plan?: string | null } | null)?.plan ?? null, hasPaid: (portaoPerfil as { has_paid?: boolean | null } | null)?.has_paid ?? null })
      }
      if (portao === 'retired') {
        // KINEO-E4-CONSERTO-2026-09-29 (revisão de regressão, achado 2) — `await`, não `void`: a Vercel congela a função
        // ao responder e o evento com `void` antes do return grava ~1 em 10 (void-antes-do-return-morre-na-vercel,
        // 16/09). Este evento É a prova pós-deploy ("recusas kineo1_retired sem fal no mesmo user_id").
        await writeServerEvent({ name: KINEO1_RETIRED_EVENT, userId: user.id, path: '/api/generate-video-fast', metadata: { route: 'generate-video-fast', plan: (portaoPerfil as { plan?: string | null } | null)?.plan ?? null, trial_status: (portaoPerfil as { trial_status?: string | null } | null)?.trial_status ?? null, service: isServiceJob, charged: false } })
        return NextResponse.json({ error: KINEO1_RETIRED_MESSAGE, reason: KINEO1_RETIRED_REASON, charged: false, retryable: false, upgrade: '/pricing', alternative_engine: 'seedance' }, { status: 403 })
      }
    }
    // ═══ FIM KINEO-E4-SAIDA-B (portão do Kineo 1) ═══

    // Push #346 — accept brollQueries from the BrollPlan (v3.0 Phase 1).
    // When the client ran generate-broll-plan first (Creator Mode or Autopilot
    // background fetch), the BrollPlan's AI-directed pexelsQuery values are
    // passed here so every scene gets a specific, topic-matched stock search
    // instead of the generic GPT scene description.
    // Push #349 — `brollScenes` carries the full per-scene metadata from the
    // BrollPlan (multi-query list, relevance score, planned duration). It
    // supersedes `brollQueries` (single query per scene), which is kept for
    // backward compat with older clients that only sent one query.
    let body: {
      prompt?: string
      duration?: number
      language?: string
      brollQueries?: Array<{ sceneNumber: number; pexelsQuery: string }>
      brollScenes?: Array<{
        sceneNumber: number
        pexelsQuery?: string
        pexelsQueries?: string[]
        relevanceScore?: number
        durationSeconds?: number
        scenePurpose?: string
        requiresExtension?: boolean
        // KINEO-1-HIBRIDO — 'stock' | 'ai' decidido pelo plano (lib/broll/hybrid-source.ts).
        source?: string
        // Push #486 — the plan scene's narration text, used for CONTENT-BASED
        // scene↔plan alignment (see buildAlignedBrollMeta below).
        narration?: string
        // KINEO-USER-FOOTAGE-2026-07-10 — the user's OWN clip/photo (public
        // user-footage storage URL) pinned to this scene. When present it
        // short-circuits the whole vault/Pixabay resolution for the scene.
        userFootageUrl?: string
      }>
      // #358 — instrumentation: client forwards whether the BrollPlan came back
      // degraded (GPT failed) so we can log/record the reason for VERBATIM.
      brollDegraded?: boolean
      /** KINEO-REGUA-UNICA-2026-09-14 — consentimento explícito para descer a duração quando o roteiro próprio não enche. */
      allow_shorter_duration?: boolean
      // KINEO-ENGINE-FIT-2026-09-09 — o cliente viu o aviso e escolheu manter o Kineo 1.
      engineFitOverride?: boolean
      // KINEO-DRYRUN-CLASSICO-2026-09-12 — validador de $0 (só contas do fundador).
      dry_run?: boolean
      // KINEO1-VERBATIM-ESTICA-2026-09-22 — "Use my script as is" ('verbatim') vale também para prosa sem marcadores.
      script_mode?: string
    }
    try {
      body = await req.json()
    } catch {
      recordFastFailure('generating', 'invalid_request_body', 400, user.id)
      return NextResponse.json({ error: 'Invalid request body.' }, { status: 400 })
    }
    // [TRAVA 8.2 — vai do fundador 29/09 'vai pra todas as 4'] KINEO-ESTRELA-DO-FILME-2026-09-29 — o Kineo 1 monta footage de banco:
    // não há still gerado para pôr o rosto. A estrela é recusada AQUI, antes de qualquer débito (a tela já não oferece). [KINEO-ESTRELA-DO-FILME-2026-09-29]
    if ((body as { estrela?: unknown }).estrela != null && (body as { estrela?: unknown }).estrela !== false) { // KINEO-ESTRELA-DO-FILME-2026-09-29
      return NextResponse.json({ error: estrelaMotorSemAncoraMensagem('fast'), reason: 'estrela_engine', retryable: false, charged: false, refunded: false }, { status: 422 }) // KINEO-ESTRELA-DO-FILME-2026-09-29
    } // KINEO-ESTRELA-DO-FILME-2026-09-29

    // KINEO-IDEIA-COLADA-2026-09-12 — ideia de 1 clique colada na frente do texto
    // da pessoa não é o tema (fichas 7/9/10 do diário dos 20 filmes).
    // ═══ KINEO-DRY-RUN-AUTORIZADO-2026-09-14 (posição, Board 4ª revisão) ═══════
    // dry_run:true de conta NÃO autorizada é rejeitado AQUI — logo depois do body
    // e antes de classificar, planejar (generateScenes), expandir, buscar clipes
    // (Pixabay), gerar abertura (fal) ou cobrar. Zero chamadas a fornecedor.
    if (body.dry_run === true && !isDryRunAccount(user.email)) {
      void writeServerEvent({ name: 'dry_run_not_authorized', userId: user.id, path: '/api/generate-video-fast', metadata: { engine: 'fast', charged: false } })
      return NextResponse.json({ error: 'Dry-run is only available to internal accounts. Send the request without dry_run to generate a video.', reason: 'dry_run_not_authorized', retryable: false }, { status: 403 })
    }
    // ═══ FIM KINEO-DRY-RUN-AUTORIZADO (posição) ═══
    const intake = stripIdeaPrefix((body.prompt ?? '').trim())
    if (intake.strippedIdea) void writeServerEvent({ name: 'idea_prefix_stripped', userId: user.id, path: '/api/generate-video-fast', metadata: { idea: intake.strippedIdea.slice(0, 80), rest_chars: intake.text.length } })
    let prompt = intake.text // KINEO-EPISODIO-COM-ASSUNTO: `let` — o pedido de continuação ganha o episódio anterior abaixo
    if (!prompt) {
      recordFastFailure('generating', 'prompt_missing', 400, user.id)
      return NextResponse.json({ error: 'Prompt is required.' }, { status: 400 })
    }
    // KINEO-PROMPT-PROPRIO-2026-09-16 — a nossa própria tela colada não vira filme nem cobra (ver lib/promptGuard.ts).
    if (looksLikeOurOwnUi(prompt)) {
      recordFastFailure('generating', PROMPT_PROPRIO_REASON, 400, user.id)
      return NextResponse.json({ error: PROMPT_PROPRIO_MESSAGE, reason: PROMPT_PROPRIO_REASON, charged: false }, { status: 400 })
    }
    // KINEO-1-COERENCIA-2026-09-16 — a pílula sozinha ("The incredible true story of", 28 caracteres) não vira
    // filme inventado nem cobra (casos wisadot849 18:43 e uldanai148 03:16). Ver lib/promptGuard.ts.
    if (isBareStarter(prompt)) {
      recordFastFailure('generating', BARE_STARTER_REASON, 400, user.id)
      return NextResponse.json({ error: BARE_STARTER_MESSAGE, reason: BARE_STARTER_REASON, charged: false }, { status: 400 })
    }
    // ═══ KINEO-EPISODIO-COM-ASSUNTO-2026-09-22 — "próximo episódio" recebe o ASSUNTO, não só o gancho ═══
    // Caso balaj.dxb (22/09 11:08Z, nota 20): o pedido de continuação trazia só "Topic: «Witness the ultimate cinematic
    // drone journey… a world of wonders in one frame»" — o gancho do filme 1 — e o escritor inventou Saara, recifes e
    // Amazônia no lugar de Gizé, Burj Khalifa e Eiffel. Agora o pedido original e a narração do episódio anterior
    // viajam junto (lib/seriesContinuation + lib/episodeSubject). Falha aberta: sem episódio anterior, segue como era.
    if (isSeriesContinuationPrompt(prompt)) {
      const anterior = await findPreviousEpisode(supabase, user.id, prompt)
      const enriched = enrichSeriesContinuationPrompt(prompt, anterior)
      void writeServerEvent({ name: 'series_continuation_enriched', userId: user.id, path: '/api/generate-video-fast', metadata: { found: !!anterior, matched_by: anterior?.matchedBy ?? null, previous_video_id: anterior?.id ?? null, added_chars: enriched.length - prompt.length } })
      prompt = enriched
    }
    // ═══ KINEO-PORTA-FORMATO-2026-09-24 — o teto de entrada é o MESMO que a tela mostra ═══
    // Até 24/09 esta rota recusava qualquer texto acima de 5.000 caracteres, enquanto o Studio (lib/analyzeLimits,
    // fonte única) aceita 20.000 no modo em que a IA reescreve e 5.000 só no verbatim ("o texto é o filme"). Medido
    // em 30 d: 22 recusas "Prompt is too long (5000 chars max)" de 4 pessoas, com texto colado do ChatGPT — a coorte
    // que paga 3× mais. Fundador 24/09: "vai" (trava 8.2 liberada nominalmente para esta porta). O que NÃO muda: no
    // verbatim continuam 5.000 e o portão de fala (abaixo) segue recusando o que não cabe em 90 s. O escritor de cenas
    // lê até SCENE_WRITER_INPUT_MAX_CHARS; acima disso o texto entra cortado — agora medido, não escondido.
    {
      const promptMaxChars = analyzePromptMaxChars(body.script_mode)
      if (prompt.length > promptMaxChars) {
        // Only the length is recorded — never the prompt text itself.
        recordFastFailure('generating', 'prompt_too_long', 400, user.id, { prompt_length: prompt.length, max_chars: promptMaxChars, script_mode: body.script_mode ?? null })
        return NextResponse.json({ error: `Prompt is too long (${promptMaxChars} chars max).`, reason: 'prompt_too_long', max_chars: promptMaxChars }, { status: 400 })
      }
      if (prompt.length > SCENE_WRITER_INPUT_MAX_CHARS) {
        void writeServerEvent({ name: 'prompt_over_writer_cap', userId: user.id, path: '/api/generate-video-fast', metadata: { prompt_length: prompt.length, writer_cap: SCENE_WRITER_INPUT_MAX_CHARS, script_mode: body.script_mode ?? null, version: 'porta_formato_v1' } })
      }
    }

    // ═══ PEDIDO-REPETIDO-2026-09-24 — autorização nominal do fundador ("vai no pedido repetido", trava 8.2) ═══
    // Pedido IGUAL (lib/fastDispatchDedupe) chegando enquanto o gêmeo ainda está sendo feito: espera o gêmeo e devolve o
    // MESMO filme, em vez de planejar e encomendar clipes de novo (caso blackmanager284: 6 repetições, 18 clipes pagos).
    // Falha aberta: sem banco, sem gêmeo ou sem resultado em 60 s, segue o caminho de sempre. Dry-run fica fora.
    const pedidoDigital = fastRequestFingerprint({ userId: user.id, prompt, duration: body.duration, language: body.language, aspect: (body as { aspect?: unknown }).aspect, scriptMode: body.script_mode })
    if (body.dry_run !== true && process.env.NEXT_PUBLIC_SUPABASE_URL && process.env.SUPABASE_SERVICE_ROLE_KEY) {
      try {
        const dedupeDb = createAdminClientForService(process.env.NEXT_PUBLIC_SUPABASE_URL, process.env.SUPABASE_SERVICE_ROLE_KEY, { auth: { persistSession: false, autoRefreshToken: false } })
        const gemeoDesde = await findRecentTwin(dedupeDb, user.id, pedidoDigital)
        if (gemeoDesde) {
          const esperaInicio = Date.now()
          const resultado = await waitForTwinResult(dedupeDb, user.id, pedidoDigital, gemeoDesde)
          const resposta = resultado ? responseFromTwin(resultado, prompt) : null
          void writeServerEvent({ name: FAST_DEDUPE_EVENT, userId: user.id, path: '/api/generate-video-fast', sessionId: resultado?.session_id ?? null, metadata: { found: Boolean(resposta), waited_ms: Date.now() - esperaInicio, version: FAST_DEDUPE_VERSION } })
          if (resposta) return NextResponse.json(resposta)
        }
      } catch (e) {
        console.warn('[generate-fast] PEDIDO-REPETIDO: checagem falhou, segue normal:', e instanceof Error ? e.message : String(e))
      }
    }

    // KINEO-DISPATCH-ENTRY-2026-09-05 — a PRIMEIRA prova de SERVIDOR de que o
    // POST chegou. Até aqui, tudo entre o clique e o primeiro erro era evento de
    // CLIENTE: quando a aba ia embora nos primeiros segundos o rastro terminava
    // em `render_wait_abandoned` e não havia como separar "o POST nunca saiu do
    // navegador" de "o POST chegou e morreu aqui dentro". O pedido do Codex de
    // 05/09 11:47 pedia exatamente "localizar o estágio servidor que ocorreu
    // depois de video_generation_started" — e a resposta honesta era: NÃO EXISTE
    // NENHUM. Este evento passa a existir. Fire-and-forget de propósito (`void`,
    // igual a recordFastFailure): telemetria não atrasa nem derruba um render.
    void writeServerEvent({
      name: 'generation_dispatch_received',
      userId: user.id,
      path: '/api/generate-video-fast',
      metadata: {
        engine: 'fast',
        // Só o TAMANHO do texto, nunca o texto — a mesma regra de prompt_too_long.
        prompt_length: prompt.length,
        requested_duration: Number(body.duration) || null,
        fingerprint: pedidoDigital, // PEDIDO-REPETIDO-2026-09-24: marca o pedido em andamento (só o hash, nunca o texto)
      },
    })

    // ═══ KINEO-ENGINE-FIT-2026-09-09 — BANCO DE IMAGENS NÃO CONTA HISTÓRIA ═══
    // Relatório dos motores (09/09): Kineo 1 = 72% dos filmes e a pior nota de
    // fidelidade (35/100), sempre pelo mesmo motivo — ficção/infantil/personagem
    // pedido a um motor de stock. Aqui o servidor devolve 409 com a sugestão
    // (Seedance, custo real) e a tela oferece UMA escolha. Quem insiste manda
    // `engineFitOverride: true` e passa. Nunca é um portão: é um aviso com botão.
    const engineFit = classifyEngineFit(prompt)
    // ═══ KINEO-TRES-MODOS-2026-09-11 — PLANO COLADO NÃO VIRA NARRAÇÃO ══════
    // Render 802f024e (11/09): a pessoa colou um plano JSON (clip/duration/
    // action/camera/vfx) e a narradora LEU O JSON em voz alta. Um prompt de
    // plano só entra pelo modo clipe (/api/generate-clip). Aqui: 422 antes de
    // qualquer débito, com a saída certa na mensagem.
    {
      const shot = detectShotSpec(prompt)
      // KINEO-PORTA-FORMATO-2026-09-24 — roteiro em cenas com FALA rotulada (Voiceover:/Narrator:/VO:) não é plano de
      // clipe: é o formato que o ChatGPT devolve quando a pessoa pede "um roteiro para Short". Medido em 30 d: 14
      // recusas "This looks like a shot plan (camera…)" de 3 pessoas, com linhas de narração no texto. Quando há fala
      // rotulada a rota segue, e o parser (screenplaySpeechOnly, lib/scriptParser) fica só com o que se fala.
      const speechInsideShotPlan = shot.isShotSpec ? screenplaySpeechOnly(prompt) : null
      if (shot.isShotSpec && speechInsideShotPlan) {
        void writeServerEvent({ name: 'shot_spec_with_speech_admitted', userId: user.id, path: '/api/generate-video-fast', metadata: { reason: shot.reason, keys: shot.keys.slice(0, 6), speech_chars: speechInsideShotPlan.length, prompt_length: prompt.length, version: 'porta_formato_v1' } })
      }
      if (shot.isShotSpec && !speechInsideShotPlan) {
        await writeServerEvent({ name: 'shot_spec_detected', userId: user.id, path: '/api/generate-video-fast', metadata: { reason: shot.reason, keys: shot.keys, seconds: shot.seconds, prompt_length: prompt.length } })
        return NextResponse.json({
          error: `This looks like a shot plan (${shot.keys.slice(0, 4).join(', ')}), not a story to narrate. Kineo would read it out loud over the footage. Use "Just this clip (no narration)" in Studio to render exactly this shot (${shot.seconds} s), or write the story you want narrated.`,
          reason: 'shot_spec_detected', clip_seconds: shot.seconds, clip_prompt: shot.prompt.slice(0, 600), retryable: false,
        }, { status: 422 })
      }
    }
    if (engineFit.verdict === 'stock_cannot_tell' && body.engineFitOverride !== true) {
      const requestedForFit = Number(body.duration) || 45
      const suggestedCredits = creditCostForDuration('cinematic_ai', true, requestedForFit)
      void writeServerEvent({
        name: 'engine_fit_warned',
        userId: user.id,
        path: '/api/generate-video-fast',
        metadata: { engine: 'fast', suggested: 'cinematic_ai', suggested_credits: suggestedCredits, signals: engineFit.signals, prompt_length: prompt.length },
      })
      return NextResponse.json(
        {
          error: engineFit.reason,
          engine_fit: { verdict: engineFit.verdict, reason: engineFit.reason, suggested: 'cinematic_ai', suggestedLabel: 'Seedance 1.5', suggestedCredits, signals: engineFit.signals },
        },
        { status: 409 },
      )
    }
    if (body.engineFitOverride === true && engineFit.verdict === 'stock_cannot_tell') {
      void writeServerEvent({ name: 'engine_fit_overridden', userId: user.id, path: '/api/generate-video-fast', metadata: { engine: 'fast', signals: engineFit.signals } })
    }

    const requestedDuration = Number(body.duration) || 45
    let duration: Duration = SUPPORTED_DURATIONS.includes(requestedDuration as Duration)
      ? (requestedDuration as Duration)
      : 45
    // KINEO-MULTIFORMATO-2026-09-02 — enquadramento pedido pelo cliente.
    // Ausente ou inválido = '9:16'. Só influencia a ESCOLHA do footage aqui;
    // a geometria do master é decidida no compose.
    const aspect = normalizeAspect((body as { aspect?: unknown }).aspect)

    let clipCount = clipCountForDuration(duration) // KINEO1-VERBATIM-ESTICA: recalculado se o roteiro próprio subir a duração

    // v3.0 Phase 1: BrollPlan query map — keyed by 1-based sceneNumber.
    // When provided, these AI-directed queries replace the generic GPT scene
    // queries for Pexels searches, giving each scene highly specific footage.
    const brollQueryMap = new Map<number, string>()

    // Push #349 — richer per-scene metadata map. Holds the multi-query list,
    // relevance score and planned duration so the clip loop can run the
    // relevance-aware fallback hierarchy. Keyed by 1-based sceneNumber.
    type BrollSceneMeta = {
      pexelsQuery?: string
      pexelsQueries?: string[]
      relevanceScore?: number
      durationSeconds?: number
      scenePurpose?: string
      /** When true, skip Pexels entirely and extend the previous relevant clip. */
      requiresExtension?: boolean
      /** Push #486 — plan scene narration for content-based alignment. */
      narration?: string
      /** KINEO-USER-FOOTAGE — user's own clip pinned to this scene. */
      userFootageUrl?: string
      /** KINEO-1-HIBRIDO — o plano marcou a cena como 'ai' (banco não cobre). */
      source?: string
    }
    const brollSceneMap = new Map<number, BrollSceneMeta>()

    // KINEO-USER-FOOTAGE-2026-07-10 — only THIS user's folder inside our
    // public user-footage bucket is accepted as a scene override (review
    // catch: the bucket-wide prefix let anyone reference another user's
    // clips and let free accounts consume footage they can't upload —
    // scoping to ${user.id}/ makes upload gating the real authorization).
    const FOOTAGE_PREFIX = `${process.env.NEXT_PUBLIC_SUPABASE_URL}/storage/v1/object/public/user-footage/${user.id}/`

    if (Array.isArray(body.brollScenes)) {
      for (const entry of body.brollScenes) {
        if (typeof entry.sceneNumber !== 'number') continue
        const queries = Array.isArray(entry.pexelsQueries)
          ? entry.pexelsQueries
              .filter((q): q is string => typeof q === 'string' && q.trim().length > 0)
              .map((q) => q.trim())
          : []
        const single =
          typeof entry.pexelsQuery === 'string' && entry.pexelsQuery.trim()
            ? entry.pexelsQuery.trim()
            : queries[0]
        brollSceneMap.set(entry.sceneNumber, {
          pexelsQuery: single,
          pexelsQueries: queries.length > 0 ? queries : single ? [single] : undefined,
          relevanceScore: typeof entry.relevanceScore === 'number' ? entry.relevanceScore : undefined,
          durationSeconds: typeof entry.durationSeconds === 'number' ? entry.durationSeconds : undefined,
          scenePurpose: typeof entry.scenePurpose === 'string' ? entry.scenePurpose : undefined,
          requiresExtension: entry.requiresExtension === true,
          source: entry.source === 'ai' || entry.source === 'stock' ? entry.source : undefined, // KINEO-1-HIBRIDO
          narration: typeof entry.narration === 'string' && entry.narration.trim() ? entry.narration.trim() : undefined,
          // KINEO-USER-FOOTAGE — accept ONLY our public user-footage URLs.
          userFootageUrl:
            typeof entry.userFootageUrl === 'string' && entry.userFootageUrl.startsWith(FOOTAGE_PREFIX)
              ? entry.userFootageUrl
              : undefined,
        })
        if (single) brollQueryMap.set(entry.sceneNumber, single)
      }
    }

    // Backward compat: `brollQueries` (single query per scene). Only fills gaps
    // not already covered by the richer `brollScenes` map above.
    if (Array.isArray(body.brollQueries)) {
      for (const entry of body.brollQueries) {
        if (
          typeof entry.sceneNumber === 'number' &&
          typeof entry.pexelsQuery === 'string' &&
          entry.pexelsQuery.trim() &&
          !brollQueryMap.has(entry.sceneNumber)
        ) {
          brollQueryMap.set(entry.sceneNumber, entry.pexelsQuery.trim())
          // Push #486 — mirror into brollSceneMap so the alignment pass (which
          // reads only brollSceneMap) also covers brollQueries-only clients.
          if (!brollSceneMap.has(entry.sceneNumber)) {
            const q = entry.pexelsQuery.trim()
            brollSceneMap.set(entry.sceneNumber, { pexelsQuery: q, pexelsQueries: [q] })
          }
        }
      }
    }

    if (brollQueryMap.size > 0) {
      console.log(
        `[generate-fast] BrollPlan active: ${brollQueryMap.size} AI-directed scene queries (${brollSceneMap.size} with full metadata)`,
      )
    }

    // Push #434 — Fast generation itself has no credit gate on this route.
    // /api/compose enforces the current free quota (up to 3 watermarked Fast
    // previews per rolling 24h); paid accounts use their documented entitlement.
    // Removing the watermark + the AI engine are the paid upgrades.

    // Push #235 — Verbatim mode. If the user authored the script with explicit
    // `[Pexels: QUERY]` markers, honor them literally: each marker becomes a
    // scene whose footage query and spoken line come straight from the user.
    // We do NOT send the script to GPT in this case — the whole point is that
    // the user already chose the perfect clip and wrote the exact narration.
    const parsedScript = parseUserScript(prompt)
    const marcadoresValidos = parsedScript.hasMarkers && parsedScript.segments.length > 0
    // ═══ KINEO1-IMAGEM-V2-2026-09-28 — instrução colada NÃO é fala (lib/kineo1/pastedBrief.ts) ═══
    // 2ff93c15 (a Lua, 24/09) narrou "Comece nos primeiros 2 segundos com um gancho muito forte…", "Use narração natural…",
    // "Troque as cenas…", "Não use avatar…"; b3b3e101 (os gêmeos, 23/09) narrou "Estilo visual: ilustración minimalista…" e
    // "Subtítulos: grandes, blancos…". Só em "Use my script as is" sem [Pexels:]: as linhas de instrução saem da fala (a do
    // autor fica palavra por palavra, pelo MESMO parser de hoje) e vão como briefing para quem escolhe a imagem
    // (planSceneQueries); sem fala de verdade sobrando, o texto É um briefing — a rota o trata como "a IA estrutura" e o
    // escritor de cenas lê o briefing inteiro (o prompt não muda).
    const briefColado = KINEO1_IMAGEM_V2 && KINEO1_BRIEF_COLADO && body.script_mode === 'verbatim' && !marcadoresValidos ? splitPastedBrief(prompt) : null
    if (briefColado?.mode === 'narration_kept') parsedScript.narration = parseUserScript(briefColado.narration).narration || briefColado.narration
    if (briefColado?.mode === 'brief_only') body.script_mode = 'ai'
    if (briefColado && briefColado.mode !== 'none' && !(body.dry_run === true && isDryRunAccount(user.email))) {
      void writeServerEvent({ name: PASTED_BRIEF_EVENT, userId: user.id, path: '/api/generate-video-fast', metadata: { engine: 'fast', mode: briefColado.mode, lines_total: briefColado.linesTotal, lines_removed: briefColado.brief.length, kinds: briefColado.kinds, narration_words: briefColado.narrationWords, version: PASTED_BRIEF_VERSION } })
      console.log(`[brief-colado] ${briefColado.mode}: ${briefColado.brief.length} linha(s) de instrução fora da fala, ${briefColado.narrationWords} palavra(s) de fala user=${user.id.slice(0, 8)}`)
    }
    // ═══ KINEO-IDIOMA-DO-TEXTO-2026-09-12 — a voz fala a língua do texto. Render
    // 59e1c0ce (11/09): história em ESPANHOL escrita na home, seletor no padrão
    // "en", escritor de cenas em inglês. Escolha explícita (pt/es) vence; o
    // padrão "en" cede ao idioma claro do texto. Evento para medir a troca.
    const narrationLanguage = resolveNarrationLanguage(body.language, prompt)
    // ═══ KINEO-RITMO-POR-VOZ-KINEO1-2026-09-15 — a régua do Kineo 1 anda no passo da voz que VAI falar ═══
    // Craco 7e48bfe5 (15/09): a rota pedia 3,1 pal/s (186 palavras para 60 s); a persona storyteller
    // (fable a 1,03) fala ~2,6 → 190 palavras dariam 72 s e o corretivo aceleraria a voz a 1,2. A
    // persona é resolvida como o compose resolve (tier free = quality 'fast'); régua em lib/speechRate.
    const fastPersona = (() => { try { return selectPersonaForScript(prompt, undefined, 'free', narrationLanguage.language) } catch { return null } })()
    const fastRate = speechRateFor({ family: 'classic', speed: parsedScript.speed, language: narrationLanguage.language, voice: fastPersona?.voice, personaSpeed: fastPersona?.defaultSpeed })
    // ═══ V1-ROTEIRO-NOSSO-CABE-2026-09-23 — autorização nominal do fundador ("V1", 23/09, trava 8.2) ═══
    // Varredura de limites (docs/growth/VARREDURA-LIMITES-2026-09-23.md): 97 pessoas em 30 d bateram em
    // narration_too_short; desde 20/09 quase só Kineo 1 a 35 s, e o roteiro recusado era NOSSO — escrito pela IA no modo
    // "IA estrutura" (autoinício do 1º filme, 57 × 8 literais). 26 de 30 só tiveram filme depois de uma tela de falha e
    // um segundo clique, 4-17 min depois; 4 nunca. Recusar o próprio roteiro não protege ninguém: no modo 'ai' o texto é
    // matéria-prima por contrato. Então, quando o roteiro marcado veio do modo 'ai' e não enche a duração pedida, ele deixa
    // de ser lido palavra por palavra e vira o TEMA do escritor de cenas desta rota, que dimensiona a fala pela duração
    // (wordsPerSceneFor). Roteiro literal ("Use my script as is") continua intocado e continua podendo ser recusado.
    const falaMarcada = marcadoresValidos ? parsedScript.segments.map((seg) => seg.voiceover ?? '').join(' ') : ''
    const roteiroIaCurto = marcadoresValidos && body.script_mode === 'ai' && !narrationFitAt(falaMarcada, duration, fastRate).ok
    const verbatim = marcadoresValidos && !roteiroIaCurto
    if (roteiroIaCurto && !(body.dry_run === true && isDryRunAccount(user.email))) {
      const fitIa = narrationFitAt(falaMarcada, duration, fastRate)
      void writeServerEvent({ name: 'ai_script_rewritten_to_fit', userId: user.id, path: '/api/generate-video-fast', metadata: { engine: 'fast', requested_seconds: duration, speech_seconds: Math.round(fitIa.speech * 10) / 10, coverage: Math.round(fitIa.coverage * 100) / 100, words_per_second: fastRate.wordsPerSecond, version: 'v1_roteiro_nosso_cabe_20260923' } })
      console.log(`[generate-fast] V1-ROTEIRO-NOSSO-CABE: roteiro da IA com ${Math.round(fitIa.speech)}s de fala para ${duration}s → escritor de cenas dimensiona pela duração (user=${user.id.slice(0, 8)})`)
    }
    // ═══ KINEO1-VERBATIM-ESTICA-2026-09-22 — "Use my script as is" vale para PROSA, e o roteiro manda na duração ═══
    // Caso Emily (22/09 13:16Z, nota 75): script_mode 'verbatim' com prosa sem [Pexels:] caía no modo IA — o escritor
    // reescreveu 215 palavras em 3ª pessoa e inventou uma cena. Fundador: "Estica então". Agora: (1) prosa própria é
    // narrada como está (blocos por frase, lib/proseBlocks; as buscas vêm do plano de B-roll alinhado por narração);
    // (2) se a fala enche uma duração MAIOR do seletor, a duração sobe (até 90 s) — o compose já acaba o filme quando
    // o texto acaba; (3) acima do teto, recusa honesta sem gasto.
    const ownScript = verbatim || body.script_mode === 'verbatim'
    const prosaVerbatim = ownScript && !verbatim
    const falaPropria = verbatim ? parsedScript.segments.map((seg) => seg.voiceover ?? '').join(' ') : (parsedScript.narration && parsedScript.narration.trim().length > 0 ? parsedScript.narration : prompt)
    if (ownScript) {
      const speechSeconds = falaPropria.trim().split(/\s+/).filter(Boolean).length / fastRate.wordsPerSecond
      const sobe = decideDurationFollowsScriptUp({ ownScript, requestedSeconds: duration, speechSeconds, largestFitting: largestFittingDuration(speechSeconds, SUPPORTED_DURATIONS) })
      if (sobe?.kind === 'too_long') {
        if (!(body.dry_run === true && isDryRunAccount(user.email))) {
          void writeServerEvent({ name: 'narration_guard_blocked', userId: user.id, path: '/api/generate-video-fast', metadata: { engine: 'fast', reason: 'script_too_long_for_engine', requested_seconds: duration, speech_seconds: sobe.speechSeconds, max_seconds: sobe.maxSeconds, words_per_second: fastRate.wordsPerSecond, charged: false } })
          return NextResponse.json({
            error: `Your script runs about ${sobe.speechSeconds}s of narration, and Kineo 1 films go up to ${sobe.maxSeconds}s. Trim the text, or switch to "Let AI structure it" and we will fit it. Nothing was charged.`,
            reason: 'script_too_long_for_engine', speech_seconds: sobe.speechSeconds, max_seconds: sobe.maxSeconds, retryable: false, charged: false,
          }, { status: 422 })
        }
      } else if (sobe?.kind === 'up' && (SUPPORTED_DURATIONS as readonly number[]).includes(sobe.to)) {
        duration = sobe.to as Duration
        clipCount = clipCountForDuration(duration)
        if (!(body.dry_run === true && isDryRunAccount(user.email))) void writeServerEvent({ name: DURATION_FOLLOWED_SCRIPT_EVENT, userId: user.id, path: '/api/generate-video-fast', metadata: { engine: 'fast', direction: 'up', from: sobe.from, to: sobe.to, speech: sobe.speechSeconds, prose: prosaVerbatim, version: sobe.version, words_per_second: fastRate.wordsPerSecond } })
        console.log(`[generate-fast] KINEO1-VERBATIM-ESTICA: ${sobe.from}s → ${sobe.to}s (speech ${sobe.speechSeconds}s) user=${user.id.slice(0, 8)}`)
      }
    }
    if (fastPersona) console.log(`[generate-fast] KINEO-RITMO-POR-VOZ-KINEO1: persona=${fastPersona.id} voice=${fastPersona.voice} speed=${fastPersona.defaultSpeed} → ${fastRate.wordsPerSecond} pal/s`)
    if (narrationLanguage.switched) {
      void writeServerEvent({ name: 'narration_language_autodetected', userId: user.id, path: '/api/generate-video-fast', metadata: { requested: body.language ?? null, detected: narrationLanguage.detected, confidence: narrationLanguage.confidence, verbatim } })
    }

    // #358 — instrumentation: record WHY this generation uses VERBATIM (and
    // whether the upstream BrollPlan was degraded). degradedReason is persisted
    // to broll_metrics below.
    const brollDegraded = body.brollDegraded === true
    const degradedReason: string | null = brollDegraded
      ? 'plan_degraded'
      : verbatim
        ? (parsedScript.hasMarkers ? 'markers_detected' : 'verbatim_unknown')
        : null
    console.log('[gen-fast] broll plan received', {
      degraded: body.brollDegraded ?? null,
      scenes_count: body.brollScenes?.length ?? body.brollQueries?.length ?? 0,
      has_markers_in_script: parsedScript.hasMarkers,
      will_use_verbatim: verbatim,
      reason_for_verbatim: verbatim
        ? (brollDegraded ? 'plan_degraded' : parsedScript.hasMarkers ? 'markers_detected' : 'unknown')
        : null,
    })

    // Step 1 — Build scenes.
    //   - Verbatim: one scene per [Pexels: ...] marker, query + narration as-is.
    //   - Otherwise: GPT plans scenes (each with a cinematic description and
    //     topic-specific Pexels keywords). Push #235 widened the prompt window
    //     from 400 → 1200 chars so longer briefs keep their topic fidelity.
    let scenes: Scene[]
    if (verbatim) {
      // KINEO-TETO-EXPLICITO-2026-09-14 — acima de 12 blocos a rota RECUSA antes do gasto (portão abaixo); aqui nunca chega roteiro maior.
      scenes = parsedScript.segments.map((seg) => ({
        description: seg.pexelsQuery,
        searchKeywords: seg.pexelsQuery,
        stockSearchQuery: seg.pexelsQuery,
        negativeVisualPrompt: '',
        scenePurpose: 'EXPLANATION',
        visualIntent: 'User-specified footage',
        visualCategory: 'general_documentary',
        voiceover: seg.voiceover,
        caption: shortCaptionFromVoiceover(seg.voiceover || seg.pexelsQuery),
      }))
      console.log(
        `[generate-fast] VERBATIM mode: ${scenes.length} user-specified clip(s); speed=${parsedScript.speed ?? 'default'}`,
      )
    } else if (prosaVerbatim) {
      // KINEO1-VERBATIM-ESTICA-2026-09-22 — prosa própria: um bloco por cena, palavras da pessoa intocadas; a busca de
      // reserva é a do bloco, e o plano de B-roll (alinhado por narração, abaixo) traz as buscas de verdade.
      const blocos = splitProseIntoBlocks(falaPropria, clipCount)
      scenes = blocos.map((bloco) => ({
        description: bloco,
        searchKeywords: fallbackStockQuery(bloco),
        stockSearchQuery: fallbackStockQuery(bloco),
        negativeVisualPrompt: '',
        scenePurpose: 'EXPLANATION',
        visualIntent: 'User-authored narration',
        visualCategory: 'general_documentary',
        voiceover: bloco,
        caption: shortCaptionFromVoiceover(bloco),
      }))
      console.log(`[generate-fast] VERBATIM prose: ${scenes.length} block(s) from ${falaPropria.split(/\s+/).length} words, no rewrite`)
    } else {
      try {
        // KINEO-VIGIA-PALAVRAS-POR-CENA-2026-09-11 — o escritor de cenas nunca
        // soube a duração: pedia 10-22 palavras por cena e um filme de 90 s
        // nascia com ~100 palavras (37 s de fala). O compose então REESCREVIA o
        // corpo para 279 palavras sob os 17 clipes escolhidos para as 114
        // originais (render 59e1c0ce, 11/09). Agora cada cena nasce com a
        // fatia de palavras que a duração pede — a mesma régua do escalador,
        // que passa a ser no-op (±15%) e o footage volta a casar com a fala.
        scenes = await generateScenes(prompt.slice(0, SCENE_WRITER_INPUT_MAX_CHARS), clipCount, undefined, {
          wordsPerScene: wordsPerSceneFor(duration, clipCount, fastRate.wordsPerSecond), // KINEO-RITMO-POR-VOZ-KINEO1-2026-09-15
          language: narrationLanguage.language,
        })
        // ═══ KINEO-TERCEIRA-PASSADA-2026-09-14 — o Kineo 1 a 90 s ficava 5% curto ═══
        // Dry-run de 14/09: ideia de 1 linha a 90 s → 263 palavras (84,8 s a 3,1)
        // para um piso de 86 s; o mesmo brief deu 180 numa rodada e 280 na outra.
        // O escritor mira o meio da faixa e o modelo entrega ~5% abaixo. Quando o
        // total fica abaixo de 95% do alvo do escalador, cada cena curta ganha a
        // reescrita por alvo (mesma função da família hollywood), texto da IA —
        // nunca do autor (este ramo é o modo IA). Fail-open.
        try {
          const wordsOf = (t: string | undefined) => (t ?? '').trim().split(/\s+/).filter(Boolean).length
          const alvoTotal = Math.round(Math.max(5, Math.min(120, Math.round(duration))) * fastRate.wordsPerSecond) // KINEO-RITMO-POR-VOZ-KINEO1-2026-09-15: mesma régua da faixa
          const total = scenes.reduce((a, s) => a + wordsOf(s.voiceover), 0)
          if (scenes.length > 0 && total < alvoTotal * 0.95) {
            const porCena = Math.ceil(alvoTotal / scenes.length)
            const curtas = scenes.map((s, i) => ({ i, s })).filter(({ s }) => wordsOf(s.voiceover) < porCena)
            const novas = await expandVoiceoversToTargets(curtas.map(({ s }) => ({ text: s.voiceover ?? '', targetWords: porCena + 2, maxWords: porCena + 8 })), narrationLanguage.language, prompt.slice(0, 300))
            // Board 14/09: a legenda deriva da fala e acompanha; a consulta visual e a
            // descrição da cena ficam — a reescrita preserva fatos, nomes e números.
            curtas.forEach(({ s }, k) => { if (novas[k] && novas[k] !== s.voiceover) { s.voiceover = novas[k]; s.caption = shortCaptionFromVoiceover(novas[k]) } })
            const depois = scenes.reduce((a, s) => a + wordsOf(s.voiceover), 0)
            console.log(`[generate-fast] KINEO-TERCEIRA-PASSADA: ${total} → ${depois} palavras (alvo ${alvoTotal}, ${curtas.length} cena(s))`)
          }
        } catch (e) {
          console.warn('[generate-fast] terceira passada pulada:', e instanceof Error ? e.message : String(e))
        }
      } catch (err) {
        const msg = err instanceof Error ? err.message : String(err)
        console.error('[generate-fast] scene generation failed:', msg)
        // KINEO-OPENAI-QUOTA-2026-07-31 — when the OpenAI account is out of
        // credits, "try a different prompt" is a lie that burns retries (5+
        // blind attempts/person measured during the 31/07 blackout). Page the
        // founder, record a distinct reason, answer 503 with honest copy —
        // GenerateClient already displays this error string verbatim.
        if (looksOpenAiQuotaDead(err)) {
          await alertOpenAiExhausted('/api/generate-video-fast (scene generation)', openAiAlertKind(err))
          recordFastFailure('scripting', 'openai_quota_dead', 503, user.id, {
            error_name: err instanceof Error ? err.name : 'unknown',
            clip_count: clipCount,
          })
          return NextResponse.json(
            { error: ENGINE_CAPACITY_MESSAGE, code: 'engine_capacity' },
            { status: 503 },
          )
        }
        // KINEO-OPENAI-HANG-2026-08-05 — the sibling failure mode, and the one
        // that actually bit on 05/08: OpenAI never answered, this route blew its
        // 120s budget, and Vercel's gateway returned a raw 504 the client logged
        // as `fast_dispatch_not_ok`. A gateway 504 skips this handler entirely,
        // so the user saw the generic "Video generation failed. Please try
        // again." and retried into the same wall 4 times. With the client
        // timeout capped in lib/openai.ts the hang now arrives as a catchable
        // error here, and gets the same honest 503 as an empty wallet.
        if (looksOpenAiHanging(err)) {
          await alertOpenAiExhausted('/api/generate-video-fast (scene generation)', 'hang')
          recordFastFailure('scripting', 'openai_hang', 503, user.id, {
            error_name: err instanceof Error ? err.name : 'unknown',
            clip_count: clipCount,
          })
          return NextResponse.json(
            { error: ENGINE_CAPACITY_MESSAGE, code: 'engine_capacity' },
            { status: 503 },
          )
        }
        recordFastFailure('scripting', 'scene_generation_failed', 500, user.id, {
          error_name: err instanceof Error ? err.name : 'unknown',
          clip_count: clipCount,
        })
        // KINEO-OPENAI-429-BLINDSPOT-2026-08-14 — a copy antiga aqui era
        // "Failed to plan scenes. Please try a different prompt."
        //
        // Este é o catch RESIDUAL: quota e hang já saíram acima com a mensagem
        // honesta de capacidade. Sobra aqui o erro que NÃO sabemos classificar
        // — e era justamente sobre esse desconhecido que a frase antiga fazia
        // uma afirmação confiante e falsa: culpava o PROMPT da pessoa.
        //
        // Duas consequências medidas em 31/07: (1) quem escreveu um prompt bom
        // acredita que escreveu um prompt ruim e reescreve — 5+ tentativas
        // cegas por pessoa, cada uma outra chamada contra a mesma OpenAI que
        // acabou de falhar; (2) o funil registra "usuário desistiu do prompt"
        // onde o que houve foi falha nossa.
        //
        // A frase nova não sabe mais do que sabemos: diz que a falha é nossa,
        // que nada foi cobrado (verdade — no Fast o débito só ocorre na
        // entrega, em compose/status/[renderId]) e que repetir o MESMO pedido
        // é a ação certa. Só sugerimos mudar o texto como segunda opção, sem
        // afirmar que ele é o culpado.
        return NextResponse.json(
          {
            error:
              'We could not plan the scenes for this video — that is on us, not your idea. Nothing was charged. Please try again in a moment; if it keeps failing, try rewording your idea.',
          },
          { status: 500 }
        )
      }
    }

    // KINEO1-IMAGEM-V2-2026-09-28 — o que o planejador de buscas lê além das falas: o briefing colado vem na frente.
    const contextoDoPlano = { language: narrationLanguage.language, topic: briefColado?.mode === 'narration_kept' ? `${briefColado.brief.join(' ')} | ${prompt}` : prompt }

    // ═══ KINEO-DRYRUN-CLASSICO-2026-09-12 — VALIDADOR DE $0 DO KINEO 1 ═══
    // ═══ KINEO-REGUA-UNICA-2026-09-14 — O KINEO 1 ENCURTAVA SEM AVISAR ═══════
    // Medido nos arquivos entregues (cabeçalho MP4, 14/09): 515c188b pediu 35 s,
    // roteiro próprio de 50 palavras, filme de 18,7 s — sem recusa, sem degrau,
    // sem evento. A rota cinematic tem portão; esta não tinha. Direção do
    // fundador: roteiro próprio não é reescrito, acelerado nem cortado em
    // silêncio — antes do gasto, oferecer expansão ou uma duração menor.
    // Board 14/09: o portão roda ANTES do dry-run, para o dry-run exercitar
    // exatamente esta decisão (o relatório carrega `gate`).
    // ═══ KINEO-DRY-RUN-AUTORIZADO-2026-09-14 (Board): o portão conferia só
    // `body.dry_run`; uma conta externa mandando dry_run:true pulava a recusa e
    // chegava à seção paga. A autorização (conta do fundador) vem ANTES de
    // qualquer decisão que dependa de "é ensaio". Pedido de dry-run não
    // autorizado é tratado como pedido real: recusa quando deve recusar.
    const dryRunAutorizado = body.dry_run === true && isDryRunAccount(user.email)
    // Board 14/09 (ajuste 2): UMA régua para o portão e para o relatório do dry-run
    // (família clássica × velocidade lida do roteiro).
    const narrationRate = fastRate // KINEO-RITMO-POR-VOZ-KINEO1-2026-09-15: a mesma régua (voz da persona) da faixa, do portão e do relatório
    let portao: { blocked: boolean; reason: 'narration_too_short' | 'too_many_clips' | null; speech_seconds: number; target_seconds: number; missing_words: number; shorter_duration: number | null; words_per_second: number; basis: 'estimate'; autofit_applied: boolean } | null = null
    if (ownScript) { // KINEO1-VERBATIM-ESTICA: o portão da fala vale para marcadores E prosa própria
      // KINEO-TETO-EXPLICITO-2026-09-14 (Board): o Kineo 1 monta até 12 clipes. Um
      // roteiro com mais blocos [Pexels] NÃO é fundido em silêncio (isso jogava
      // fora a direção visual dos blocos 13+): a pessoa decide antes do gasto.
      const MAX_CLIP_BLOCKS = 12
      if (parsedScript.segments.length > MAX_CLIP_BLOCKS) {
        portao = { blocked: true, reason: 'too_many_clips', speech_seconds: 0, target_seconds: duration, missing_words: 0, shorter_duration: null, words_per_second: 0, basis: 'estimate', autofit_applied: false }
        if (!dryRunAutorizado) {
          void writeServerEvent({ name: 'narration_guard_blocked', userId: user.id, path: '/api/generate-video-fast', metadata: { engine: 'fast', reason: 'too_many_clips', clips: parsedScript.segments.length, max_clips: MAX_CLIP_BLOCKS, charged: false } })
          return NextResponse.json({
            error: `Your script has ${parsedScript.segments.length} clip blocks, and Kineo 1 films use up to ${MAX_CLIP_BLOCKS}. Merge a few [Pexels: …] blocks (each block becomes one clip) or move the extra lines into a neighboring block, then generate again. Nothing was charged.`,
            reason: 'too_many_clips', clips: parsedScript.segments.length, max_clips: MAX_CLIP_BLOCKS, retryable: false,
          }, { status: 422 })
        }
      }
      const falaDoAutor = falaPropria // KINEO1-VERBATIM-ESTICA: marcadores → segmentos; prosa → a narração inteira
      let fit = narrationFitAt(falaDoAutor, duration, narrationRate)
      let autofitApplied = false
      if (!fit.ok && body.allow_shorter_duration === true) {
        const menor = largestFittingDuration(fit.speech)
        if (menor && menor < duration && (SUPPORTED_DURATIONS as readonly number[]).includes(menor)) {
          const pedida = duration
          duration = menor as Duration
          fit = narrationFitAt(falaDoAutor, duration, narrationRate)
          autofitApplied = true
          if (!dryRunAutorizado) void writeServerEvent({ name: 'narration_autofit_down', userId: user.id, path: '/api/generate-video-fast', metadata: { engine: 'fast', requested_seconds: pedida, effective_seconds: duration, speech_seconds: Math.round(fit.speech * 10) / 10, words_per_second: narrationRate.wordsPerSecond, basis: narrationRate.basis } })
        }
      }
      // ═══ KINEO-DURACAO-SEGUE-O-ROTEIRO-KINEO1-2026-09-22 — a parede mudou de endereço ═══
      // Medido 22/09 (30 d, contas externas): desde que o cinematic passou a descer a duração sozinho (19/09), a
      // parede "your script is N s, you asked for N s" ZEROU no Seedance — e no Kineo 1 subiu de 0,8/dia para
      // 3,7/dia (11 em 3 dias, 9 pessoas). O trial de 10 cr é só Kineo 1: esta era a primeira parede que todo
      // cadastro novo encontrava. Mesma regra do fundador ("roteiro colado: duração segue as palavras"): roteiro
      // próprio + uma duração do seletor que cabe → desce e renderiza, em vez de recusar e pedir palavras.
      // `allow_shorter_duration` (bloco acima) nunca é enviado pelo cliente; fica como caminho explícito.
      if (!fit.ok && !autofitApplied) {
        const seguiu = decideDurationFollowsScript({ fitOk: fit.ok, ownScript, requestedSeconds: duration, speechSeconds: fit.speech, largestFitting: largestFittingDuration(fit.speech), floorSeconds: 35 })
        if (seguiu && (SUPPORTED_DURATIONS as readonly number[]).includes(seguiu.to)) {
          const pedida = duration
          duration = seguiu.to as Duration
          fit = narrationFitAt(falaDoAutor, duration, narrationRate)
          autofitApplied = true
          if (!dryRunAutorizado) void writeServerEvent({ name: DURATION_FOLLOWED_SCRIPT_EVENT, userId: user.id, path: '/api/generate-video-fast', metadata: { engine: 'fast', from: pedida, to: duration, speech: seguiu.speechSeconds, fits_now: fit.ok, version: seguiu.version, words_per_second: narrationRate.wordsPerSecond } })
          console.log(`[generate-fast] duration follows script: ${pedida}s → ${duration}s (speech ${seguiu.speechSeconds}s) user=${user.id.slice(0, 8)}`)
        }
      }
      if (!portao?.blocked) portao = { blocked: !fit.ok, reason: fit.ok ? null : 'narration_too_short', speech_seconds: Math.round(fit.speech * 10) / 10, target_seconds: duration, missing_words: fit.missingWords, shorter_duration: largestFittingDuration(fit.speech), words_per_second: narrationRate.wordsPerSecond, basis: narrationRate.basis, autofit_applied: autofitApplied }
      if (!fit.ok && !dryRunAutorizado) {
        void writeServerEvent({ name: 'narration_guard_blocked', userId: user.id, path: '/api/generate-video-fast', metadata: { engine: 'fast', reason: 'narration_too_short', requested_seconds: duration, speech_seconds: Math.round(fit.speech * 10) / 10, coverage: Math.round(fit.coverage * 100) / 100, words_per_second: narrationRate.wordsPerSecond, basis: narrationRate.basis, charged: false } })
        return NextResponse.json({
          error: narrationTooShortMessage(fit, SUPPORTED_DURATIONS),
          reason: 'narration_too_short',
          speech_seconds: Math.round(fit.speech),
          target_seconds: duration,
          missing_words: fit.missingWords,
          shorter_duration: largestFittingDuration(fit.speech),
          retryable: false,
        }, { status: 422 })
      }
    }

    // Devolve as cenas planejadas e a narração ANTES do hook pago da IA
    // (Seedance 5 s), do Pixabay e do compose. O Kineo 1 só cobra na entrega
    // (compose/status), então aqui não há nada a estornar.
    if (dryRunAutorizado) {
      const fastReport = classicDryRunReport({
        scenes: scenes.map((s) => ({ voiceover: s.voiceover, prompt: s.description })),
        targetSeconds: duration,
        secondsPerClip: duration / Math.max(1, clipCount),
        verbatim,
        elasticFootage: true, // Pixabay é cortado à medida da fala; não há teto de clipe
        wordsPerSecond: narrationRate.wordsPerSecond, // Board 14/09: a mesma velocidade efetiva do portão
      })
      // Board 14/09 (ajuste 2): o resultado global NUNCA diz PASS quando o portão
      // bloqueia (roteiro curto ou excesso de blocos): o portão manda no veredito.
      const portaoBloqueia = portao?.blocked === true
      const vereditoDoPortao = portaoBloqueia
        ? (portao?.reason === 'too_many_clips'
          ? `FAIL — portão: ${parsedScript.segments.length} blocos [Pexels], o Kineo 1 monta até 12 — o render real seria recusado antes do gasto`
          : `FAIL — portão: ${portao?.speech_seconds ?? 0}s de fala a ${portao?.words_per_second ?? narrationRate.wordsPerSecond} pal/s para ${duration}s — o render real seria recusado antes do gasto`)
        : null
      // KINEO1-IMAGEM-V2-2026-09-28 — o ensaio mostra o que a imagem nova faria: a instrução colada que saiu da fala e as
      // buscas que o planejador escreveu da fala (UMA gpt-4o-mini). A busca do plano de B-roll entra sem o alinhamento por
      // narração, que no render roda depois deste ponto.
      const planoEnsaio = KINEO1_IMAGEM_V2 && !verbatim ? await planSceneQueries(scenes.map((sc) => ({ voiceover: sc.voiceover ?? '', planQuery: sc.stockSearchQuery ?? null })), contextoDoPlano) : null
      const imagemV2Ensaio = KINEO1_IMAGEM_V2
        ? {
            pasted_brief: briefColado && briefColado.mode !== 'none' ? { mode: briefColado.mode, removed: briefColado.brief.map((l) => l.slice(0, 160)), narration_words: briefColado.narrationWords } : null,
            scene_queries: planoEnsaio ? planoEnsaio.map((pl, i) => ({ scene: i + 1, subject: pl?.subject ?? null, stockable: pl?.stockable ?? null, queries: pl?.queries ?? [] })) : null,
          }
        : {}
      return NextResponse.json({ ...imagemV2Ensaio, dry_run: true, family: 'fast', engine: 'fast', gate: portao, verbatim: ownScript /* KINEO1-VERBATIM-ESTICA: o relatório diz a mesma coisa que o render */, refunded: true, words_per_scene: verbatim ? null : wordsPerSceneFor(duration, clipCount), ...fastReport, ...(vereditoDoPortao ? { verdict: vereditoDoPortao, pass: false, problems: [vereditoDoPortao, ...(fastReport.problems ?? [])] } : {}) })
    }

    // KINEO-AI-HOOK — FIRST-VIDEO cinematic opener.
    // A new user decides in the first seconds whether Kineo is "AI magic" or
    // just stock clips. For a FREE account's very FIRST video we fire ONE
    // Seedance 5s 9:16 opener and submit it HERE — so it renders in parallel
    // with the Pixabay/vault resolution below — then await it with a bounded
    // budget. Every step is fail-open: on any miss the normal stock hook stands
    // and the Fast video proceeds exactly as it does today.
    let aiHookHandle: AiHookHandle | null = null
    // KINEO-PRIMEIRO-FILME-COM-STILLS-2026-09-16 — o mesmo sinal do hook (primeiro filme + conta gratuita) decide
    // abaixo se TODA cena ganha um still gerado. Falha fechada: sem sinal, nada muda.
    let primeiroFilmeDaConta = false
    // ═══ KINEO1-FILME-DESENHADO-2026-09-21 — o Kineo 1 passa a DESENHAR quando pedem desenho ═══
    // Caso jonathanschwapp (21/09 16:52Z, nota 65): pedido em francês de "animation 3D colorée… maison en carton…
    // facteur" chegou pelo auto-start (activation_autostart_dispatched, motor 'fast', sem tela de escolha, sem aviso).
    // Os 3 clipes Seedance eram a casa de papelão e o carteiro; o banco pôs criança na neve, lago, raio-X e vinil.
    // Regra: pedido de desenho (lib/cinematic/sceneStyle, 16 línguas) → TODA cena nasce de still no look pedido,
    // os clipes gerados entram sempre (até 3) no mesmo look, e o banco NÃO entra na cena que já tem visual gerado.
    // Custo ≈ 7 stills × US$ 0,026 + 3 clipes × US$ 0,13 = US$ 0,57 — dentro do teto de 0,5 acima do filme comum.
    const filmeDesenhado = looksLikeDrawnRequest(prompt)
    const desenhoLook = filmeDesenhado ? deriveStyleAnchor(prompt) : null
    if (filmeDesenhado) console.log(`[filme-desenhado] look=${desenhoLook?.look} — banco de stock fora das cenas geradas`)
    try {
      // Toggle + provider gate are also enforced inside submitAiHook; checking
      // here first avoids two DB round-trips when the feature is off.
      if (process.env.FAST_AI_HOOK !== 'false' && process.env.FAL_KEY) {
        // FIRST-VIDEO signal — the SAME query the activation cron uses to decide
        // "has this account ever generated a video?" (app/api/cron/
        // send-activation-nudge). Zero rows in `videos` = this is video #1. On a
        // query error we conservatively DON'T fire (protects the one-per-account
        // cost guard). RLS scopes both reads to the current user.
        const { count: priorVideos, error: priorErr } = await supabase
          .from('videos')
          .select('id', { count: 'exact', head: true })
          .eq('user_id', user.id)
        const isFirstVideo = !priorErr && (priorVideos ?? 0) === 0

        // FREE-TIER signal — mirror generate-video-cinematic's paid-user gate.
        const { data: hookProfile } = await supabase
          .from('profiles')
          .select('plan, has_paid')
          .eq('id', user.id)
          .maybeSingle()
        const isFreeTier =
          hookProfile?.has_paid !== true &&
          !AI_HOOK_PAID_PLANS.has(String(hookProfile?.plan ?? 'free').toLowerCase())
        primeiroFilmeDaConta = isFirstVideo && isFreeTier && FIRST_FILM_STILLS_ENABLED

        // ═══ KINEO-CLIPES-PARA-PAGANTE-2026-09-21 — "desliga as fotos e estende os clipes" ═══
        // Antes: 3 clipes Seedance de 5 s (US$ 0,39) só no PRIMEIRO filme de conta gratuita (17/09). Medido 17-21/09:
        // 39 filmes, 115/117 clipes prontos (98%), espera média 19 s. Agora: 1º filme de QUALQUER conta (o 1º filme é
        // o produto) + TODO Kineo 1 de conta paga (5 cr ≈ US$ 0,62-0,83 de receita contra ~US$ 0,39 de clipes).
        // Filmes seguintes de conta gratuita continuam só com banco — o trial não paga por IA em cada tentativa.
        const isPaidAccount = !isFreeTier
        const clipesElegiveis = isFirstVideo || isPaidAccount || filmeDesenhado // KINEO1-FILME-DESENHADO: desenho sempre leva clipe gerado

        if (clipesElegiveis) {
          // Build the cinematic prompt from scene 1's description (the visual
          // hook), topic = the user's prompt. Faceless/era-safe by construction.
          const hookPrompt = buildHookPrompt(scenes[0]?.description ?? prompt, prompt, desenhoLook)
          aiHookHandle = await submitAiHook(hookPrompt)
          console.log(
            `[ai-hook] eligible (${isFirstVideo ? 'first-video' : 'paid-account'}) — submit ${aiHookHandle ? 'OK request=' + aiHookHandle.requestId : 'skipped/failed'}`,
          )
        } else {
          console.log(
            `[ai-hook] not eligible (firstVideo=${isFirstVideo} paid=${isPaidAccount}) — normal stock hook`,
          )
        }
      }
    } catch (err) {
      // Any failure here must never affect the video — drop the hook silently.
      console.warn('[ai-hook] eligibility/submit failed (non-blocking):', err instanceof Error ? err.message : String(err))
      aiHookHandle = null
    }

    // Step 2 — Resolve each scene to a clip URL.
    //
    // Push #215 — Removed STOCKLIB_PRIORITY mode (Push #213/214).
    // Root cause: ALL Pexels CDN URLs (videos.pexels.com/video-files/...) return
    // HTTP 403 when Creatomate fetches them server-side. NASA SVS also 403s.
    // The only stockLibrary URLs that work server-side are Cloudinary demo.
    // Priority mode was forcing broken URLs → always 403 for rocket topics.
    //
    // Fix: always try Pexels API first (PEXELS_API_KEY must be set in Vercel
    // for this to return real results). The visual category + slug filter from
    // Push #212 (pexels.ts) still applies to reject abstract/wrong footage.
    // Fallback: stockLibrary (Cloudinary demo clips — wrong content but renders).

    // Push #295 — switched from Promise.all to sequential to enable cross-scene
    // deduplication. Two bugs fixed here:
    //
    // Bug 1 (wrong clips): libQuery was built from visualCategory name
    // (e.g. "general documentary") instead of the GPT-generated stockSearchQuery
    // (e.g. "Nazi soldiers WW2 Europe invasion"). Fixed: stockSearchQuery is now
    // the primary source, with searchKeywords and description as fallbacks.
    //
    // Bug 2 (repeated clips): Promise.all ran all Pexels fetches concurrently
    // with no dedup — the same top-ranking URL came back for similar queries.
    // Fixed: usedPexelsUrls Set tracks every raw Pexels URL already assigned;
    // if a duplicate is returned we skip Pexels and use stockLibrary instead
    // (which uses idx as a seed, so each scene gets a different library clip).
    // Push #486 — build the scene→plan alignment ONCE, before the clip loop.
    // alignedMeta[idx] replaces the old brollSceneMap.get(idx+1) lookup.
    const alignedMeta: (BrollSceneMeta | undefined)[] = new Array(scenes.length).fill(undefined)
    if (!verbatim && brollSceneMap.size > 0) {
      const planEntries = Array.from(brollSceneMap.entries()).sort((a, b) => a[0] - b[0])
      const planTokens = planEntries.map(([, m]) => alignTokens(m.narration ?? ''))
      const haveNarration = planTokens.some((t) => t.size > 0)
      const sameCount = planEntries.length === scenes.length
      const taken = new Set<number>()
      console.log(
        `[broll-align] plan=${planEntries.length} scenes=${scenes.length} narration=${haveNarration} mode=${sameCount ? 'direct-1:1' : haveNarration ? 'content' : 'proportional'}`,
      )
      for (let i = 0; i < scenes.length; i++) {
        let chosen = -1
        let bestScore = 0
        let method = 'index'
        // Happy path: when the plan and the route agree on scene count, keep the
        // direct 1:1 mapping — content matching only runs when counts DIFFER.
        if (!sameCount && haveNarration) {
          const sceneTok = alignTokens(
            `${scenes[i].voiceover ?? ''} ${scenes[i].description ?? ''}`,
          )
          // Require meaningful overlap; below the threshold positional mapping
          // is safer than a weak content match. Small penalty on plan scenes
          // already taken so distinct route scenes spread across the plan.
          let best = 0.3
          for (let j = 0; j < planEntries.length; j++) {
            const score = alignOverlap(sceneTok, planTokens[j]) - (taken.has(j) ? 0.15 : 0)
            if (score > best) {
              best = score
              chosen = j
            }
          }
          if (chosen !== -1) {
            method = 'content'
            bestScore = best
          }
        }
        if (chosen === -1) {
          // Positional fallback: identical to legacy behavior when counts match,
          // proportional (relative position, no off-by-one drift) when they differ.
          chosen = sameCount
            ? i
            : scenes.length > 1
              ? Math.round((i * (planEntries.length - 1)) / (scenes.length - 1))
              : 0
          method = sameCount ? 'index' : 'proportional'
        }
        if (chosen >= 0 && chosen < planEntries.length) {
          taken.add(chosen)
          alignedMeta[i] = planEntries[chosen][1]
          console.log(
            `[broll-align] scene ${i + 1} ↔ plan ${planEntries[chosen][0]} (score ${bestScore.toFixed(2)}, ${method})`,
          )
        }
      }
    }

    // ═══ KINEO1-IMAGEM-V2-2026-09-28 — as buscas nascem da FALA: UMA chamada antes do laço, falha aberta ═══
    // Taxonomia (136 cenas reprovadas, 40 filmes nota 40, 21-27/09): 36 com a busca errada para a fala — o roteiro
    // próprio buscava as 4 primeiras palavras do bloco ("long before people played" → Long Beach; "news seconds launched
    // tts" → borboleta), o plano trazia marcos inventados ("space needle, brainstorming, skyline" para os ovos do Bezos).
    // planSceneQueries dá, por cena, o sujeito filmável, 3 buscas sem nome próprio nem plano de câmera, se o banco tem o
    // assunto (stockable) e o prompt de IA; null → as buscas de hoje. Marcadores [Pexels:] são do autor: a busca dele é
    // soberana (12/06) e o portão fica o de hoje.
    const imagemV2 = KINEO1_IMAGEM_V2 && !verbatim
    const planoCenas: Array<SceneQueryPlan | null> = imagemV2 ? ((await planSceneQueries(scenes.map((sc, i) => ({ voiceover: sc.voiceover ?? '', planQuery: alignedMeta[i]?.pexelsQuery ?? sc.stockSearchQuery ?? null })), contextoDoPlano)) ?? []) : []
    if (imagemV2) console.log(`[imagem-v2] plano de buscas: ${planoCenas.length > 0 ? `${planoCenas.filter(Boolean).length}/${scenes.length} cena(s)` : 'falhou — buscas de hoje (fail-open)'}`)
    // Roteiro próprio em prosa: a busca de reserva era fallbackStockQuery (as 4 primeiras palavras do bloco); com o plano,
    // é a do plano. A fala do autor não muda uma letra.
    if (prosaVerbatim) scenes.forEach((sc, i) => { const qs = planoCenas[i]?.queries ?? []; if (qs.length > 0) { sc.stockSearchQuery = qs[0]; sc.searchKeywords = qs.join(' ') } })
    // Duração provável do filme (o compose mede o áudio): a fala no ritmo da voz, +10%, com o piso de 61,5 s do TIKTOK-61
    // — é o que decide se a fatia do clipe de IA pode reentrar na volta de reciclagem (planAiClipForSlot).
    const filmeEstimadoS = Math.min(90, Math.max(duration >= 60 ? 61.5 : 0, Math.max(duration, (ownScript ? falaPropria : scenes.map((sc) => sc.voiceover ?? '').join(' ')).split(/\s+/).filter(Boolean).length / Math.max(0.5, fastRate.wordsPerSecond)) * 1.1))

    const usedPexelsUrls = new Set<string>()
    const clipUrls: string[] = []
    // KINEO-FAST-CINEMA-2026-07-10 — per-video style memory. Every picked clip
    // deposits its cinematic style tags (aerial/night/fog/...) here; later
    // scenes get a ranking bonus for matching them, so one video keeps ONE
    // consistent look (the AI Gen signature) instead of a stock patchwork.
    const styleCtx = { tags: new Set<string>() }
    // Push #355 — track B-roll source per scene for quality metrics.
    // KINEO-USER-FOOTAGE-2026-07-10 — 'user' = the user's own uploaded clip.
    type ClipSource = 'pixabay' | 'fallbackA' | 'stockLibrary' | 'none' | 'user' | 'aiHook' | 'aiStill'
    const clipSources: ClipSource[] = []
    // KINEO-1-HIBRIDO-2026-09-16 — stills gerados neste filme (teto por filme) e seed estável.
    let aiStillsUsed = 0
    let aiStillsMax = fastAiScenesMax()
    const aiStillSeed = fastStillSeed(prompt)
    // KINEO-HISTORIA-COM-PERSONAGENS-2026-09-16 — "Johny's cookie heist" virou um panda: história com personagem
    // nomeado é cena que o stock não cobre. Toda cena ABRE com still (lib/fastAiScene.ts).
    // KINEO1-VIDEO-NAO-FOTO-2026-09-17 — o detector lê SÓ as falas (o prompt do Kineo 1 já é o roteiro com as
    // falas; somar os dois contava cada palavra em dobro e "Faster. Wilder. Boundless." virou personagem).
    // Sem fala nenhuma (roteiro cru), cai no prompt.
    const falas = scenes.map((sc) => sc.voiceover ?? '').join(' ').trim()
    const personagem = characterStoryName(falas || prompt, { v2: KINEO1_IMAGEM_V2 }) // KINEO1-IMAGEM-V2: Google/Earth/Moon/France não são personagem (46 de 61 filmes, 19-27/09)
    if (personagem || filmeDesenhado) aiStillsMax = Math.max(aiStillsMax, Math.min(scenes.length, CHARACTER_STORY_MAX_STILLS)) // KINEO1-FILME-DESENHADO: toda cena desenhada
    // KINEO-PRIMEIRO-FILME-COM-STILLS — desligado por padrão desde 17/09 (fundador: "era VÍDEO que era para ser
    // melhor"); só entra com KINEO_FIRST_FILM_STILLS=on.
    if (primeiroFilmeDaConta) aiStillsMax = Math.max(aiStillsMax, Math.min(scenes.length, FIRST_FILM_MAX_STILLS))
    // KINEO1-PRIMEIRO-FILME-VIDEO-2026-09-17 — primeiro filme de conta gratuita (o mesmo sinal do hook, já
    // submetido acima): as cenas mais FRACAS do plano ganham um clipe Seedance de 5 s, VÍDEO, não foto
    // (fundador 17/09: "um pedaço de Seedance nas cenas fracas… max 0.5 teto"). Só submete — quem espera é o
    // /api/compose, onde o tempo do TTS/Whisper já existe (a rota esperava 15 s e a Seedance leva 60-120 s:
    // 0 de 142 hooks chegaram em 12 dias). Os stills do híbrido ficam em 3 para o filme caber no teto.
    // Falha aberta: sem request, a cena fica no stock de sempre.
    const aiClipsSubmitted: Array<{ scene: number; requestId: string; prompt: string; usd?: number; seconds?: number; replaceRaw?: number }> = []
    const primeiroFilmeComClipes = !!aiHookHandle && FIRST_FILM_AI_CLIPS_ENABLED
    // KINEO1-IMAGEM-V2-2026-09-28 — com a imagem nova, os clipes das cenas fracas saem DENTRO do laço, depois da busca
    // (fecharCenaV2, abaixo). O desenho segue o caminho de 21/09 (todo o filme é gerado e os clipes abrem a cena), e o
    // roteiro com [Pexels:] também (a busca é do autor; a cena fraca não é medida com o portão v2).
    const clipesNaCenaFraca = imagemV2 && primeiroFilmeComClipes && !filmeDesenhado
    if (primeiroFilmeComClipes) {
      // KINEO1-FILME-DESENHADO: desenho mantém still em toda cena. KINEO1-FICCAO-STOCK-EXATO-2026-09-22: história com
      // personagem sobe o teto para 6 (a Emily ficou com stills só nas cenas 1-3; as cenas 4-6 eram só banco) — +US$ 0,08.
      if (!filmeDesenhado) aiStillsMax = Math.min(aiStillsMax, personagem ? CHARACTER_STORY_STILLS_WITH_CLIPS_MAX : FIRST_FILM_STILLS_WITH_CLIPS_MAX)
      const extras = Math.max(0, firstFilmAiClipCount(FIRST_FILM_STILLS_WITH_CLIPS_MAX) - 1)
      const notas = scenes.map((_, i) => ({ scene: i + 1, relevance: typeof alignedMeta[i]?.relevanceScore === 'number' ? (alignedMeta[i]?.relevanceScore as number) : null }))
      for (const sceneNo of pickWeakScenes(notas, clipesNaCenaFraca ? 0 : extras)) { // KINEO1-IMAGEM-V2: 0 = a escolha é depois da busca
        const sc = scenes[sceneNo - 1]
        const clipPrompt = buildSceneClipPrompt(sc?.description ?? '', sc?.voiceover ?? '', alignedMeta[sceneNo - 1]?.pexelsQuery ?? sc?.stockSearchQuery ?? '', desenhoLook)
        const requestId = await submitSceneClip(clipPrompt)
        if (requestId) aiClipsSubmitted.push({ scene: sceneNo, requestId, prompt: clipPrompt })
        console.log(`[ai-clips] scene=${sceneNo} relevance=${notas[sceneNo - 1]?.relevance ?? 'n/a'} submit ${requestId ? 'OK request=' + requestId : 'skipped/failed'}`)
      }
    }
    // KINEO1-MUNDO-DA-ENTIDADE-2026-09-17 — fundador, olhando o primeiro filme com Seedance ("5 shocking facts
    // about Jeff Bezos"): "muitas cenas que a gente já realizou… quanto mais chegar com vídeos próximos a ele,
    // melhor". No rastro: cenas 2 e 3 com o MESMO "stock market graph"; cena 1 com call center/laptop do cofre
    // para "armazém com robôs". Três regras de custo zero: (1) cena que já tem visual gerado (still ou clipe
    // Seedance) leva UM clipe de stock, não 2-3 — o que é específico ganha tempo de tela; (2) filme sobre
    // entidade nomeada não usa o cofre (clipes de OUTROS vídeos da casa = "os que a gente já realizou"); (3) dedupe
    // por assinatura de tags, não só por URL (o mesmo gráfico com outra URL é o mesmo gráfico para quem vê).
    const cenasComClipeIA = new Set<number>([...(primeiroFilmeComClipes ? [1] : []), ...aiClipsSubmitted.map((c) => c.scene)])
    const filmeDeEntidade = !!personagem || filmeDesenhado // KINEO1-FILME-DESENHADO: desenho não puxa do cofre
    const usedTagSigs = new Set<string>()
    const usedQueriesNoFilme = new Set<string>() // KINEO1-BUSCA-DA-FALA-2026-09-18 — a mesma busca não abre duas cenas
    const tagSig = (tags: string | null | undefined) => (tags ?? '').toLowerCase().split(',').map((t) => t.trim()).filter(Boolean).sort().join('|')
    const aiStillLog: Array<{ scene: number; reason: string; entity: string | null; ok: boolean }> = []
    // KINEO-1-COERENCIA-2026-09-16 — evidência por cena (fala · busca · origem · tags) para o juiz de coerência.
    const sceneEvidence: FastSceneEvidence[] = []
    const tentarStill = async (sceneNo: number, reason: string, entity: string | null, description: string, voiceover: string, query: string): Promise<string | null> => {
      if (aiStillsUsed >= aiStillsMax) return null
      // KINEO-1-HIBRIDO-R2 — seed varia por tentativa (a 2ª imagem da mesma cena não repete a 1ª).
      const still = await generateFastSceneStill({ prompt: buildFastStillPrompt({ description, voiceover, query, entity, look: desenhoLook }), seed: aiStillSeed + sceneNo * 7 + aiStillsUsed * 101, aspect, look: desenhoLook }) // KINEO1-FILME-DESENHADO
      aiStillLog.push({ scene: sceneNo, reason, entity, ok: !!still })
      if (still) aiStillsUsed++
      console.log(`[clip] scene=${sceneNo} KINEO-1-HIBRIDO reason=${reason}${entity ? ` entity="${entity}"` : ''} still=${still ? 'OK' : 'miss (fail-open)'}`)
      return still
    }

    // ═══ KINEO1-IMAGEM-V2-2026-09-28 — cena fraca DEPOIS da busca; o clipe de IA sai DENTRO do laço e TROCA o stock ═══
    // Na amostra (30 filmes com clipe, 21-27/09), 38 das 103 cenas reprovadas JÁ tinham clipe Seedance pronto: ele era
    // escolhido ANTES da busca (pela relevância do plano) e entrava na frente do stock, que continuava tocando e sendo
    // julgado. Agora cada cena é fechada logo depois da sua busca — no topo da cena seguinte e depois da última, então
    // nenhum `continue` escapa: fraca = o banco não deu nada (reciclado/biblioteca), o assunto não é filmável
    // (stockable=false), só o cofre serviu, ou a cabeça do sujeito não é tag exata do clipe (weakSceneReason). Cena fraca
    // elegível pede o clipe NA HORA (a espera p90 da Seedance já é 54 s dos 60 s do compose), fica com UM stock e o evento
    // pendente leva replace_index: pronto, o clipe TROCA esse stock; não pronto (5%: 194 de 204 prontos desde 21/09), o
    // stock fica. A duração vem de planAiClipForSlot: cobre a fatia do montador sem laço, inclusive na volta de
    // reciclagem; quando o teto não paga essa duração, a cena fica no stock (KINEO1-SEM-LACO-2026-09-28: o recuo antigo
    // para a inserção de 5 s relia o arquivo em laço). Nunca passa de KINEO1_AI_WEAK_CLIPS_MAX clipes nem de
    // KINEO1_AI_BUDGET_USD por filme. O stock que a troca tira não volta em outra cena (stockTrocado, abaixo).
    type CenaV2 = { idx: number; vault: number; report: ScenePoolReport | null; skip: 'gap' | 'extension' | null; queries: string[] }
    let cenaV2: CenaV2 | null = null
    const reservaStillsUsd = Math.round(aiStillsMax * FIRST_FILM_STILL_USD * 1000) / 1000 // os stills do híbrido que ainda podem sair
    let gastoIaUsd = primeiroFilmeComClipes ? SEEDANCE_720P_5S_USD : 0 // o hook da cena 1
    const mantidos = (urls: string[]) => urls.filter((u) => typeof u === 'string' && u.length > 0 && !/^https:\/\/([a-z0-9-]+\.)*fal\.(media|run|ai)\//i.test(u)).length
    // KINEO1-SEM-LACO-2026-09-28 (FIX-REVISAO-2) — o stock que um clipe de IA vai TROCAR sai do filme: a revisão 2 provou
    // (cena 2 fraca trocada, cena 3 um vão < 3 s) que o vão copiava clipUrls[último] = aquele stock, e o chafariz de Paris
    // julgado errado para o hambúrguer tocava logo depois do clipe que o substituiu. Vão, extensão e reciclagem (#352)
    // escolhem entre os clipes que ficam. Sem troca no filme, o conjunto é vazio e tudo é como antes.
    const stockTrocado = new Set<string>()
    const semTrocados = (urls: string[]) => (stockTrocado.size === 0 ? urls : urls.filter((u) => !stockTrocado.has(u)))
    const fecharCenaV2 = async (): Promise<void> => {
      const c = cenaV2
      cenaV2 = null
      if (!c) return
      const ev = sceneEvidence[c.idx]
      if (!ev) return
      try {
        const sceneNo = c.idx + 1
        const plano = planoCenas[c.idx] ?? null
        const fontes = clipSources.slice(ev.from)
        const iStock = fontes.findIndex((f) => f !== 'aiStill')
        const rawStock = iStock >= 0 ? ev.from + iStock : -1
        const pixMantidos = fontes.filter((f) => f === 'pixabay').length - c.vault
        const origem: StockOrigin | 'still' | 'user' | 'gap' | 'extension' =
          c.skip ? c.skip
          : fontes.includes('user') ? 'user'
          : iStock < 0 ? 'still'
          : fontes[iStock] === 'fallbackA' ? 'recycled'
          : fontes[iStock] === 'stockLibrary' ? 'library'
          : fontes[iStock] === 'none' ? 'none'
          : c.vault > 0 && pixMantidos <= 0 ? 'vault'
          : c.report?.origin === 'chain' ? 'chain'
          : 'pool'
        const tagsDoStock = rawStock >= 0 ? pixabayTagsForUrl(clipUrls[rawStock]) : null
        const fraca = origem === 'still' || origem === 'user' || origem === 'gap' || origem === 'extension'
          ? null
          : weakSceneReason({ origin: origem, stockable: plano?.stockable ?? null, subject: plano?.subject ?? null, pickedTags: tagsDoStock })
        ev.queries = c.queries.slice(0, 8)
        ev.origin = origem
        ev.stock_origin = origem
        ev.candidates = c.report?.candidates ?? []
        ev.subject = plano?.subject ?? null
        ev.stockable = plano?.stockable ?? null
        ev.weak = fraca
        if (!fraca) return
        if (!clipesNaCenaFraca) { ev.ai_clip = { skipped: primeiroFilmeComClipes ? 'drawn_film' : 'not_eligible' }; return } // desenho: clipes antes do laço (21/09)
        if (sceneNo === 1) { ev.ai_clip = { skipped: 'hook_scene' }; return } // o hook já abre a cena 1
        if (aiClipsSubmitted.length >= KINEO1_AI_WEAK_CLIPS_MAX) { ev.ai_clip = { skipped: 'cap' }; return }
        const livreUsd = Math.round((KINEO1_AI_BUDGET_USD - gastoIaUsd - reservaStillsUsd) * 1000) / 1000
        const podeTrocar = rawStock >= 0 && mantidos([clipUrls[rawStock]]) === 1
        // KINEO1-SEM-LACO-2026-09-28 (FIX-REVISAO-2) — nenhum clipe de IA que o montador leria em laço (SEM QUADRO
        // REPETIDO). Troca: a duração que cobre a pior reentrada; se o teto não a paga (fits=false), a cena fica no stock —
        // o recuo antigo comprava 5 s para uma fatia que reentrava (revisão 2: cena 3 reciclada do filme de 60 s, 11 s
        // necessários, US$ 0,144 livres → o clipe de 5 s relido de 3,3 s a 5,96 s, loop:true). Inserção (o stock da cena
        // não é mantido): só quando a posição do clipe inserido nunca reentra — aí 5 s cobrem a fatia.
        const plan = podeTrocar
          ? planAiClipForSlot({ filmSeconds: filmeEstimadoS, clipCount: mantidos(clipUrls.slice(0, rawStock + 1)) + (scenes.length - sceneNo), index: mantidos(clipUrls.slice(0, rawStock)), maxUsd: livreUsd })
          : { mode: 'insert' as const, seconds: 5, usd: SEEDANCE_720P_5S_USD, fits: true, reentries: planAiClipForSlot({ filmSeconds: filmeEstimadoS, clipCount: mantidos(clipUrls.slice(0, rawStock + 1)) + 1 + (scenes.length - sceneNo), index: mantidos(clipUrls.slice(0, ev.from)) }).reentries }
        if (plan.mode === 'insert' && plan.reentries > 0) {
          ev.ai_clip = { skipped: 'insert_loop' }
          console.log(`[ai-clips] v2 scene=${sceneNo} reason=${fraca} inserção de 5 s reentraria ${plan.reentries}x (laço) — a cena fica como está`)
          return
        }
        if (!plan.fits || plan.usd > livreUsd + 1e-9) {
          ev.ai_clip = { skipped: plan.reentries > 0 ? 'budget_loop' : 'budget' }
          console.log(`[ai-clips] v2 scene=${sceneNo} reason=${fraca} sem orçamento para ${plan.seconds}s sem laço (reentradas ${plan.reentries}, US$${plan.usd}; livre US$${livreUsd}, gasto US$${gastoIaUsd}, teto US$${KINEO1_AI_BUDGET_USD})`)
          return
        }
        const sc = scenes[c.idx]
        const clipPrompt = buildSceneClipPrompt(plano?.aiPrompt || sc?.description || '', sc?.voiceover ?? '', plano?.subject || ev.query || sc?.stockSearchQuery || '', desenhoLook)
        const requestId = await submitSceneClip(clipPrompt, plan.mode === 'replace' ? plan.seconds : undefined)
        console.log(`[ai-clips] v2 scene=${sceneNo} reason=${fraca} origin=${origem} mode=${plan.mode} ${plan.seconds}s US$${plan.usd} (gasto antes US$${gastoIaUsd} de ${KINEO1_AI_BUDGET_USD}) submit ${requestId ? 'OK request=' + requestId : 'skipped/failed'}`)
        if (!requestId) { ev.ai_clip = { skipped: 'submit_failed' }; return }
        gastoIaUsd = Math.round((gastoIaUsd + plan.usd) * 1000) / 1000
        aiClipsSubmitted.push({ scene: sceneNo, requestId, prompt: clipPrompt, usd: plan.usd, ...(plan.mode === 'replace' ? { seconds: plan.seconds, replaceRaw: rawStock } : {}) })
        if (plan.mode === 'replace' && clipUrls[rawStock]) stockTrocado.add(clipUrls[rawStock]) // KINEO1-SEM-LACO: sai do filme
        cenasComClipeIA.add(sceneNo)
        // A cena fraca fica com UM stock (KINEO1-MUNDO-DA-ENTIDADE: o gerado ganha a tela) — na troca, é o que o clipe substitui.
        if (rawStock >= 0) while (clipUrls.length > rawStock + 1) { clipUrls.pop(); clipSources.pop() }
        ev.origin = 'ai'
        ev.ai_clip = { mode: plan.mode, seconds: plan.seconds, usd: plan.usd, reason: fraca }
      } catch (err) {
        console.warn('[imagem-v2] fechar a cena falhou (non-blocking):', err instanceof Error ? err.message : String(err))
      }
    }

    for (let idx = 0; idx < scenes.length; idx++) {
      await fecharCenaV2() // KINEO1-IMAGEM-V2 — a busca da cena anterior terminou: fecha ela ANTES de abrir esta
      const scene = scenes[idx]
      const cat = scene.visualCategory ?? ''
      const sceneNo = idx + 1
      const ev: FastSceneEvidence = { scene: sceneNo, voiceover: (scene.voiceover ?? '').slice(0, 240), query: scene.stockSearchQuery ?? null, from: clipSources.length, sources: [], tags: [] } // KINEO-1-COERENCIA
      sceneEvidence.push(ev)
      if (imagemV2) cenaV2 = { idx, vault: 0, report: null, skip: null, queries: [] } // KINEO1-IMAGEM-V2

      // Push #349 — pull this scene's BrollPlan metadata (1-based sceneNumber).
      // Hotfix (12/06): in VERBATIM mode the user hand-picked a [Pexels: ...]
      // query for every scene — the BrollPlan (built by splitting the marked
      // text its own way, so scene numbers don't even align) must NEVER
      // override them. Joseph's gift video #1: "private jet interior luxury"
      // was replaced by a plan query that returned coins-on-dollar-bills.
      // Push #486 — content-aligned plan meta (was: brollSceneMap.get(sceneNo),
      // an index lookup that shifted every query when plan/scene counts differ).
      const brollMeta = verbatim ? undefined : alignedMeta[idx]

      // KINEO-USER-FOOTAGE-2026-07-10 (Prioridade 2, cliente $200/mês) — the
      // user's OWN clip pinned to this scene beats EVERYTHING: no vault, no
      // Pixabay, no fallback. URL was validated against our user-footage
      // bucket prefix at parse time. Scenes without user footage fall through
      // to the normal hierarchy (the "Pexels fills the gaps" MVP contract).
      if (brollMeta?.userFootageUrl) {
        clipUrls.push(brollMeta.userFootageUrl)
        clipSources.push('user')
        console.log(
          `[clip] scene=${sceneNo} source=USER-FOOTAGE url=${brollMeta.userFootageUrl.slice(0, 80)}`,
        )
        continue
      }

      // v3.0 Phase 1: if a BrollPlan provided a specific AI-directed pexelsQuery
      // for this scene, use it as the primary search — it's far more specific
      // (e.g. "Wall Street trading floor 1987 crash") than GPT's generic scene
      // description.
      const brollOverride = verbatim ? undefined : brollMeta?.pexelsQuery
      const relevanceScore = brollMeta?.relevanceScore
      const purpose = (brollMeta?.scenePurpose ?? scene.scenePurpose ?? '').toString()
      const durationSeconds = brollMeta?.durationSeconds
      const scoreLabel = typeof relevanceScore === 'number' ? String(relevanceScore) : 'n/a'
      const durLabel = typeof durationSeconds === 'number' ? `${durationSeconds}` : '?'

      // Push #350 — requiresExtension: true means the AI Visual Director found no
      // safe Pexels query for this scene (blacklisted topic). Skip the Pexels search
      // entirely and go straight to FALLBACK-A (extend the previous relevant clip).
      if (brollMeta?.requiresExtension && clipUrls.length > 0) {
        const extUrl = findPreviousRelevantClip(semTrocados(clipUrls), usedPexelsUrls, idx) // KINEO1-SEM-LACO: sem o stock trocado
        if (extUrl) {
          if (cenaV2) cenaV2.skip = 'extension' // KINEO1-IMAGEM-V2: o plano não achou busca segura — não é cena fraca de busca
          clipUrls.push(extUrl)
          clipSources.push('fallbackA') // #355
          console.log(
            `[clip] scene=${sceneNo} purpose=${purpose} duration=${durLabel}s source=FALLBACK-A(requiresExtension) score=${scoreLabel} url=${extUrl.slice(0, 60)}`,
          )
          continue
        }
        // No prior relevant clip — fall through to normal search (will likely
        console.log(`[clip] scene=${sceneNo} requiresExtension=true but no prior relevant clip — continuing to normal search`)
      }

      // Push #349 — Timeline balancing. A tiny trailing gap (<3s) isn't worth a
      // fresh Pexels search (and a brand-new clip flashing for under 3 seconds
      // looks jarring) — just extend whatever clip preceded it so the timeline
      // stays full and visually coherent. Only fires when we know the planned
      // duration (BrollPlan metadata present) and there is a prior clip.
      // KINEO1-SEM-LACO-2026-09-28 — o vão copia o último clipe que FICA no filme (nunca o stock que um clipe de IA troca);
      // sem nenhum, a cena segue para a busca normal. Sem troca no filme, é o último clipe, como antes.
      const clipesQueFicam = semTrocados(clipUrls)
      if (typeof durationSeconds === 'number' && durationSeconds < 3 && clipesQueFicam.length > 0) {
        if (cenaV2) cenaV2.skip = 'gap' // KINEO1-IMAGEM-V2: vão < 3 s, sem busca — nunca ganha clipe de IA
        const prevUrl = clipesQueFicam[clipesQueFicam.length - 1]
        clipUrls.push(prevUrl)
        clipSources.push('fallbackA') // #355
        console.log(
          `[clip] scene=${sceneNo} purpose=${purpose} duration=${durLabel}s query="(gap)" source=FALLBACK-A score=${scoreLabel} GAP<3s url=${prevUrl.slice(0, 60)}`,
        )
        continue
      }

      // Bug 1 fix (#295): prefer GPT's specific stockSearchQuery over the generic
      // visual category name. Falls back to searchKeywords, then description.
      // v3.0: BrollPlan override takes priority over all other sources.
      const libQuery = brollOverride ||
        scene.stockSearchQuery ||
        scene.searchKeywords ||
        (cat && cat !== 'general_documentary' ? cat.replace(/_/g, ' ') : scene.description)

      // Final fallback: stockLibrary (Cloudinary demo — always server-accessible)
      // In verbatim mode the user's own query routes the fallback too, so even
      // the safety net stays on-topic.
      // Push #350 — if this scene has no people/lifestyle vocabulary, filter out
      // any stock clips that carry people/lifestyle tags so a random portrait
      // clip never lands as the fallback for mystery/history/finance content.
      const PEOPLE_STOCK_TAGS = new Set(['lifestyle', 'people', 'person', 'portrait', 'fashion', 'celebrity'])
      const hasPeopleVocab = sceneHasPeopleVocabulary(
        scene.voiceover ?? '',
        scene.description ?? '',
        scene.searchKeywords ?? '',
      )
      let libCandidates: LibraryClip[] = pickLibraryClips(verbatim ? scene.stockSearchQuery : libQuery, 4, idx)
      if (!hasPeopleVocab) {
        const safe = libCandidates.filter((c) => !c.tags.some((t) => PEOPLE_STOCK_TAGS.has(t)))
        if (safe.length > 0) libCandidates = safe
      }
      // Push #437 — never let a finance/money/billionaire scene fall back to an
      // ocean/animal/nature clip (the "school of fish for 'the asset'" bug). Only
      // keep nature clips when the scene actually talks about nature/animals.
      const ANIMAL_NATURE_STOCK_TAGS = new Set(['ocean', 'water', 'sea', 'underwater', 'animal', 'wildlife', 'nature', 'forest'])
      const natureText = `${scene.voiceover ?? ''} ${scene.description ?? ''} ${scene.searchKeywords ?? ''} ${libQuery}`.toLowerCase()
      const sceneIsNature = /\b(ocean|sea|water|wave|fish|animal|wildlife|nature|forest|mountain|river|jungle|reef|whale|shark|bird)\b/.test(natureText)
      if (!sceneIsNature) {
        const safe = libCandidates.filter((c) => !c.tags.some((t) => ANIMAL_NATURE_STOCK_TAGS.has(t)))
        if (safe.length > 0) libCandidates = safe
      }
      const fallbackUrl = libCandidates[0]?.url ?? ''

      // Push #353 — PIXABAY PRIMARY SOURCE.
      // New hierarchy: PIXABAY → FALLBACK-A (cycling #352) → FALLBACK-B (stockLibrary)
      // Toggle: ENABLE_PIXABAY=false falls straight through to FALLBACK-A/B.
      const queryUsed = brollOverride ?? scene.stockSearchQuery ?? libQuery
      const pixabayEnabled = process.env.ENABLE_PIXABAY !== 'false'

      if (pixabayEnabled) {
        // Build ordered query list for Pixabay: BrollPlan multi-query preferred,
        // then single brollOverride, then stockSearchQuery, then libQuery.
        let pixQueries: string[] =
          brollMeta?.pexelsQueries && brollMeta.pexelsQueries.length > 0
            ? brollMeta.pexelsQueries
            : brollOverride
              ? [brollOverride]
              : scene.stockSearchQuery
                ? [scene.stockSearchQuery]
                : libQuery
                  ? [libQuery]
                  : []

        // KINEO1-IMAGEM-V2-2026-09-28 — busca do plano com vírgula ("space needle, brainstorming, skyline") vira só os
        // pedaços que a fala menciona (12,7% das buscas nos filmes nota 40, 1,4% nos 80+); nenhum → a busca da própria cena.
        if (imagemV2 && pixQueries.some((q) => q.includes(','))) {
          const partes = splitCommaQueries(pixQueries, scene.voiceover ?? '')
          pixQueries = partes.length > 0 ? partes : [scene.stockSearchQuery || libQuery].filter((q): q is string => !!q)
        }

        // Fix 03/07 — HOOK ANTI-OFFTOPIC GUARD (scene 1 only). Scene 1 is the
        // visual hook; one off-topic clip there kills the video (the "snow clip
        // on a cave video" bug, 11h20 E2E). If a planned query shares ZERO
        // content tokens with this scene's own text, it's plan misalignment or
        // a hallucinated location — drop it and fall back to the scene's own
        // stockSearchQuery. Other scenes keep the #486 content alignment as-is.
        // KINEO1-BUSCA-DA-FALA-2026-09-18 — a guarda do gancho (só cena 1) passa a valer para TODA cena: query planejada
        // sem NENHUM token do texto da cena é desalinhamento do plano (57% das cenas na amostra de 18/09; −12 de
        // visual). Cai para a busca da própria cena. E uma query já usada em cena anterior vai para o fim da lista:
        // o mesmo "stock market graph" 3× no filme do Bezos e "jaipur neighborhood" 6× no filme hindi.
        if (pixQueries.length > 1 && usedQueriesNoFilme.size > 0) {
          const ineditas = pixQueries.filter((q) => !usedQueriesNoFilme.has(q.trim().toLowerCase()))
          if (ineditas.length > 0 && ineditas.length < pixQueries.length) {
            pixQueries = [...ineditas, ...pixQueries.filter((q) => usedQueriesNoFilme.has(q.trim().toLowerCase()))]
            console.log(`[busca-da-fala] scene=${sceneNo} moved ${pixQueries.length - ineditas.length} already-used query(ies) to the end`)
          }
        }
        if (pixQueries.length > 0) {
          const HOOK_STOP = new Set(['the', 'a', 'an', 'of', 'in', 'on', 'at', 'and', 'or', 'to', 'for', 'with', 'this', 'that', 'is', 'are', 'was', 'were', 'it', 'its', 'from', 'by', 'into', 'over', 'under', 'aerial', 'view', 'shot', 'footage', 'cinematic'])
          const tokensOf = (s: string) =>
            s.toLowerCase().replace(/[^a-z0-9\s]/g, ' ').split(/\s+/).filter((t) => t.length > 2 && !HOOK_STOP.has(t))
          const sceneTokens = new Set(
            tokensOf(`${scene.voiceover ?? ''} ${scene.description ?? ''} ${scene.searchKeywords ?? ''} ${scene.stockSearchQuery ?? ''}`),
          )
          const onTopic = pixQueries.filter((q) => tokensOf(q).some((t) => sceneTokens.has(t)))
          if (onTopic.length < pixQueries.length) {
            console.log(
              `[hook-guard] scene=${sceneNo} dropped ${pixQueries.length - onTopic.length}/${pixQueries.length} off-topic planned queries`,
            )
          }
          if (onTopic.length > 0) {
            pixQueries = onTopic
          } else if (scene.stockSearchQuery || libQuery) {
            // All planned queries off-topic — trust the scene's own text instead.
            pixQueries = [scene.stockSearchQuery || libQuery]
            console.log(`[hook-guard] scene=${sceneNo} all planned queries off-topic — using scene's own query`)
          }
        }

        // KINEO1-IMAGEM-V2-2026-09-28 — as buscas do plano novo (feitas da FALA) vão NA FRENTE; as de hoje depois, sem o plano
        // de câmera; a já usada em outra cena vai para o fim. A guarda do gancho não vale para elas: a fala pode estar em
        // espanhol e a busca é em inglês de propósito (o banco é em inglês).
        if (imagemV2) pixQueries = planFirstQueries(planoCenas[idx]?.queries, pixQueries, usedQueriesNoFilme).slice(0, KINEO1_SCENE_QUERIES_MAX)
        if (cenaV2) cenaV2.queries = [...pixQueries]
        ev.query = pixQueries[0] ?? ev.query // KINEO-1-COERENCIA — a busca que valeu, depois do hook-guard
        if (pixQueries[0]) usedQueriesNoFilme.add(pixQueries[0].trim().toLowerCase()) // KINEO1-BUSCA-DA-FALA
        // KINEO-1-HIBRIDO — antes de gastar a busca: se o plano, a relevância ou a fala dizem que o banco
        // não tem esta cena (nome próprio, lugar específico), o still entra no lugar do stock. Falha aberta.
        {
          const dec = filmeDesenhado
            ? { ai: true, reason: 'drawn' as const, entity: null }
            : personagem
            ? { ai: true, reason: 'character_story' as const, entity: null }
            : primeiroFilmeDaConta
              ? { ai: true, reason: 'first_film' as const, entity: null }
              : decideFastAiScene({ planSource: brollMeta?.source ?? null, relevanceScore: relevanceScore ?? null, voiceover: scene.voiceover ?? null, description: scene.description ?? null })
          if (dec.ai && dec.reason !== 'pixabay_miss') {
            const still = await tentarStill(sceneNo, dec.reason ?? 'plan_ai', dec.entity, scene.description ?? '', scene.voiceover ?? '', pixQueries[0] ?? scene.stockSearchQuery ?? '')
            if (still) {
              clipUrls.push(still)
              clipSources.push('aiStill')
              cenasComClipeIA.add(sceneNo) // KINEO1-MUNDO-DA-ENTIDADE — a cena já tem visual gerado
              // KINEO1-FILME-DESENHADO-2026-09-21 — pedido de DESENHO: o banco de filmagem real nunca é a cena certa
              // (criança na neve, lago, raio-X e vinil no filme do carteiro). Com o still desenhado na mão, a cena
              // fecha aqui; se o still falhar (fail-open, abaixo), o stock ainda entra — cena vazia é pior.
              if (filmeDesenhado) continue
              // KINEO-HISTORIA-COM-PERSONAGENS (16/09) excluía o stock da cena com `continue` — e o filme inteiro
              // virava slideshow (bekeecomedytv, 17/09 02:48Z: 7 fotos, 0 clipe). KINEO1-VIDEO-NAO-FOTO-2026-09-17:
              // o still do personagem ABRE a cena e o vídeo de stock segue nos cortes seguintes, como no R2 abaixo.
              // O Kineo 1 é um motor de VÍDEO; foto parada é o que o fundador chamou de "dois clientes a menos".
              // KINEO-1-HIBRIDO-R2 — o still abre a cena e o stock da cena continua sendo buscado para os
              // cortes seguintes (sem `continue`): no render de prova (7b34db47) o filme de 35 s ficou com 5
              // visuais para 10 cortes e repetiu skyline/despertador/caderno. Variedade > pureza.
            }
          }
        }
        if (pixQueries.length > 0) {
          const sceneNeedsPeople = sceneHasPeopleVocabulary(
            scene.voiceover ?? '',
            scene.description ?? '',
            scene.searchKeywords ?? '',
          )
          // Fast Mode v2 (02/07) — ranked mini-pool per scene (strongest clip
          // first, so scene 1's lead clip = the strongest of its whole pool —
          // the visual hook). Near the total cap we drop back to 1 clip/scene.
          // KINEO-FAST-CINEMA (10/07) — the HOOK scene gets 3 clips instead of
          // 2: faster cuts in the first seconds is the AI Gen retention
          // signature, and scene 1 is where a Fast video wins or loses the
          // viewer. Same single pool call — just a deeper take from it.
          // KINEO1-MUNDO-DA-ENTIDADE-2026-09-17 — cena com visual gerado (still/Seedance) leva UM stock: o específico ganha tela.
          const perScene = cenasComClipeIA.has(sceneNo) ? 1 : idx === 0 ? FAST_CLIPS_PER_SCENE + 1 : FAST_CLIPS_PER_SCENE
          const clipsWanted = Math.max(
            1,
            Math.min(perScene, FAST_MAX_TOTAL_CLIPS - clipUrls.length),
          )

          // KINEO-FAST-V4 — VAULT FIRST. Clips already curated by past videos
          // (high score at pick time, served from OUR storage) beat a fresh
          // external search: instant, on-brand, Creatomate-safe. Vault misses
          // cost one indexed SQL query (~10ms). Skipped in verbatim mode (the
          // user's hand-picked query deserves a live search).
          let vaultTaken = 0
          // KINEO1-MUNDO-DA-ENTIDADE-2026-09-17 — filme sobre entidade nomeada e cena com visual gerado não
          // puxam do cofre: clipe de OUTRO vídeo da casa é "o que a gente já realizou" (fundador). Busca fresca.
          if (!verbatim && !filmeDeEntidade && !cenasComClipeIA.has(sceneNo)) {
            const vaultHits = await searchVault(pixQueries[0] ?? libQuery ?? '', {
              exclude: usedPexelsUrls,
              limit: clipsWanted,
              ...(imagemV2 ? { v2: true, sceneText: scene.voiceover ?? '', sceneNeedsPeople } : {}), // KINEO1-IMAGEM-V2: o portão do pool, só tags, sem ai-hook
            })
            for (const hit of vaultHits) {
              clipUrls.push(hit.storageUrl)
              usedPexelsUrls.add(hit.storageUrl)
              notePickedClipTags(hit.storageUrl, hit.tags) // KINEO-1-COERENCIA
              { const sig = tagSig(hit.tags); if (sig) usedTagSigs.add(sig) } // KINEO1-MUNDO-DA-ENTIDADE
              clipSources.push('pixabay') // metrics bucket: vault clips originated from pixabay
              vaultTaken++
              if (cenaV2) cenaV2.vault++ // KINEO1-IMAGEM-V2
              console.log(
                `[clip] scene=${sceneNo} purpose=${purpose} duration=${durLabel}s query="${(pixQueries[0] ?? '').slice(0, 50)}" source=VAULT score=${hit.score} url=${hit.storageUrl.slice(0, 60)}`,
              )
            }
            if (vaultTaken >= clipsWanted) continue
          }

          const pixUrls = await getPixabayClipsForScene(
            pixQueries,
            sceneNeedsPeople,
            // PUSH #94 — was `.slice(0, 80)` (~12 words), which fed the concept
            // matcher nothing but the scene's leading filler clause. See
            // buildSceneHint() above.
            buildSceneHint(scene.voiceover ?? ''),
            // (12/06) exact: user-authored [Pexels: ...] queries are sovereign —
            // no concept-map prepending. exclude: never reuse a clip another
            // scene already took (the same-Dubai-aerial-4x bug).
            // Push #483 — minDurationSec: clips long enough to cover the planned
            // scene duration rank higher (kills freeze/loop padding on short clips).
            // KINEO-MULTIFORMATO-2026-09-02 — o ranker precisa saber o quadro:
            // num Short vale +10 para clipe retrato; num 16:9 é o inverso.
            // KINEO1-FICCAO-STOCK-EXATO-2026-09-22 — história com personagem: o banco só entra se a cabeça da busca for tag exata.
            { exact: verbatim, exclude: usedPexelsUrls, minDurationSec: durationSeconds, maxClips: clipsWanted - vaultTaken, ...(imagemV2 ? { v2: true, headFallback: KINEO1_GATE_HEAD_FALLBACK, onReport: (r: ScenePoolReport) => { if (cenaV2) cenaV2.report = r } } : {}), styleCtx, aspect, strictSubject: !!personagem },
          )
          // KINEO1-MUNDO-DA-ENTIDADE-2026-09-17 — dedupe por assinatura de tags: o mesmo gráfico de bolsa com outra
          // URL é o mesmo gráfico para quem vê (cenas 2 e 3 do filme do Bezos). Se todos repetem, fica o primeiro.
          const pixInedito = pixUrls.filter((u) => { const sig = tagSig(pixabayTagsForUrl(u)); return !sig || !usedTagSigs.has(sig) })
          // KINEO1-SUJEITO-2026-09-18 — se TUDO repete e a cena já tem visual gerado (still/Seedance), não entra
          // stock nenhum: o filme do Boeing (salswina, 17/09) recebeu o MESMO trânsito de cidade nas cenas 2 e 3
          // porque o "fica o primeiro" readmitia o repetido. Sem visual gerado, o primeiro ainda fica (cena vazia é pior).
          const pixFinal = pixInedito.length > 0 ? pixInedito : cenasComClipeIA.has(sceneNo) ? [] : pixUrls.slice(0, 1)
          if (pixFinal.length < pixUrls.length) console.log(`[clip] scene=${sceneNo} KINEO1-MUNDO-DA-ENTIDADE dropped ${pixUrls.length - pixFinal.length} clip(s) with tags already on screen`)
          if (pixFinal.length > 0) {
            for (const pixUrl of pixFinal) {
              { const sig = tagSig(pixabayTagsForUrl(pixUrl)); if (sig) usedTagSigs.add(sig) }
              console.log(
                `[clip] scene=${sceneNo} purpose=${purpose} duration=${durLabel}s query="${(pixQueries[0] ?? '').slice(0, 60)}" source=PIXABAY score=${scoreLabel} url=${pixUrl.slice(0, 60)}`,
              )
              clipUrls.push(pixUrl)
              usedPexelsUrls.add(pixUrl) // (12/06) cross-scene dedup
              clipSources.push('pixabay') // #355 — one entry per clip; ratios stay valid
            }
            continue
          }
          // KINEO-FAST-V4 — scene already partially covered by vault clips:
          // that's enough, don't pad it with a fallback repeat.
          if (vaultTaken > 0) continue
          console.log(`[clip] scene=${sceneNo} Pixabay miss — falling through to FALLBACK-A/B`)
          // KINEO-1-HIBRIDO — o banco não achou nada: um still da própria cena vale mais que reciclar
          // o clipe de outra cena (FALLBACK-A, a "foto que deixa a desejar").
          {
            const dec = decideFastAiScene({ voiceover: scene.voiceover ?? null, description: scene.description ?? null, pixabayMiss: true })
            if (dec.ai) {
              const still = await tentarStill(sceneNo, dec.reason ?? 'pixabay_miss', dec.entity, scene.description ?? '', scene.voiceover ?? '', pixQueries[0] ?? '')
              if (still) {
                clipUrls.push(still)
                clipSources.push('aiStill')
                continue
              }
            }
          }
        }
      }

      // FALLBACK-A: cycle through previous valid clips (#352 — intelligent cycling).
      const previousRelevantUrl = findPreviousRelevantClip(semTrocados(clipUrls), usedPexelsUrls, idx) // KINEO1-SEM-LACO: sem o stock trocado

      // FALLBACK-B: stockLibrary (Cloudinary — pre-curated, pre-approved).
      const libUrl = previousRelevantUrl ?? fallbackUrl

      if (libUrl) {
        const fbSource = previousRelevantUrl ? 'FALLBACK-A' : 'FALLBACK-B'
        if (previousRelevantUrl) {
          console.log(`[clip] scene=${sceneNo} FALLBACK-A: cycling to prior clip (#352)`)
          clipSources.push('fallbackA') // #355
        } else {
          console.log(`[clip] scene=${sceneNo} FALLBACK-B: stockLibrary url=${fallbackUrl.slice(0, 60)}`)
          clipSources.push('stockLibrary') // #355
        }
        console.log(
          `[clip] scene=${sceneNo} purpose=${purpose} duration=${durLabel}s query="${(queryUsed ?? '').slice(0, 60)}" source=${fbSource} score=${scoreLabel} url=${libUrl.slice(0, 60)}`,
        )
        clipUrls.push(libUrl)
      } else {
        // Absolute last resort — no prior clip AND no stockLibrary match.
        console.log(
          `[clip] scene=${sceneNo} purpose=${purpose} duration=${durLabel}s source=NONE url=(none)`,
        )
        clipUrls.push('')
        clipSources.push('none') // #355
      }
    }

    await fecharCenaV2() // KINEO1-IMAGEM-V2 — a última cena também é fechada (e pode pedir o seu clipe de IA)

    // KINEO-1-COERENCIA-2026-09-16 — fecha a evidência ANTES do hook (que faz unshift e deslocaria os índices):
    // cada cena recebe as origens e as tags dos clipes que ficaram entre o seu `from` e o `from` da próxima.
    for (let i = 0; i < sceneEvidence.length; i++) {
      const a = sceneEvidence[i].from
      const b = i + 1 < sceneEvidence.length ? sceneEvidence[i + 1].from : clipSources.length
      sceneEvidence[i].sources = clipSources.slice(a, b)
      sceneEvidence[i].tags = clipUrls.slice(a, b).map((u) => pixabayTagsForUrl(u) ?? '').filter(Boolean)
    }

    // KINEO-1-HIBRIDO — rastro de medição: quantas cenas viraram still e por quê (denominador = cenas).
    if (aiStillLog.length > 0) {
      void writeServerEvent({ name: 'fast_ai_still', userId: user.id, path: '/api/generate-video-fast', metadata: { scenes: scenes.length, tried: aiStillLog.length, used: aiStillsUsed, max: aiStillsMax, character: personagem, first_film: primeiroFilmeDaConta, drawn_look: desenhoLook?.look ?? null, log: aiStillLog.slice(0, 12) } })
    }

    // KINEO-AI-HOOK — await + PERSIST the opener, then prepend it as clip 0.
    // awaitAiHook resolves to a raw fal.media URL (which expires, is stripped
    // just below, AND is rejected by /api/compose). persistHookClip copies it
    // into our own public `broll` bucket — the SAME storage the clip vault
    // serves from — and returns a durable Supabase URL that survives the strip
    // and passes Compose. Bounded + fully fail-open: any miss keeps the stock
    // hook and the video proceeds unchanged. The hook is a VISUAL opener only —
    // scenes / scene_captions / voiceover_script are untouched, so it plays
    // under the existing scene-1 hook voiceover and adds no narration.
    // KINEO1-PRIMEIRO-FILME-VIDEO-2026-09-17 — com o interruptor ligado, esta rota NÃO espera mais: o hook e os
    // clipes das cenas fracas viram o evento `fast_ai_clips_pending` (abaixo, depois do generationId) e quem
    // espera é o /api/compose (lib/fastAiClips.ts). Os 15 s daqui nunca bastaram (0 de 142 em 12 dias).
    const deferAiClipsToCompose = primeiroFilmeComClipes
    if (aiHookHandle && !deferAiClipsToCompose) {
      let hookClipUrl: string | null = null
      try {
        const falUrl = await awaitAiHook(aiHookHandle, AI_HOOK_AWAIT_BUDGET_MS, prompt)
        if (falUrl) {
          const durable = await persistHookClip(falUrl)
          // Only accept a durable, non-fal URL (persistHookClip returns null on
          // failure and never returns a fal URL for a fal input).
          if (durable && !/^https:\/\/([a-z0-9-]+\.)*fal\.(media|run|ai)\//i.test(durable)) {
            hookClipUrl = durable
          }
        }
      } catch (err) {
        console.warn('[ai-hook] await/persist failed (non-blocking):', err instanceof Error ? err.message : String(err))
      }
      if (hookClipUrl) {
        // Stay within the total-clip cap: drop the last stock clip if adding the
        // opener would overflow, so the length math downstream stays correct.
        if (clipUrls.length >= FAST_MAX_TOTAL_CLIPS) {
          clipUrls.pop()
          clipSources.pop()
        }
        clipUrls.unshift(hookClipUrl)
        clipSources.unshift('aiHook')
        console.log(`[ai-hook] prepended durable hook as clip 0 → ${hookClipUrl.slice(0, 70)}`)
      }
    }

    // Fast is the free stock-footage path. AI-generated FAL media requires a
    // signed premium generation claim in /api/compose, so it must never leave
    // this route as Fast footage. A legacy first-video Seedance hook violated
    // that contract and caused valid activation renders to fail at Compose.
    // Keep the Compose guard and fail closed here too.
    const filtered = clipUrls.filter(
      (u) =>
        typeof u === 'string' &&
        u.length > 0 &&
        !/^https:\/\/([a-z0-9-]+\.)*fal\.(media|run|ai)\//i.test(u),
    )
    if (filtered.length === 0) {
      // PUSH #96 — this is the dead end where a user gets a hard error after
      // the full scripting + sourcing wait. Record the scene/clip counts so a
      // provider outage is separable from a topic with no usable footage.
      recordFastFailure('generating', 'no_stock_footage_sourced', 502, user.id, {
        scene_count: scenes.length,
        raw_clip_count: clipUrls.length,
      })
      return NextResponse.json(
        { error: 'No stock footage could be sourced. Please try a different topic.' },
        { status: 502 }
      )
    }

    const generationId = randomUUID()

    // KINEO-1-COERENCIA-2026-09-16 — o plano visual cena a cena vira evento (session_id = generationId, o mesmo
    // que o compose grava no claim). Custa um insert; a NOTA é calculada fora do caminho da pessoa (painel).
    if (sceneEvidence.length > 0) {
      await writeServerEvent({
        name: FAST_SCENE_PLAN_EVENT,
        userId: user.id,
        sessionId: generationId,
        path: '/api/generate-video-fast',
        // topic INTEIRO (o teto da caixa é 5.000): videos.topic é cortado em 500 e o juiz precisa do texto real.
        metadata: { generation_id: generationId, topic: prompt.slice(0, 5000), scenes: sceneEvidence.slice(0, 24).map(({ from: _from, ...rest }) => rest), verbatim, ...(KINEO1_IMAGEM_V2 ? { image_v2: { on: imagemV2, plan_ok: planoCenas.length > 0, head_fallback: KINEO1_GATE_HEAD_FALLBACK, pasted_brief: briefColado?.mode ?? null, ai_budget_usd: clipesNaCenaFraca ? KINEO1_AI_BUDGET_USD : null, ai_spent_usd: clipesNaCenaFraca ? Math.round((gastoIaUsd + aiStillsUsed * FIRST_FILM_STILL_USD) * 100) / 100 : null, weak_scenes: sceneEvidence.filter((e) => !!e.weak).map((e) => e.scene) } } : {}) },
      })
    }

    // KINEO1-PRIMEIRO-FILME-VIDEO-2026-09-17 — o que o compose vai esperar: request_id + posição de cada clipe
    // no clip_urls ENTREGUE (índices de `filtered`; o evento de cena guarda `from` sobre o array cru, então a
    // posição é o número de clipes mantidos antes dele). Escrito com await — `void` antes do return morre na
    // Vercel. Só o servidor escreve este evento; o compose o lê pelo generation_id + user_id.
    if (deferAiClipsToCompose && aiHookHandle) {
      const keptBefore = (rawIndex: number) => clipUrls.slice(0, Math.max(0, rawIndex)).filter((u) => typeof u === 'string' && u.length > 0 && !/^https:\/\/([a-z0-9-]+\.)*fal\.(media|run|ai)\//i.test(u)).length
      const clips = [
        { request_id: aiHookHandle.requestId, scene: 1, at_index: 0, prompt: aiHookHandle.prompt.slice(0, 300), usd: SEEDANCE_720P_5S_USD },
        // KINEO1-IMAGEM-V2-2026-09-28 — no modo troca o clipe leva replace_index (posição no clip_urls ENTREGUE do stock que
        // ele substitui) e a duração pedida à fal; o custo é o de cada clipe (US$ 0,026/s).
        ...aiClipsSubmitted.map((c) => ({ request_id: c.requestId, scene: c.scene, at_index: keptBefore(sceneEvidence[c.scene - 1]?.from ?? 0), prompt: c.prompt.slice(0, 300), usd: c.usd ?? SEEDANCE_720P_5S_USD, ...(typeof c.replaceRaw === 'number' ? { replace_index: keptBefore(c.replaceRaw), seconds: c.seconds } : {}) })),
      ]
      const estUsd = Math.round((clips.reduce((a, c) => a + c.usd, 0) + aiStillsUsed * FIRST_FILM_STILL_USD) * 100) / 100
      await writeServerEvent({
        name: FIRST_FILM_AI_CLIPS_EVENT,
        userId: user.id,
        sessionId: generationId,
        path: '/api/generate-video-fast',
        metadata: { generation_id: generationId, clips: clips.slice(0, AI_CLIPS_PER_FILM_MAX), budget_usd: clipesNaCenaFraca ? KINEO1_AI_BUDGET_USD : FIRST_FILM_BUDGET_USD, est_usd: estUsd, stills_used: aiStillsUsed, scenes: scenes.length, clip_count: filtered.length, ...(clipesNaCenaFraca ? { version: 'kineo1_imagem_v2', stills_reserved_usd: reservaStillsUsd, weak_scenes: sceneEvidence.filter((e) => !!e.weak).map((e) => e.scene) } : {}) },
      })
      console.log(`[ai-clips] pending for compose: ${clips.length} clip(s) est=US$${estUsd} budget=US$${clipesNaCenaFraca ? KINEO1_AI_BUDGET_USD : FIRST_FILM_BUDGET_USD} scenes=${clips.map((c) => c.scene).join(',')} replace=${clips.filter((c) => 'replace_index' in c).map((c) => c.scene).join(',') || 'none'}`)
    }

    // Push #355 — Compute B-roll quality metrics and write to broll_metrics.
    // Best-effort: failures never block the video response.
    try {
      const totalSources = clipSources.filter((s) => s !== 'none').length || 1
      const countOf = (src: ClipSource) => clipSources.filter((s) => s === src).length
      const brollSourceDistribution = {
        pixabay:      parseFloat((countOf('pixabay')      / totalSources).toFixed(3)),
        fallbackA:    parseFloat((countOf('fallbackA')    / totalSources).toFixed(3)),
        stockLibrary: parseFloat((countOf('stockLibrary') / totalSources).toFixed(3)),
      }

      const uniqueClipsCount = new Set(filtered).size

      // Average relevance score across scenes that have one (from BrollPlan).
      const relevanceScores = Array.from(brollSceneMap.values())
        .map((m) => m.relevanceScore)
        .filter((s): s is number => typeof s === 'number')
      const relevanceScoreAvg =
        relevanceScores.length > 0
          ? relevanceScores.reduce((a, b) => a + b, 0) / relevanceScores.length
          : null

      const { error: metricsErr } = await supabase
        .from('broll_metrics')
        .insert({
          generation_id:            generationId,
          user_id:                  user.id,
          broll_source_distribution: brollSourceDistribution,
          unique_clips_count:       uniqueClipsCount,
          relevance_score_avg:      relevanceScoreAvg,
          degraded_reason:          degradedReason, // #358 instrumentation
        })

      if (metricsErr) {
        // PASSO 3 (20260530) — never fail silently. Capture the full PostgREST
        // error (code/message/details/hint) explicitly so broll_metrics insert
        // failures are traceable in logs. Still non-blocking by design: a metrics
        // write must never stop the user's video from being delivered.
        console.error('[broll_metrics] insert failed:', JSON.stringify({
          code: (metricsErr as { code?: string }).code,
          message: metricsErr.message,
          details: (metricsErr as { details?: string }).details,
          hint: (metricsErr as { hint?: string }).hint,
          generation_id: generationId,
          user_id_prefix: user.id.slice(0, 8),
        }))
      } else {
        console.log(
          `[broll_metrics] inserted generation_id=${generationId}`,
          JSON.stringify({ brollSourceDistribution, uniqueClipsCount, relevanceScoreAvg }),
        )
      }
    } catch (metricsEx) {
      // PASSO 3 (20260530) — escalate the thrown case to console.error too so
      // an unexpected exception in the metrics path is never swallowed silently.
      console.error('[broll_metrics] compute/insert threw:', metricsEx instanceof Error ? metricsEx.message : String(metricsEx))
    }

    // Push #132 — assemble the caption/voiceover pipeline. Each scene now
    // carries the SAME source string for both: the per-scene `voiceover` is
    // the narration TTS will read, and the per-scene `caption` is its
    // <=8-word readable on-screen paraphrase. We log both so any future
    // drift between captions and narration is debuggable from server logs.
    const sceneCaptions = scenes.map((s) => s.caption)
    // Push #235 — in verbatim mode the spoken text is the user's own narration
    // (markers/directives already stripped by the parser). Prefer it so what is
    // narrated is exactly what the user wrote; otherwise join the scene lines.
    const sceneJoinedVoiceover = scenes
      .map((s) => s.voiceover)
      .filter((v) => typeof v === 'string' && v.trim().length > 0)
      .join(' ')
    const voiceoverScript =
      ownScript ? falaPropria : sceneJoinedVoiceover // KINEO1-VERBATIM-ESTICA: prosa própria também é narrada como está

    console.log(
      '[generate-fast] scenes:',
      JSON.stringify(
        scenes.map((s, i) => ({
          scene: i + 1,
          voiceover: s.voiceover,
          caption: s.caption,
        })),
      ),
    )

    console.log(
      `[generate-fast] OK user=${user.id.slice(0, 8)} clips=${filtered.length} duration=${duration}s captions=${sceneCaptions.length}`
    )

    // ═══ KINEO-ENTREGA-SERVIDOR-2026-09-09 — O FILME DEIXA DE DEPENDER DA ABA
    //
    // O DEFEITO, medido na auditoria desta noite (14 dias, contas externas):
    // 280 pessoas apertaram Generate, 50 não receberam filme, e a MAIOR fatia
    // — 22 pessoas — não tem NENHUM erro registrado e NENHUMA tela de falha.
    // O rastro típico (pessoa `1968136d`, 06/09, vinda do ChatGPT): despacho
    // 07:21:19 · `generation_dispatch_received` 07:21:27 · aba embora 07:21:45
    // · nunca mais nada.
    //
    // O mecanismo estava aqui, logo abaixo: esta rota trabalha 30-40s e
    // termina devolvendo o payload COMPLETO do compose. O checkpoint durável
    // (`/api/render-recovery`, KINEO-RECOVERY-2026-09-06) só nasce quando o
    // CLIENTE recebe essa resposta e a reenvia. Se a aba morreu enquanto o
    // servidor trabalhava, a resposta cai no vazio: clipes buscados e script
    // pronto EVAPORAM, nenhum checkpoint existe, a fase 4 do cron é cega — o
    // remédio dependia do sobrevivente para socorrer o afogado.
    //
    // Agora o checkpoint nasce AQUI, do lado que sobreviveu, no instante em
    // que o payload existe e antes de qualquer coisa poder se perder.
    //
    // ⚠️ NÃO MUDA UM FIO DO FILME: mesmo `sanitizeFastComposePayload` que a
    // rota do cliente usa, mesmos campos, mesma fase 4, mesmo `/api/compose`
    // com custo por tier, recusa por saldo e claim assinado. Prompt de cena,
    // contrato, régua de voz, planner, motor e crédito ficam intocados. O que
    // muda é só QUEM grava o bilhete, e quando.
    //
    // ⚠️ `source:'server'` NÃO é decoração: é o que deixa o checkpoint do
    // cliente substituir este quando a aba está viva (render-recovery), e é o
    // corte pelo qual esta entrega se mede — campo novo, nunca relógio.
    //
    // Fire-and-forget: telemetria e rede de segurança não atrasam nem
    // derrubam um render que já deu certo.
    const recoveryPayload = sanitizeFastComposePayload(generationId, {
      quality: 'fast',
      clip_urls: filtered,
      duration,
      voiceover_script: voiceoverScript,
      scene_captions: sceneCaptions,
      topic: prompt,
      language: narrationLanguage.language,
      ...(parsedScript.speed != null ? { speed: parsedScript.speed } : {}),
    })
    if (recoveryPayload) {
      // KINEO-1-COERENCIA-2026-09-16 — ERA `void`: a resposta saía na linha seguinte, a Vercel congelava a função e o
      // insert morria no ar na maioria das vezes. Medido hoje (8 dias): 80 checkpoints do cliente contra 8 do servidor
      // — e o filme "3 AM rule" de wisadot849 às 18:34 terminou OK no servidor, a aba já tinha ido embora, e nada
      // ficou (a pessoa voltou e gerou "The incredible true story of" sozinho). Esperar ~80 ms de um insert é o
      // preço de o remédio existir.
      await writeServerEvent({
        name: RECOVERABLE_EVENT,
        userId: user.id,
        sessionId: generationId,
        metadata: {
          payload: recoveryPayload,
          clips: (recoveryPayload.clip_urls as string[]).length,
          source: 'server',
          // PEDIDO-REPETIDO-2026-09-24 — o que um pedido gêmeo precisa para devolver o MESMO filme ao navegador.
          fingerprint: pedidoDigital,
          verbatim: ownScript,
          speed: ownScript ? (parsedScript.speed ?? 1) : parsedScript.speed,
          scenes: scenes.map((sc) => sc.description).slice(0, 24),
          ai_scene_index: clipSources[0] === 'aiHook' ? 0 : null,
        },
      })
    }

    // Client expects `scenes` to be a string array of descriptions for the
    // result-page recap UI — flatten before serializing. We also surface
    // `scene_captions` and `voiceover_script` so the compose request can
    // be assembled with the per-scene caption pipeline as the single source
    // of truth.
    return NextResponse.json({
      mode: 'fast',
      generationId,
      prompt,
      duration,
      scenes: scenes.map((s) => s.description), // client still gets string array
      scene_captions: sceneCaptions,
      voiceover_script: voiceoverScript,
      clip_urls: filtered,
      // Push #235 — when the user authored the script verbatim, tell the client
      // so it forwards this narration (not the analyze-idea brief) and the
      // requested TTS speed to /api/compose.
      verbatim: ownScript, // KINEO1-VERBATIM-ESTICA: prosa própria viaja como verbatim (o compose pula o escalador)
      // KINEO-VERBATIM-NAO-REESCREVE-2026-09-12 — "as is" sem `speed:` viajava sem
      // speed e o compose reescrevia o corpo do texto do cliente. Verbatim agora
      // sempre leva um speed (1,0 por padrão) e o compose pula o escalador.
      speed: ownScript ? (parsedScript.speed ?? 1) : parsedScript.speed,
      // KINEO-AI-SCENE-VISIBLE-2026-08-03 — POR QUE ISTO EXISTE.
      // Todo PRIMEIRO vídeo de usuário free já recebe uma cena de abertura
      // GERADA POR IA (Seedance 1.5 Pro, ~$0.22 de provider) — e medimos em
      // 03/08 que esse hook é 100% do nosso gasto no fal. O usuário nunca soube:
      // via uma abertura linda e assumia que era sorte do banco de imagens.
      // Pagávamos pela demonstração do produto PAGO e jogávamos fora o argumento
      // de venda. Agora o cliente recebe o flag e a tela de resultado pode dizer
      // "esta cena foi gerada por IA — o Creator gera o vídeo inteiro assim".
      // Custo incremental: zero. É a prova do upgrade dentro do vídeo dele,
      // com o tema dele.
      ai_scene_index: clipSources[0] === 'aiHook' ? 0 : null,
    })
  } catch (error: unknown) {
    const msg = error instanceof Error ? error.message : String(error)
    console.error('[generate-fast] unexpected error:', msg)
    // PUSH #96 — the catch-all was completely silent in the funnel. The user id
    // is not available here (the throw may predate auth), and the message is
    // deliberately NOT recorded because it can echo request content; the error
    // name alone is enough to group these.
    recordFastFailure('generating', 'unhandled_exception', 500, null, {
      error_name: error instanceof Error ? error.name : 'unknown',
    })
    return NextResponse.json(
      { error: 'Something went wrong. Please try again.' },
      { status: 500 }
    )
  }
}

app/api/kids-cartoon/story/route.ts.before:
// KINEO-BEBE-QUE-FALA-2010 — POST /api/kids-cartoon/story: escreve a HISTÓRIA do "AI Kids Cartoon Stories" (template de 1 clique).
//
// Não cobra nada e não gera vídeo: valida o pedido no servidor (personagem/língua/duração/ideia da lista fechada de
// lib/kidsCartoon/kidsCartoon.ts), passa a ideia pela moderação da casa (moderateTopic + moderateContent) e pela regra extra
// "conteúdo inocente para criança", escreve a narração (gpt-4o, régua do Seedance 1.5 = lib/scriptWriterRate, a MESMA do
// /api/generate-script), confere a saída de novo (tamanho, nome do personagem, regra infantil, moderação) e devolve o link do
// fluxo de filme de sempre: /generate no Seedance 1.5 com o roteiro "como está" e `kids_cartoon=<personagem>` — a rota do filme
// trava o estilo 3D e o personagem em TODA cena. O preço aparece só no botão de gerar de lá (o do Seedance para a duração).
//
// Interruptor: KIDS_CARTOON_LIVE=false → só as contas da casa (isInternalEmail); o resto recebe 404.
import { NextRequest, NextResponse } from 'next/server'
import { createClient } from '@/lib/supabase/server'
import { isInternalEmail } from '@/lib/internalAccounts'
import { openai, OPENAI_SCRIPT_TIMEOUT_MS } from '@/lib/openai'
import { AI_TEXT_MODELS } from '@/lib/aiModels'
import { writeServerEvent } from '@/lib/serverEvents'
import { moderateTopic } from '@/lib/safety/topicModeration'
import { moderateContent } from '@/lib/safety/contentModeration'
import { moderationRefusalMessage, moderationRefusalStatus } from '@/lib/safety/moderationPolicy'
import { minWordsFor, maxWordsFor, writerRateFor } from '@/lib/scriptWriterRate'
import { maxWordsForShortFilm, SEEDANCE_SHORT_SECONDS } from '@/lib/durationByEngine'
import {
  KIDS_CARTOON_LIVE,
  KIDS_REFUSAL_MESSAGE,
  kidsCartoonGenerateHref,
  kidsCartoonOn,
  kidsContentRefusal,
  kidsPostCaption,
  kidsStoryCheck,
  kidsStoryWriterPrompt,
  validateKidsCartoonRequest,
} from '@/lib/kidsCartoon/kidsCartoon'

export const maxDuration = 60
export const dynamic = 'force-dynamic'

const PATH = '/api/kids-cartoon/story'

/** A faixa de palavras do Seedance 1.5 na duração e na língua (a mesma conta do /api/generate-script para 'cinematic_ai'). */
function kidsStoryWordBand(duration: number, language: string, idea: string): { min: number; max: number } {
  const regua = writerRateFor('cinematic_ai', idea, language)
  const idioma = duration === SEEDANCE_SHORT_SECONDS ? language : undefined
  const min = minWordsFor(duration, regua.wordsPerSecond, regua.coverage, idioma)
  const teto = maxWordsFor(duration, regua.wordsPerSecond, regua.coverage, idioma)
  const max = duration === SEEDANCE_SHORT_SECONDS ? Math.min(teto, maxWordsForShortFilm(duration, language)) : teto
  return { min: Math.min(min, max), max }
}

export async function POST(req: NextRequest) {
  const supabase = createClient()
  const { data: { user } } = await supabase.auth.getUser()
  if (!user) return NextResponse.json({ error: 'You must be signed in.' }, { status: 401 })
  if (!kidsCartoonOn(KIDS_CARTOON_LIVE, isInternalEmail(user.email))) return NextResponse.json({ error: 'Not found.' }, { status: 404 })

  let raw: unknown
  try { raw = await req.json() } catch { return NextResponse.json({ error: 'Invalid request body.' }, { status: 400 }) }
  const v = validateKidsCartoonRequest(raw)
  if (!v.ok) return NextResponse.json({ error: v.error, field: v.field }, { status: 400 })
  const request = v.value
  const lang = request.language === 'pt' ? 'pt' : 'en'
  const recusa = async (status: number, error: string, reason: string, extra: Record<string, unknown> = {}) => {
    await writeServerEvent({ name: 'kids_cartoon_story_refused', userId: user.id, path: PATH, metadata: { reason, character: request.character, language: request.language, duration: request.duration, idea_id: request.ideaId, charged: false, ...extra } }).catch(() => false)
    return NextResponse.json({ error, reason, charged: false }, { status })
  }

  // 1. a regra extra para criança e a moderação da casa, ANTES do escritor
  const regraInfantil = kidsContentRefusal(request.idea)
  if (regraInfantil) return recusa(422, KIDS_REFUSAL_MESSAGE[lang], 'kids_rule', { category: regraInfantil })
  const tema = await moderateTopic({ entry: 'generate-script', userId: user.id, text: request.idea, language: request.language, meta: { product: 'kids_cartoon' } })
  if (!tema.ok) return recusa(tema.status, tema.message, 'topic_moderation', { category: tema.category })
  const entrada = await moderateContent({ surface: 'script', stage: 'input', userId: user.id, text: request.idea, meta: { route: PATH, product: 'kids_cartoon' } })
  if (!entrada.ok) return recusa(moderationRefusalStatus(entrada.reason), moderationRefusalMessage(entrada.reason), `moderation_${entrada.reason}`)

  // 2. o escritor (uma nova tentativa só quando o tamanho ou o nome falham; nunca quando a regra infantil falha)
  const band = kidsStoryWordBand(request.duration, request.language, request.idea)
  const { system, user: userMsg } = kidsStoryWriterPrompt({ request, minWords: band.min, maxWords: band.max })
  let script = ''
  let motivo = ''
  for (let tentativa = 0; tentativa < 2 && !script; tentativa++) {
    let texto = ''
    try {
      const completion = await openai.chat.completions.create(
        {
          model: AI_TEXT_MODELS.writer, // o escritor de roteiro da casa (gpt-4o hoje; a migração troca num lugar só)
          temperature: 0.8,
          max_tokens: 600,
          messages: [
            { role: 'system', content: system },
            { role: 'user', content: tentativa === 0 ? userMsg : `${userMsg}\n\nThe previous version was ${motivo.replace('_', ' ')}. Write it again: exactly between ${band.min} and ${band.max} words, and name the main character.` },
          ],
        },
        { timeout: OPENAI_SCRIPT_TIMEOUT_MS, maxRetries: 0 },
      )
      texto = completion.choices[0]?.message?.content?.trim() ?? ''
    } catch (err) {
      console.warn('[kids-cartoon/story] escritor falhou:', err instanceof Error ? err.message : String(err))
      return recusa(503, lang === 'pt' ? 'O escritor está ocupado agora. Nada foi cobrado — tente de novo em um minuto.' : 'The story writer is busy right now. Nothing was charged — try again in a minute.', 'writer_unavailable')
    }
    const conferida = kidsStoryCheck(texto, { character: request.character, minWords: band.min, maxWords: band.max })
    if (conferida.ok) { script = conferida.script; break }
    motivo = conferida.reason
    if (conferida.reason === 'not_innocent' || conferida.reason === 'empty') break
  }
  if (!script) return recusa(motivo === 'not_innocent' ? 422 : 502, motivo === 'not_innocent' ? KIDS_REFUSAL_MESSAGE[lang] : (lang === 'pt' ? 'Não saiu uma história boa desta vez. Nada foi cobrado — tente de novo.' : 'The story did not come out right this time. Nothing was charged — please try again.'), `writer_${motivo || 'failed'}`)

  // 3. a saída passa pela moderação de novo (falha fechada, como toda porta da casa)
  const saida = await moderateContent({ surface: 'script', stage: 'output', userId: user.id, text: script, meta: { route: PATH, product: 'kids_cartoon' } })
  if (!saida.ok) return recusa(moderationRefusalStatus(saida.reason), moderationRefusalMessage(saida.reason), `output_moderation_${saida.reason}`)

  const href = kidsCartoonGenerateHref({ script, request })
  if (!href) return recusa(502, lang === 'pt' ? 'A história saiu longa demais. Nada foi cobrado — tente de novo.' : 'The story came out too long. Nothing was charged — please try again.', 'handoff_too_long')
  await writeServerEvent({ name: 'kids_cartoon_story_written', userId: user.id, path: PATH, metadata: { character: request.character, language: request.language, duration: request.duration, idea_id: request.ideaId, words: script.split(/\s+/).length, band, charged: false } }).catch(() => false)
  return NextResponse.json({ script, href, caption: kidsPostCaption(request.language, request.character), band })
}

