              <p className="kkc-note">{t.storyHint} {t.rules}</p>
              {editedRefusal ? <p className="kkc-err" role="alert">{language === 'pt' ? KIDS_REFUSAL_MESSAGE.pt : KIDS_REFUSAL_MESSAGE.en}</p> : null}
              <div className="kkc-actions" style={{ marginTop: 10 }}>
