    try {
      const q = new URLSearchParams(window.location.search)
      if (q.get('bought')) setMsg({ ok: true, text: t.bought })
      else if (q.get('checkout_error')) setMsg({ ok: false, text: q.get('checkout_error') ?? t.err })
