export function kling25ApplyShotAxis(prompt: string, index: number, maxChars: number = KLING25_PROMPT_MAX_CHARS, caudaChars = 600): string {
  const eixo = kling25ShotAxis(index)
  const corpo = normalizarEspacos(prompt)
