export function kling25StripShotAxis(prompt: string): string {
  const texto = String(prompt ?? '')
  for (const eixo of KLING25_SHOT_AXES) {
    if (texto === eixo) return ''
    if (texto.startsWith(`${eixo}. `)) return texto.slice(eixo.length + 2)
  }
  return texto
}

