  const b = kidsNum(i.balance, l)
  if (i.balance < i.cost) {
    if (l === 'pt') return { enough: false, text: `Você precisa de ${c} ${cr} — você tem ${b}.` }
    if (l === 'es') return { enough: false, text: `Necesitas ${c} ${cr} — tienes ${b}.` }
