const TTS_FALLBACK_MAX_CHARS = 3800

/** O erro da TTS da OpenAI é apagão (429/5xx/conexão), veio RÁPIDO, e o plano B está ligado com FAL_KEY? */
export function ttsFallbackApplies(err: unknown, elapsedMs: number): boolean {
  if (!TTS_FALLBACK_ENABLED) return false
  if (!(elapsedMs < TTS_FALLBACK_MAX_ELAPSED_MS)) return false
  if (!process.env.FAL_KEY) return false
  return isOpenAiOutageError(err) || looksOpenAiQuotaDead(err)
}

/**
 * FIX-REVISAO-2 KINEO-PLANO-B-OPENAI-2026-09-28 — no PASSE CORRETIVO a OpenAI acabou de entregar a narração primária:
 * ela está de pé. Um 503 "overloaded" ou um 429 de RPM ali é passageiro, e a 2ª tentativa da OpenAI
 * (KINEO-CORRETIVO-TENTA-DE-NOVO-2026-09-15) devolve a voz da persona no ritmo certo — a 1ª versão trocava a voz do filme
 * pela MiniMax (outra voz, ~2,7 pal/s: 70 s num filme de 60) e mandava "Recarregar a OpenAI" ao fundador. Só a conta
 * SEM CRÉDITO (o que a OpenAI declara, ou o 429 sem pista, que nesta casa é saldo — openAiAlertKind) pula a 2ª tentativa
 * e vai direto à voz reserva; todo o resto segue o retry da origin/main e só cai na MiniMax se ele também falhar.
 */
export function ttsFallbackSkipsRetry(err: unknown): boolean {
  return looksOpenAiQuotaDead(err) && openAiAlertKind(err) === 'quota'
}

/** O corpo EXATO da rota /audio para a MiniMax 2.8 HD (nunca inventar parâmetro). */
export function ttsFallbackInput(text: string): { prompt: string; output_format: 'url'; language_boost: 'auto' } {
  return { prompt: text, output_format: 'url', language_boost: 'auto' }
}

/**
 * Sintetiza a narração pela MiniMax na fal e devolve o mp3 em Buffer (o que o compose espera).
 * FIX-REVISAO-2 — recusa da fal por SALDO (403 "User is locked. Reason: Exhausted balance", o ApiError do @fal-ai/client
 * traz a frase em body.detail) toca o alarme único de saldo (lib/falAlert, fonte 'tts_fallback') antes de relançar: o
 * compose segue o caminho de sempre (502 na primária, áudio original no corretivo), e o fundador sabe que a fal travou.
 */
export async function synthesizeTtsFallback(
  script: string,
  ctx: { userId?: string | null; generationId?: string | null } = {},
): Promise<Buffer> {
  try {
    return await sintetizaPelaFal(script)
  } catch (e) {
    await avisaSaldoDaFalNaVoz(e, ctx)
    throw e
  }
}

/** FIX-REVISAO-2 — o alarme de saldo da voz reserva: só com recusa de SALDO, com teto de espera, nunca lança. */
async function avisaSaldoDaFalNaVoz(e: unknown, ctx: { userId?: string | null; generationId?: string | null }): Promise<void> {
  try {
    if (!looksExhausted(e as Parameters<typeof looksExhausted>[0])) return
    console.error(`[tts-fallback] a fal recusou a voz reserva por SALDO (${TTS_FALLBACK_MODEL}) — alarme único de saldo da fal`)
    await settleWithin(FAL_BALANCE_ALARM_WAIT_MS, [
      alertFalExhausted({
        source: 'tts_fallback',
        engine: TTS_FALLBACK_MODEL,
        userId: ctx.userId ?? null,
        generationId: ctx.generationId ?? null,
        context: 'voz reserva do /api/compose: a TTS da OpenAI recusou e a MiniMax na fal recusou por saldo — o filme segue o caminho de sempre sem a voz reserva',
      }),
    ])
  } catch {
    // o alarme é anotação: nunca troca o erro que o compose recebe
  }
}

async function sintetizaPelaFal(script: string): Promise<Buffer> {
  const falKey = process.env.FAL_KEY
  if (!falKey) throw new Error('FAL_KEY is not set')
  // A mesma limpeza do generateTTS: o narrador nunca lê "[Pexels: …]", "HOOK" ou linha de "speed:".
  const cleaned = stripScriptMarkers(script)
  const text = (cleaned.length > TTS_FALLBACK_MAX_CHARS ? cleaned.slice(0, TTS_FALLBACK_MAX_CHARS) : cleaned).trim()
  if (!text) throw new Error('fallback TTS: narration is empty after marker strip')
  fal.config({ credentials: falKey })
  const result = (await fal.subscribe(TTS_FALLBACK_MODEL, {
    input: ttsFallbackInput(text),
    timeout: TTS_FALLBACK_TIMEOUT_MS,
  })) as { data?: { audio?: { url?: string } }; audio?: { url?: string } }
  const url = result?.data?.audio?.url ?? result?.audio?.url ?? null
  if (!url) throw new Error('fallback TTS returned no audio url')
  const res = await fetch(url, { signal: AbortSignal.timeout(TTS_FALLBACK_DOWNLOAD_MS) })
  if (!res.ok) throw new Error(`fallback TTS audio fetch failed: ${res.status}`)
  const buf = Buffer.from(await res.arrayBuffer())
  if (buf.length === 0) throw new Error('fallback TTS audio is empty')
  return buf
}

// ═══ KINEO-ATORES-IA-2026-10-13 — a voz ElevenLabs v3 do apresentador de IA escolhido no Studio Ads ═══════════════════
// O anúncio narra na MiniMax de sempre (synthesizeTtsFallback). Quando o anunciante escolhe na biblioteca um apresentador de
// voz ElevenLabs (lib/ads/v2Presenter.ts, ADS_V2_PRESENTER_LIBRARY: os homens e duas mulheres), a narração sai aqui: o MESMO
// motor e o MESMO corpo da rota /audio (app/api/audio/generate MODELS.eleven: { text, voice, stability: 0.5 }, vozes da lista
// fechada) — nenhum parâmetro inventado. Recusa por saldo toca o mesmo alarme único da fal.
export const ADS_PRESENTER_ELEVEN_MODEL = 'fal-ai/elevenlabs/tts/eleven-v3'
export const ADS_PRESENTER_ELEVEN_VOICES = ['Brian', 'Daniel', 'Aria', 'Jessica'] as const
/** O corpo EXATO da rota /audio para a ElevenLabs v3. */
export function elevenTtsInput(text: string, voice: (typeof ADS_PRESENTER_ELEVEN_VOICES)[number]): { text: string; voice: string; stability: number } {
  return { text, voice, stability: 0.5 }
}

/** A narração na voz ElevenLabs v3 (mp3 em Buffer). Voz fora da lista fechada = erro (nunca chega à fal). */
export async function synthesizeElevenVoice(
  script: string,
  voice: string,
  ctx: { userId?: string | null; generationId?: string | null } = {},
): Promise<Buffer> {
  if (!(ADS_PRESENTER_ELEVEN_VOICES as readonly string[]).includes(voice)) throw new Error(`eleven voice not allowed: ${voice}`)
  try {
    const falKey = process.env.FAL_KEY
    if (!falKey) throw new Error('FAL_KEY is not set')
    const cleaned = stripScriptMarkers(script)
    const text = (cleaned.length > TTS_FALLBACK_MAX_CHARS ? cleaned.slice(0, TTS_FALLBACK_MAX_CHARS) : cleaned).trim()
    if (!text) throw new Error('eleven TTS: narration is empty after marker strip')
    fal.config({ credentials: falKey })
    const result = (await fal.subscribe(ADS_PRESENTER_ELEVEN_MODEL, {
      input: elevenTtsInput(text, voice as (typeof ADS_PRESENTER_ELEVEN_VOICES)[number]),
      timeout: TTS_FALLBACK_TIMEOUT_MS,
    })) as { data?: { audio?: { url?: string } }; audio?: { url?: string } }
    const url = result?.data?.audio?.url ?? result?.audio?.url ?? null
    if (!url) throw new Error('eleven TTS returned no audio url')
    const res = await fetch(url, { signal: AbortSignal.timeout(TTS_FALLBACK_DOWNLOAD_MS) })
    if (!res.ok) throw new Error(`eleven TTS audio fetch failed: ${res.status}`)
    const buf = Buffer.from(await res.arrayBuffer())
    if (buf.length === 0) throw new Error('eleven TTS audio is empty')
    return buf
  } catch (e) {
    await avisaSaldoDaFalNaVoz(e, ctx)
    throw e
  }
}

/**
 * Evento `tts_fallback_used` + alarme ao fundador (mesmo limitador de 30 min por tipo), com o MESMO teto do plano B de
 * texto (settleWithin, 2,5 s): o compose aguarda isto depois do débito, e um Resend/Supabase travado no apagão não pode
 * segurar a narração que já saiu (revisão adversarial 28/09 — a 1ª versão aguardava sem teto).
 */
export async function registerTtsFallbackUse(args: {
  err: unknown
  stage: 'primary' | 'corrective'
  primaryMs: number
  ms: number
  bytes: number
  chars: number
  userId: string | null
  generationId: string | null
  quality: string | null
}): Promise<void> {
  const primaryStatus = primaryStatusOf(args.err)
  const kind: 'quota' | 'hang' | 'rate_limit' = looksOpenAiQuotaDead(args.err) ? openAiAlertKind(args.err) : 'hang'
  await settleWithin(FALLBACK_SIDE_EFFECTS_MS, [
    writeServerEvent({
      name: TTS_FALLBACK_EVENT,
      userId: args.userId,
      sessionId: args.generationId,
      path: '/api/compose',
      metadata: {
        stage: args.stage,
        model: TTS_FALLBACK_MODEL,
        primary_status: primaryStatus,
        primary_ms: args.primaryMs,
        ms: args.ms,
        bytes: args.bytes,
        chars: args.chars,
        quality: args.quality,
        generation_id: args.generationId,
        alert_kind: kind,
      },
    }),
    alertOpenAiExhausted(
      `PLANO B DE VOZ ATIVO (/api/compose, ${args.stage}): a TTS da OpenAI recusou (${String(primaryStatus)}) e a ` +
        `narração saiu pela ${TTS_FALLBACK_MODEL} na fal (${args.ms} ms). O filme segue, com outra voz e outro ritmo; ` +
        `cada narração agora gasta o saldo da fal. ` +
        // FIX-REVISAO-2 — "Recarregar" só quando foi crédito: num 5xx/rate limit o e-mail já diz que recarregar não resolve.
        (kind === 'quota' ? 'Recarregar a OpenAI.' : 'Não é falta de crédito: acompanhar https://status.openai.com/.'),
      kind,
    ),
  ])
}

